    @keyframes cook-food-flip {
        0%   { transform: translateY(0) scaleX(1); }
        30%  { transform: translateY(-50px) rotate(180deg) scaleX(1.1); }
        60%  { transform: translateY(0) rotate(360deg) scaleX(1); }
        100% { transform: translateY(0) rotate(360deg); }
    }
    @keyframes cook-pulse {
        0%, 100% { opacity: 0.5; }
        50%       { opacity: 1; }
    }

    #st-cooking-module {
        font-family: "Microsoft YaHei", sans-serif;
        width: 100%;
        max-width: 320px;
        margin: 0 auto;
        position: relative;
        box-sizing: border-box;
        user-select: none;
        -webkit-user-select: none;

        --bg-red: #87402D;
        --border-light: #A39685;
        --border-dark: #59473E;
        --inner-bg: #F2DEBD;
        --inner-stroke: #535343;
        --bar-yellow: #CF9940;
        --slot-size: 50px;
        --slot-gap: 8px;
    }

    img.emoji {
        height: 1.2em; width: 1.2em; margin: 0 .05em 0 .1em; vertical-align: -0.2em;
        pointer-events: none;
    }

    /* 修复③：移除固定宽高，改为 auto，防止内容被拉伸变形 */
    .th-drag-helper {
        position: fixed; pointer-events: none; z-index: 99999;
        opacity: 0.9; transform: scale(1.1);
        width: auto; 
        height: auto;
        display: flex; flex-direction: column; align-items: center; justify-content: center;
        font-size: 32px;
        background-color: transparent; border: none; box-shadow: none;
        filter: url(#emoji-outline); 
        pointer-events: none;
    }

    .cook-base-layer {
        background-color: var(--bg-red);
        border-radius: 6px;
        border: 4px solid var(--border-light);
        box-shadow: 0 0 0 2px var(--border-dark); 
        padding: 25px 12px 0 12px;
        position: relative;
        background-image: radial-gradient(#5e2d20 20%, transparent 20%);
        background-position: 0 0; background-size: 10px 10px;
        display: flex; flex-direction: column; gap: 0; 
    }

    .cook-title {
        position: absolute; top: -5px; left: 10px;
        width: 110px;
        height: 45px;
        background: url('https://img.baibai.cv/f/pXwQHE/%E6%96%99%E7%90%86%E5%8F%B0.png') left top / contain no-repeat;
        z-index: 10;
        overflow: hidden;
        text-indent: -9999px;
        white-space: nowrap;
    }

    .cook-subtitle {
        position: absolute; top: 32px; left: 130px; 
        font-size: 14px; font-weight: bold; color: #000;
        background: #F2DEBD; padding: 0 4px; border: 2px solid #000; border-radius: 4px;
    }

    .start-btn {
        position: absolute; top: 20px; right: -5px; 
        background-color: #163C9C; color: white;
        border: 2px solid #fff; border-radius: 4px;
        padding: 4px 12px; font-weight: bold; cursor: pointer;
        box-shadow: 2px 2px 0 rgba(0,0,0,0.5); z-index: 11;
        transition: transform 0.05s, box-shadow 0.05s;
    }
    .start-btn:active, .start-btn.animating { 
        transform: translate(2px, 2px); 
        box-shadow: none; 
    }

    .cook-inner-board {
        background-color: var(--inner-bg);
        border: 2px solid var(--inner-stroke);
        border-radius: 6px 6px 0 0;
        border-bottom: none;
        height: 340px; 
        display: flex; flex-direction: column;
        overflow: hidden;
        z-index: 5;
    }

    .board-section {
        padding: 10px; flex: 1; display: flex; flex-direction: column;
        min-height: 0; 
    }

    .section-label { 
        font-size: 16px; font-weight: bold; color: #8f7e63; margin-bottom: 5px; flex-shrink: 0; 
        padding-left: 5px; 
    }

    .grid-container {
        display: grid;
        grid-template-columns: repeat(4, var(--slot-size)); 
        grid-auto-rows: var(--slot-size);
        gap: var(--slot-gap);
        justify-content: center;
        align-content: center;
        padding: 5px 0;
        width: 100%; height: 100%; 
        overflow: hidden;
    }

    .grid-slot {
        width: var(--slot-size); height: var(--slot-size);
        border-radius: 8px;
        background-color: rgba(0,0,0,0.05);
        border: 2px dashed rgba(83, 83, 67, 0.2);
        display: flex; align-items: center; justify-content: center;
        position: relative; flex-shrink: 0; 
        overflow: visible; 
        z-index: 1;
    }
    .grid-slot.highlight {
        background-color: rgba(135, 64, 45, 0.2);
        border-color: var(--bg-red);
    }

    .divider-dashed {
        height: 2px;
        background-image: linear-gradient(to right, #CBB69E 60%, rgba(255,255,255,0) 0%);
        background-size: 10px 2px; margin: 0 10px; flex-shrink: 0;
    }

    .inventory-container {
        position: relative; 
        width: auto; 
        margin-left: -16px; margin-right: -16px; margin-bottom: 0; 
        top: 2px;
        z-index: 20;
        height: 85px; 
    }

    .inventory-bar {
        background-color: var(--bar-yellow);
        border: 4px solid #A39685;
        box-shadow: inset 0 0 0 2px #2A2F20;
        border-radius: 0 0 12px 12px;
        height: 100%; width: 100%; box-sizing: border-box;
        display: flex; 
        align-items: flex-start; 
        padding-top: 12px;
        gap: 15px; 
        overflow-x: auto;
        overflow-y: hidden;
        padding-left: 100px; 
        padding-right: 15px;

        /* ② 修改：显示细滚动条，配色匹配界面 */
        scrollbar-width: thin;
        scrollbar-color: #8B5E3C #b8892a;

        touch-action: pan-x;
    }

    /* ② 修改：Webkit 滚动条样式（电脑端横向，细且配色） */
    .inventory-bar::-webkit-scrollbar {
        display: block;
        height: 4px; /* 横向滚动条高度，较细 */
        width: auto;
    }
    .inventory-bar::-webkit-scrollbar-track {
        background: #b8892a;
        border-radius: 2px;
    }
    .inventory-bar::-webkit-scrollbar-thumb {
        background: #59473E;
        border-radius: 2px;
    }
    .inventory-bar::-webkit-scrollbar-thumb:hover {
        background: #87402D;
    }

    .toggle-icon {
        position: absolute; 
        width: 140px; 
        height: 90px;
        left: -25px; 
        bottom: 0px; 
        display: flex; align-items: center; justify-content: center;
        cursor: pointer; z-index: 30;
        transition: transform 0.1s;
        filter: drop-shadow(2px 2px 2px rgba(0,0,0,0.3));
    }
    .toggle-icon:active { transform: scale(0.9); }
    .toggle-icon img {
        width: 100%;
        height: 100%;
        object-fit: contain;
        pointer-events: none;
    }

    .item-obj {
        width: 54px;
        height: auto; 
        min-height: 50px;
        background-color: transparent; border: none; box-shadow: none;
        display: flex; 
        flex-direction: column; 
        align-items: center; 
        justify-content: flex-start; 
        cursor: grab; z-index: 5; flex-shrink: 0;
        overflow: visible; 
        font-size: 32px; 
        filter: url(#emoji-outline);
        transition: transform 0.1s;
    }

    .inventory-bar .item-obj {
        padding-top: 4px;
    }

    .grid-slot .item-obj {
        margin-top: 2px;
    }

    .item-obj.is-pressed {
        transform: scale(0.9);
    }

    .item-obj img.emoji {
        width: 28px !important;       
        height: 28px !important;
        max-width: none !important; 
        max-height: none !important;
        min-width: 28px !important;
        min-height: 28px !important;
        flex-shrink: 0 !important;
        margin-bottom: 0px;
    }

    .item-name {
        font-size: 10px;
        font-weight: 900;
        color: #5e2d20;
        text-align: center;
        line-height: 1.1;
        width: 100%;
        white-space: normal;
        overflow: visible;
        text-overflow: clip;
        pointer-events: none; 
        text-shadow: 1px 1px 0 #fff, -1px -1px 0 #fff, 1px -1px 0 #fff, -1px 1px 0 #fff; 
        margin-top: 2px;
    }

    .item-obj:active { cursor: grabbing; }
    .item-obj.is-dragging { opacity: 0.3; }

    .cook-tooltip {
        position: fixed;
        background: rgba(0,0,0,0.85); color: white; padding: 6px 10px;
        border-radius: 6px; font-size: 14px; pointer-events: none; z-index: 100000;
        display: none; white-space: nowrap; border: 1px solid #ffd700;
        box-shadow: 0 4px 8px rgba(0,0,0,0.4);
        transform: translateX(-50%);
    }


    /* 前后置情节输入框：白字黑描边，适配任意酒馆背景 */
    .cook-float-text {
        color: #fff !important;
        caret-color: #fff;
        background: transparent !important;
        text-shadow:
            1px 0 0 #000,
            -1px 0 0 #000,
            0 1px 0 #000,
            0 -1px 0 #000,
            1px 1px 0 #000,
            -1px -1px 0 #000,
            1px -1px 0 #000,
            -1px 1px 0 #000;
    }

    .cook-float-text::placeholder {
        color: #fff !important;
        opacity: 0.62;
        text-shadow:
            1px 0 0 #000,
            -1px 0 0 #000,
            0 1px 0 #000,
            0 -1px 0 #000,
            1px 1px 0 #000,
            -1px -1px 0 #000,
            1px -1px 0 #000,
            -1px 1px 0 #000;
    }</style>
</head>
<body>

<svg style="width:0;height:0;position:absolute;" aria-hidden="true" focusable="false">
  <filter id="emoji-outline">
    <feMorphology in="SourceAlpha" operator="dilate" radius="2" result="dilatedWhite" />
    <feFlood flood-color="white" flood-opacity="1" result="floodWhite" />
    <feComposite in="floodWhite" in2="dilatedWhite" operator="in" result="outlineWhite" />
    <feMorphology in="SourceAlpha" operator="dilate" radius="1" result="dilatedBlack" />
    <feFlood flood-color="black" flood-opacity="1" result="floodBlack" />
    <feComposite in="floodBlack" in2="dilatedBlack" operator="in" result="outlineBlack" />
    <feMerge>
        <feMergeNode in="outlineWhite" />
        <feMergeNode in="outlineBlack" />
        <feMergeNode in="SourceGraphic" />
    </feMerge>
  </filter>
</svg>

<textarea class="cook-float-text" id="cook-prelude" placeholder="可以在此处输入前置情节(如有)" rows="2"></textarea>
<div id="st-cooking-module">
    <div class="cook-title">料理台</div>
    <div class="cook-subtitle">kitchen counter</div>
    <button class="start-btn">开工!</button>

    <div class="cook-base-layer">

        <div class="cook-overlay" id="cook-overlay">
            <div class="cooking-loader">
                <div class="cook-food"></div>
                <div class="cook-pan"></div>
                <div class="cook-loading-text">COOKING...</div>
            </div>
        </div>

        <div class="cook-inner-board">
            <div class="board-section" style="flex: 0 0 auto; height: 105px;">
                <div class="section-label">工具:</div>
                <div class="grid-container" id="grid-tools" style="overflow-y: hidden;"></div>
            </div>

            <div class="divider-dashed"></div>

            <div class="board-section" style="flex: 1; overflow: hidden;">
                <div class="section-label">烹饪:</div>
                <div class="grid-container" id="grid-cooking"></div>
            </div>
        </div>

        <div class="inventory-container">
            <div class="toggle-icon" id="toggle-btn">
                <img src="https://i.postimg.cc/fTLDqVwZ/mmexport1767799910243.png" alt="切换">
            </div>

            <div class="inventory-bar" id="inv-page-1">
                </div>

            <div class="inventory-bar" id="inv-page-2" style="display:none;">
                </div>
        </div>

    </div>
</div>
<textarea class="cook-float-text" id="cook-epilogue" placeholder="可以在此处输入后置情节(如有)，点击【开工!】继续剧情" rows="2"></textarea>
<div id="cook-tooltip" class="cook-tooltip"></div>

<script>
(function() {
    // === 数据定义 ===
    const COOKING_METHODS = [
        { name: "炖煮", icon: "🍲", desc: "长时间慢火烹调" },
        { name: "炒", icon: "🍳", desc: "大火快炒" },
        { name: "烤", icon: "🔥", desc: "直接火烤" },
        { name: "切", icon: "🔪", desc: "处理食材形状" },
        { name: "生腌", icon: "🦐", desc: "酒或酱油腌制生食" },
        { name: "凉拌", icon: "🥣", desc: "加入调料搅拌" },
        { name: "炸", icon: "🍤", desc: "放入热油炸制" },
        { name: "蒸", icon: "💧", desc: "水蒸气加热" },
        { name: "煎", icon: "🍳", desc: "平底锅煎制" },
        { name: "焖", icon: "🥘", desc: "加盖微火焖熟" }
    ];

    // === 联动读取背包数据 ===
    const getInventory = () => {
        if (window.TavernHelper) {
            const allData = TavernHelper.getVariables();
            const rawList = allData.inventory_data || [];
            const hiddenList = allData.inventory_storage_list || [];
            return rawList.filter(i => !hiddenList.includes(i.id));
        }
        return []; 
    };

    const toolsGrid = document.getElementById('grid-tools');
    const cookingGrid = document.getElementById('grid-cooking');
    const page1 = document.getElementById('inv-page-1');
    const page2 = document.getElementById('inv-page-2');
    const tooltip = document.getElementById('cook-tooltip');

    for(let i=0; i<4; i++) {
        let slot = document.createElement('div');
        slot.className = 'grid-slot'; toolsGrid.appendChild(slot);
    }
    for(let i=0; i<12; i++) {
        let slot = document.createElement('div');
        slot.className = 'grid-slot'; cookingGrid.appendChild(slot);
    }

    // === 核心功能：造句逻辑 & 发送 ===
    const startBtn = document.querySelector('.start-btn');
    startBtn.addEventListener('click', async () => {
        startBtn.classList.add('animating');
        const overlay = document.getElementById('cook-overlay');
        overlay.classList.add('active');

        setTimeout(async () => {
            startBtn.classList.remove('animating');

            const tools = [];
            document.querySelectorAll('#grid-tools .item-obj').forEach(el => tools.push(el.dataset.name));

            const slots = document.querySelectorAll('#grid-cooking .grid-slot');
            let actions = [];
            let tempIngredients = []; 

            slots.forEach(slot => {
                if (slot.children.length > 0) {
                    const el = slot.children[0];
                    const name = el.dataset.name;
                    const type = el.dataset.type;

                    if (type === 'item') {
                        tempIngredients.push(name);
                    } else if (type === 'method') {
                        if (tempIngredients.length > 0) {
                            actions.push(`使用${name}方式处理${tempIngredients.join('、')}`);
                            tempIngredients = []; 
                        } else {
                            actions.push(`进行${name}操作`);
                        }
                    }
                }
            });

            if (tempIngredients.length > 0) {
                actions.push(`还使用了${tempIngredients.join('、')}`);
            }

            if (actions.length === 0 && tools.length === 0) {
                alert("请至少放入一些食材或工具！");
                return;
            }

            let sentence = `{{user}}开始烹饪：`;
            if (tools.length > 0) sentence += `借助${tools.join('、')}，`;
            if (actions.length > 0) sentence += actions.join('，') + "。";
            sentence += "最后完成了菜品。\n<!-- request:请展开描述烹饪过程与成品（叙述技法可参考文学作品《雅舍谈吃》、《老味道》、《迷宫饭》）。食材和工具来自<Item_List>，消耗遵循<Item_Rules>要求格式，进行对应食材的删改（如工具一般无需修改，而食材应该有相应的库存变动修改（MOD）或彻底用完（DEL）；鼓励生成至少一个关于成品的成就(成就名称为菜品名，如厚切培根蔬菜浓汤、班尼迪克蛋、炎龙肉套餐)) -->";

            const prelude = document.getElementById('cook-prelude').value.trim();
            const epilogue = document.getElementById('cook-epilogue').value.trim();
            let combined = '';
            if (prelude) combined += prelude + '\n\n';
            combined += sentence;
            if (epilogue) combined += '\n\n' + epilogue;

            if (typeof getChatMessages !== 'undefined' && typeof setChatMessages !== 'undefined' && typeof triggerSlash !== 'undefined') {
                try {
                    const msgs = await getChatMessages(-1);
                    if (!msgs || msgs.length === 0) throw new Error("未找到当前楼层");
                    const lastMsg = msgs[0];
                    const newContent = lastMsg.message + "\n\n" + combined;
                    await setChatMessages([{
                        message_id: lastMsg.message_id,
                        message: newContent
                    }], { refresh: 'none' });
                    await triggerSlash('/trigger');
                    // 遮罩由widget重渲染自动消失，无需手动移除
                } catch (e) {
                    overlay.classList.remove('active'); // 出错时手动撤掉
                    console.error(e);
                    alert("发送失败: " + e.message);
                }
            } else {
                alert("未检测到酒馆API，生成文本:\n" + combined);
            }
        }, 250);
    });

    // === 拖拽逻辑 ===
    let dragItem = null; 
    let dragHelper = null;
    let isDragging = false;
    let dragTimer = null;
    let isTouch = false; // 区分触摸/鼠标
    let startX = 0, startY = 0; 
    let dragOrigin = { parent: null, nextSibling: null };

    let cachedSlots = [];
    let cachedBarRect = null;

    const enableWheelHorizontalScroll = (bar) => {
        bar.addEventListener('wheel', (e) => {
            if (isDragging || e.ctrlKey) return;
            if (!e.deltaY || Math.abs(e.deltaX) > Math.abs(e.deltaY)) return;

            const maxScrollLeft = bar.scrollWidth - bar.clientWidth;
            if (maxScrollLeft <= 0) return;

            let scrollAmount = e.deltaY;
            if (e.deltaMode === 1) scrollAmount *= 16;
            if (e.deltaMode === 2) scrollAmount *= bar.clientWidth;

            const direction = scrollAmount > 0 ? 1 : -1;
            const atStart = bar.scrollLeft <= 0;
            const atEnd = bar.scrollLeft >= maxScrollLeft - 1;
            if ((direction < 0 && atStart) || (direction > 0 && atEnd)) return;

            e.preventDefault();
            bar.scrollLeft += scrollAmount;
        }, { passive: false });
    };
    [page1, page2].forEach(enableWheelHorizontalScroll);
    const createItemEl = (data, type) => {
        const el = document.createElement('div');
        el.className = 'item-obj';

        const emojiSpan = document.createElement('span');
        emojiSpan.textContent = data.icon;
        const nameSpan = document.createElement('span');
        nameSpan.className = 'item-name';
        nameSpan.textContent = data.name;

        el.appendChild(emojiSpan);
        el.appendChild(nameSpan);

        el.dataset.name = data.name;
        el.dataset.desc = data.desc;
        el.dataset.type = type; 

        bindEventsToItem(el);
        return el;
    };

    function bindEventsToItem(item) {
        item.addEventListener('touchstart', handleInputStart, {passive: false});
        item.addEventListener('mousedown', handleInputStart);
        item.oncontextmenu = function(e) { e.preventDefault(); e.stopPropagation(); return false; };
        item.addEventListener('mouseenter', () => { if(!isDragging) showTooltip(item, item.dataset.desc); });
        item.addEventListener('mouseleave', hideTooltip);
    }

    function showTooltip(targetElement, text) {
        if(isDragging) return;
        tooltip.textContent = text;
        tooltip.style.display = 'block';
        const rect = targetElement.getBoundingClientRect();
        tooltip.style.left = (rect.left + rect.width / 2) + 'px';
        tooltip.style.top = (rect.top - 48) + 'px'; 
    }

    function updateTooltipPos(x, y) {
        tooltip.style.left = x + 'px';
        tooltip.style.top = (y - 48) + 'px';
    }

    function hideTooltip() {
        if (isDragging) return; 
        tooltip.style.display = 'none';
    }

    function handleInputStart(e) {
        if (isDragging || (e.button && e.button !== 0)) return;

        const evt = (e.touches) ? e.touches[0] : e;
        const target = e.currentTarget;

        startX = evt.clientX;
        startY = evt.clientY;
        dragItem = target;
        isTouch = !!e.touches; // 记录本次是触摸还是鼠标

        dragItem.classList.add('is-pressed');

        // 鼠标：20ms 快速响应；触摸：80ms 防止与横向滑动冲突
        const delay = isTouch ? 80 : 20;
        dragTimer = setTimeout(() => {
            startDragLogic(evt);
        }, delay);

        document.addEventListener('mousemove', handleInputMove);
        document.addEventListener('touchmove', handleInputMove, {passive: false});
        document.addEventListener('mouseup', handleInputEnd);
        document.addEventListener('touchend', handleInputEnd);
    }

    function startDragLogic(evt) {
        isDragging = true;

        dragOrigin.parent = dragItem.parentNode;
        dragOrigin.nextSibling = dragItem.nextSibling;

        if (dragItem.dataset.type === 'method' && dragItem.parentNode.id === 'inv-page-2') {
             const clone = dragItem.cloneNode(true);
             clone.classList.remove('is-pressed');
             bindEventsToItem(clone); 
             dragItem.parentNode.insertBefore(clone, dragItem); 
             dragOrigin.parent = null; 
        }

        dragHelper = dragItem.cloneNode(true);
        dragHelper.className = 'th-drag-helper';
        dragHelper.classList.remove('is-pressed');
        document.body.appendChild(dragHelper);
        dragItem.classList.add('is-dragging');
        dragItem.classList.remove('is-pressed');

        dragHelper.style.left = (evt.clientX - 24) + 'px';
        dragHelper.style.top = (evt.clientY - 24) + 'px';

        tooltip.textContent = dragItem.dataset.desc;
        tooltip.style.display = 'block';
        updateTooltipPos(evt.clientX, evt.clientY);

        cacheLayout();
    }

    function cacheLayout() {
        cachedSlots = [];
        document.querySelectorAll('.grid-slot').forEach(slot => {
            cachedSlots.push({
                el: slot,
                rect: slot.getBoundingClientRect()
            });
        });
        const visibleBar = page1.style.display !== 'none' ? page1 : page2;
        cachedBarRect = {
            el: visibleBar,
            rect: visibleBar.getBoundingClientRect()
        };
    }

    function handleInputMove(e) {
        const evt = (e.touches) ? e.touches[0] : e;

        if (!isDragging) {
            const moveX = evt.clientX - startX;
            const moveY = evt.clientY - startY;
            const distance = Math.hypot(moveX, moveY);

            // 鼠标：3px 即取消（精准操作）；触摸：8px 容忍小幅抖动，避免过早取消长按
            const cancelThreshold = isTouch ? 8 : 3;
            if (distance > cancelThreshold) {
                if (dragTimer) {
                    clearTimeout(dragTimer);
                    dragTimer = null;
                }
                if (dragItem) dragItem.classList.remove('is-pressed');
            }
            return;
        }

        if (e.cancelable) e.preventDefault();

        if(dragHelper) {
            dragHelper.style.left = (evt.clientX - 24) + 'px';
            dragHelper.style.top = (evt.clientY - 24) + 'px';
        }
        updateTooltipPos(evt.clientX, evt.clientY);

        const prevHighlight = document.querySelector('.grid-slot.highlight');
        if(prevHighlight) prevHighlight.classList.remove('highlight');
        if(cachedBarRect && cachedBarRect.el) cachedBarRect.el.style.backgroundColor = '';

        let highlightDone = false;

        if (cachedBarRect) {
            const r = cachedBarRect.rect;
            if (evt.clientX >= r.left && evt.clientX <= r.right &&
                evt.clientY >= r.top && evt.clientY <= r.bottom) {
                 cachedBarRect.el.style.backgroundColor = '#e0b060';
                 highlightDone = true;
            }
        }

        if (!highlightDone) {
            for(let item of cachedSlots) {
                const r = item.rect;
                if (evt.clientX >= r.left && evt.clientX <= r.right &&
                    evt.clientY >= r.top && evt.clientY <= r.bottom) {
                    item.el.classList.add('highlight');
                    break; 
                }
            }
        }
    }

    function handleInputEnd(e) {
        if (dragTimer) {
            clearTimeout(dragTimer);
            dragTimer = null;
        }

        if (dragItem) dragItem.classList.remove('is-pressed');

        tooltip.style.display = 'none';

        document.removeEventListener('mousemove', handleInputMove);
        document.removeEventListener('touchmove', handleInputMove);
        document.removeEventListener('mouseup', handleInputEnd);
        document.removeEventListener('touchend', handleInputEnd);

        if (!isDragging) {
            dragItem = null;
            return;
        }

        isDragging = false;

        cachedSlots = [];
        cachedBarRect = null;

        let clientX, clientY;
        if (e.changedTouches) {
            clientX = e.changedTouches[0].clientX; clientY = e.changedTouches[0].clientY;
        } else {
            clientX = e.clientX; clientY = e.clientY;
        }

        let dropped = false;

        const visibleBar = page1.style.display !== 'none' ? page1 : page2;
        const barRect = visibleBar.getBoundingClientRect();

        const inInventoryZone = (clientX >= barRect.left && clientX <= barRect.right &&
                                 clientY >= barRect.top && clientY <= barRect.bottom);

        if (inInventoryZone) {
            if (dragItem.dataset.type === 'method') {
                dragItem.remove();
                dropped = true;
            } else {
                const targetHomeId = dragItem.dataset.home === 'page-1' ? 'inv-page-1' : 'inv-page-2';
                document.getElementById(targetHomeId).appendChild(dragItem);
                dropped = true;
            }
        } 
        else {
            const slots = document.querySelectorAll('.grid-slot');
            for (let slot of slots) {
                const rect = slot.getBoundingClientRect();
                if (clientX >= rect.left && clientX <= rect.right &&
                    clientY >= rect.top && clientY <= rect.bottom) {

                    if (slot.children.length > 0) {
                         const existingItem = slot.children[0];
                         if (existingItem.dataset.type === 'method') {
                             existingItem.remove();
                         } else {
                             const homeId = existingItem.dataset.home === 'page-1' ? 'inv-page-1' : 'inv-page-2';
                             document.getElementById(homeId).appendChild(existingItem);
                         }
                    }
                    slot.appendChild(dragItem);
                    dropped = true;
                    break;
                }
            }
        }

        if (!dropped) {
            if (dragItem.dataset.type === 'method') {
                dragItem.remove();
            } else if (dragOrigin.parent && dragOrigin.parent.isConnected) {
                dragOrigin.parent.insertBefore(dragItem, dragOrigin.nextSibling);
            } else {
                const targetHomeId = dragItem.dataset.home === 'page-1' ? 'inv-page-1' : 'inv-page-2';
                document.getElementById(targetHomeId).appendChild(dragItem);
            }
        }

        if (dragHelper) { dragHelper.remove(); dragHelper = null; }
        if (dragItem) dragItem.classList.remove('is-dragging');

        document.querySelectorAll('.grid-slot').forEach(s => s.classList.remove('highlight'));
        document.querySelectorAll('.inventory-bar').forEach(b => b.style.backgroundColor = '');

        dragItem = null;
        dragOrigin = { parent: null, nextSibling: null };
    }

    const refreshInventory = () => {
        page1.innerHTML = '';
        let items = getInventory();

        const usedItemNames = [];
        document.querySelectorAll('.grid-slot .item-obj').forEach(el => {
            if (el.dataset.type === 'item') {
                usedItemNames.push(el.dataset.name);
            }
        });

        usedItemNames.forEach(usedName => {
            const index = items.findIndex(i => i.name === usedName);
            if (index !== -1) {
                items.splice(index, 1);
            }
        });

        if (items.length === 0) {
            page1.innerHTML = '<span style="color:#5e2d20; font-size:12px; width:100%; text-align:center;">背包空空如也</span>';
        } else {
            items.forEach(item => {
                const el = createItemEl(item, 'item');
                el.dataset.home = 'page-1';
                page1.appendChild(el);
            });
        }
        if(window.twemoji) twemoji.parse(page1);
    };

    const initMethods = () => {
        page2.innerHTML = '';
        COOKING_METHODS.forEach(method => {
            const el = createItemEl(method, 'method');
            el.dataset.home = 'page-2';
            page2.appendChild(el);
        });
        if(window.twemoji) twemoji.parse(page2);
    };

    const toggleBtn = document.getElementById('toggle-btn');
    let isPage1 = true;

    toggleBtn.addEventListener('click', () => {
        if (isPage1) {
            page1.style.display = 'none'; page2.style.display = 'flex';
            toggleBtn.innerHTML = '<img src="https://files.catbox.moe/byiexe.jpg" alt="烹饪方式">'; 
            initMethods(); 
        } else {
            page2.style.display = 'none'; page1.style.display = 'flex';
            toggleBtn.innerHTML = '<img src="https://i.postimg.cc/fTLDqVwZ/mmexport1767799910243.png" alt="切换">';
            refreshInventory(); 
        }
        isPage1 = !isPage1;
    });


    document.querySelectorAll('.cook-float-text').forEach(ta => {
        ta.addEventListener('input', function() {
            this.style.height = 'auto';
            this.style.height = this.scrollHeight + 'px';
        });
    });

        refreshInventory();
    if(window.twemoji) twemoji.parse(document.body);

})();
