<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <script src="https://unpkg.com/@twemoji/api@latest/dist/twemoji.min.js" crossorigin="anonymous"></script>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        html, body { background: transparent; overflow: visible; }
        body { display: flex; flex-wrap: wrap; align-items: flex-start; gap: 18px; padding: 10px; }

        .item { 
            display: inline-flex; flex-direction: column; align-items: center; 
            gap: 6px; cursor: pointer; user-select: none; flex-shrink: 0;
            width: 96px;
        }

        .icon-wrap { position: relative; width: 52px; height: 52px; }

        .em { 
            width: 52px; height: 52px; font-size: 52px; line-height: 1; 
            display: block; text-align: center; 
            filter: grayscale(1) brightness(0.7); 
            transition: filter 0.35s ease;
        }
        .em img { 
            width: 52px; height: 52px; 
            filter: grayscale(1) brightness(0.7); 
            transition: filter 0.2s ease; 
        }
        .item.revealed .em, .item.revealed .em img { filter: none; }

        .em-flash {
            position: absolute; top: 0; left: 0;
            width: 52px; height: 52px; font-size: 52px; line-height: 1;
            display: block; text-align: center;
            opacity: 0; pointer-events: none; z-index: 1;
        }
        .em-flash img { 
            width: 52px; height: 52px; 
            transition: none !important;
        }
        .item.pop .em-flash {
            animation: colorflash 0.7s cubic-bezier(0.22, 1, 0.36, 1) forwards,
                       pop 0.55s cubic-bezier(0.34, 1.56, 0.64, 1);
        }
        @keyframes colorflash {
            0%   { opacity: 0; }
            18%  { opacity: 0.92; }
            100% { opacity: 0; }
        }

        .qmark { 
            position: absolute; inset: 0; display: flex; align-items: center; 
