<script>
    var raw = document.getElementById('raw').textContent;
    var re = /【[^|｜】]*[物品道具][^|｜】]*[|｜]\s*(?:等级\s*[：:]\s*)?(R|SR|SSR)\s*[|｜]\s*[\(（]?\s*((?:[\u2190-\u2BFF\u2600-\u27BF\u3030\u303D\uFE0F\u200D\uD83C-\uDBFF\uDC00-\uDFFF])+)\s*[\)）]?\s*(.+?)】/g;
    var m, items = [];

    while ((m = re.exec(raw)) !== null) {
        var parts = m[3].split(/[|｜]/);
        items.push({ r: m[1], e: m[2], n: parts[0].trim(), desc: parts[1] ? parts[1].trim() : '' });
    }

    items.forEach(function(item) {
        var div = document.createElement('div');
        div.className = 'item';

        div.innerHTML = `
            <div class="icon-wrap">
                <div class="em">${item.e}</div>
                <div class="em-flash" data-fill="fill-${item.r}">${item.e}</div>
                <div class="qmark">?</div>
            </div>
            <div class="info">
                <span class="nm r-${item.r}" data-t="${item.r} ${item.n}">${item.r} ${item.n}</span>
            </div>
            ${item.desc ? `<div class="desc r-${item.r}" data-t="${item.desc}">${item.desc}</div>` : ''}
        `;

        document.body.appendChild(div);

        div.addEventListener('click', function() {
            if (div.classList.contains('revealed')) return;

            div.classList.add('pop');
            div.addEventListener('animationend', function() {
                div.classList.remove('pop');
            }, { once: true });

            setTimeout(function() {
                div.classList.add('revealed');
            }, 60);
        });
    });

    function tw() {
        document.querySelectorAll('.em, .em-flash').forEach(function(e) {
            twemoji.parse(e, { folder: 'svg', ext: '.svg' });
        });
        document.querySelectorAll('.em-flash').forEach(function(flash) {
            var img = flash.querySelector('img');
            if (img) {
                img.style.filter = 'url(#' + flash.dataset.fill + ')';
                img.style.transition = 'none';
            }
        });
    }

    if (typeof twemoji !== 'undefined') tw();
    else document.querySelector('script[src*="twemoji"]').addEventListener('load', tw);

   if (window.frameElement) {
    window.frameElement.style.cssText = 'display:block;overflow:visible;width:100%;';
    setTimeout(function() {
        window.frameElement.style.height = document.body.scrollHeight + 20 + 'px';
    }, 100);
}
</script>
