<script>
    (function(){
        function updateAchievementCardLayout() {
            document.querySelectorAll('.pop-sticker-card').forEach(card => {
                const title = card.querySelector('.sticker-title');
                if (!title) return;
                title.setAttribute('data-title', title.textContent || '');

                const styles = window.getComputedStyle(title);
                const lineHeight = parseFloat(styles.lineHeight) || parseFloat(styles.fontSize) * 1.1 || 0;
                const titleHeight = title.scrollHeight || title.offsetHeight || 0;
                const extra = Math.max(0, Math.ceil(titleHeight - lineHeight));
                card.style.setProperty('--achievement-title-extra', extra + 'px');
            });
        }

        updateAchievementCardLayout();
        requestAnimationFrame(updateAchievementCardLayout);
        window.addEventListener('resize', updateAchievementCardLayout);
        if (document.fonts && document.fonts.ready) {
            document.fonts.ready.then(updateAchievementCardLayout).catch(() => {});
        }

        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('visible');
                    observer.unobserve(entry.target); 
                }
            });
        }, { threshold: 0.1 }); 

        const cards = document.querySelectorAll('.reveal-section');
        cards.forEach(el => observer.observe(el));
    })();
</script>

