            container.querySelectorAll('.auto-width-init-purpose').forEach(function(el){
                el.style.width = (el.value.length * 12 + 20) + 'px';
            });
        })();

        window.guestSavePromise = window.guestSavePromise || Promise.resolve();

        function getGuestTavernHelper() {
            return (window.parent && window.parent.TavernHelper) || window.TavernHelper || null;
        }

        function cloneGuestList(list) {
            try { return JSON.parse(JSON.stringify(list || [])); }
            catch (e) { return Array.isArray(list) ? list.slice() : []; }
        }

        function getCurrentMvuDateTextForGuest() {
            try {
                var mvuInterface = window.Mvu || (window.parent && window.parent.Mvu);
                if (!mvuInterface) return "";
                var mvuData = mvuInterface.getMvuData({ type: 'message', message_id: 'latest' });
                if (mvuData && mvuData.stat_data && mvuData.stat_data['当前时间']) return mvuData.stat_data['当前时间'];
                var chatData = mvuInterface.getMvuData({ type: 'chat' });
                if (chatData && chatData.stat_data && chatData.stat_data['当前时间']) return chatData.stat_data['当前时间'];
            } catch (e) {}
            return "";
        }

        function chineseDayToNumberForGuest(text) {
            var raw = String(text || "").replace(/第|日/g, "").trim();
            if (/^\d+$/.test(raw)) return parseInt(raw, 10);
            var map = { '零':0, '〇':0, '一':1, '二':2, '两':2, '三':3, '四':4, '五':5, '六':6, '七':7, '八':8, '九':9 };
            if (raw === '十') return 10;
            if (raw === '廿') return 20;
            if (raw === '卅') return 30;
            if (raw === '卌') return 40;
            var m;
            if ((m = raw.match(/^十([一二两三四五六七八九])$/))) return 10 + map[m[1]];
            if ((m = raw.match(/^([一二两三四五六七八九])十$/))) return map[m[1]] * 10;
            if ((m = raw.match(/^([一二两三四五六七八九])十([一二两三四五六七八九])$/))) return map[m[1]] * 10 + map[m[2]];
            if ((m = raw.match(/^廿([一二两三四五六七八九])$/))) return 20 + map[m[1]];
            if ((m = raw.match(/^卅([一二两三四五六七八九])$/))) return 30 + map[m[1]];
            if ((m = raw.match(/^卌([一二两三四五六七八九])$/))) return 40 + map[m[1]];
            return typeof map[raw] === 'number' ? map[raw] : null;
        }

        function parseWorldDatePartForGuest(text) {
            var raw = String(text || "").trim();
            var match = raw.match(/([^\s~～（）()，,：:]+月)\s*第?([零〇一二两三四五六七八九十廿卅卌\d]+)日/);
            if (!match) return null;
            var day = chineseDayToNumberForGuest(match[2]);
            if (day === null) return null;
            return { raw: raw, month: match[1], day: day };
        }

        function formatGuestDateRangeForStatus(dateRange) {
            var raw = String(dateRange || "").trim();
            if (!raw) return "";
            var parts = raw.split(/[~～]/);
            if (parts.length < 2) return raw;
            var startPart = parseWorldDatePartForGuest(parts[0]);
            var endPart = parseWorldDatePartForGuest(parts.slice(1).join('~'));
            var todayPart = parseWorldDatePartForGuest(getCurrentMvuDateTextForGuest());
            if (!startPart || !endPart || !todayPart) return raw;
            if (startPart.month !== endPart.month) return raw;
            if (startPart.month !== todayPart.month || endPart.month !== todayPart.month) return raw;
            function rel(diff) {
                if (diff === -1) return '昨天';
                if (diff === 0) return '今天';
                if (diff === 1) return '明天';
                if (diff < 0) return Math.abs(diff) + '日前';
                return diff + '日后';
            }
            return rel(startPart.day - todayPart.day) + '（' + startPart.raw + '）~' + rel(endPart.day - todayPart.day) + '（' + endPart.raw + '）';
        }

        function buildGuestAiViewForStatus(guestList) {
            if (!guestList || guestList.length === 0) return '';
            var body = '<Current_Guest_Group_Info>\n以下是当前在酒馆入住的客人团体信息表：\n';
            guestList.forEach(function(g, i) {
                var displayDate = g.custom_date || g.date_range || '';
                var displayPurpose = g.custom_purpose || g.purpose || '';
                var displayDateWithRelative = formatGuestDateRangeForStatus(displayDate);
                var statusParts = [];
                if (g.note) statusParts.push('备注: ' + g.note);
                if (g.pending_payment && g.pending_payment != '0') statusParts.push('待支付: ' + g.pending_payment);
                var statusStr = statusParts.length > 0 ? ' [' + statusParts.join(' | ') + ']' : '';

                body += '\n【团体 ' + (i + 1) + '】\n';
                if ((g.roles && g.roles.length > 0) || g.others) body += '成员:\n';
                if (g.roles && g.roles.length > 0) {
                    g.roles.forEach(function(r) {
                        var rName = r['姓名'] || r['Name'] || '';
                        if (!rName) return;
                        var rRoom = r.room ? '(入住房间：' + r.room + ')' : '(未分配房间)';
                        var gender = r['性别'] || r['Gender'] || '';
                        var race = r['种族'] || '';
                        var job = r['职业'] || '';
                        var appearance = r['外貌特征'] || '';
                        var identity = [race, job].filter(Boolean).join('、');
                        var descParts = [];
                        if (gender) descParts.push(gender);
                        if (identity) descParts.push(identity);
                        var detailStr = descParts.length > 0 ? descParts.join('，') + '。' : '';
                        if (appearance) detailStr += String(appearance).replace(/[。.]$/, '') + '。';
                        if (detailStr) detailStr += ' ';
                        body += '  ' + rName + '：' + detailStr + rRoom + '\n';
                    });
                }
                if (g.others) {
                    var oRoom = g.others_room ? ' (入住房间：' + g.others_room + ')' : '';
                    body += '  其他随行人员: ' + g.others + oRoom + '\n';
                }
                if (displayPurpose || statusStr) body += '事由：' + displayPurpose + statusStr + '\n';
                if (displayDateWithRelative) body += '住宿时间：' + displayDateWithRelative + '\n';
            });
            body += '\n</Current_Guest_Group_Info>';
            return body;
        }

        function getGuestListForEdit() {
            var cached = Array.isArray(window.guestDataCache) ? cloneGuestList(window.guestDataCache) : null;
            if (cached) return cached;
            var helper = getGuestTavernHelper();
            if (!helper) return [];
            var vars = helper.getVariables({type:'chat'}) || {};
            var gList = vars.guest_group_info || [];
            if (typeof gList === 'string') { try { gList = JSON.parse(gList); } catch(e) { gList = []; } }
            if (!Array.isArray(gList)) gList = [];
            return cloneGuestList(gList);
        }

        window.guestEditMode = !!window.guestEditMode;
        window.toggleGuestEditMode = function(event) {
            if (event) {
                event.preventDefault();
                event.stopPropagation();
            }
            window.guestEditMode = !window.guestEditMode;
            if (window.renderGuestList) window.renderGuestList();
        };
        window.closeGuestEditMode = function() {
            if (!window.guestEditMode) return;
            var active = document.activeElement;
            if (active && active !== document.body && active.blur) active.blur();
            window.guestEditMode = false;
            Promise.resolve(window.guestSavePromise).finally(function() {
                if (window.renderGuestList) window.renderGuestList();
            });
        };
        window.toggleGuestHelp = function(event) {
            if (event) {
                event.preventDefault();
                event.stopPropagation();
            }
            var popover = document.getElementById('guest-help-popover');
            if (popover) popover.classList.toggle('is-open');
        };
        window.closeGuestHelp = function() {
            var popover = document.getElementById('guest-help-popover');
            if (popover) popover.classList.remove('is-open');
        };
        document.addEventListener('click', function(event) {
            var target = event.target;
            if (window.guestEditMode) {
                if (!(target && target.closest && target.closest('#guest-records-panel'))) window.closeGuestEditMode();
            }
            if (target && target.closest && target.closest('.guest-help-toggle')) return;
            if (!(target && target.closest && target.closest('#guest-help-popover'))) window.closeGuestHelp();
        });

        /* --- 修改点：新增渲染函数，实现翻页时读取最新变量 --- */
        window.renderGuestList = function() {
            var container = document.getElementById('guest-list-container');
            if (!container) return;

            var gData = [];
            try {
                // 尝试从酒馆获取变量
                if (window.parent && window.parent.TavernHelper) {
                    var vars = window.parent.TavernHelper.getVariables({type:'chat'});
                    if (vars && vars.guest_group_info) {
                        gData = vars.guest_group_info;
                    }
                }
            } catch (e) { console.error("Error fetching variables", e); }

            // 数据解析
            if (typeof gData === 'string') { try { gData = JSON.parse(gData); } catch(e) { gData = []; } }
            if (!Array.isArray(gData)) gData = [];
            window.guestDataCache = cloneGuestList(gData);

            var panel = document.getElementById('guest-records-panel');
            if (panel) panel.classList.toggle('guest-edit-mode', !!window.guestEditMode);

            var html = '';

            if (gData.length === 0) {
                html = '<span style="color:#999; font-style: italic;">- 目前没有客人入住 -</span>';
            } else {
                // 倒序遍历，模拟 gData.slice().reverse()
                for (var i = gData.length - 1; i >= 0; i--) {
                    var g = gData[i];
                    var realIndex = i; // 原始数组中的索引
                    var isLastDisplayed = (i === 0); // 在倒序显示中，索引为0的是最后一个显示的





                    var borderStyle = (!isLastDisplayed) ? "border-bottom:2px solid rgba(120, 82, 55, 0.25); margin-bottom:12px; padding-bottom:12px;" : "";

                    var firstRoleName = (g.roles && g.roles[0]) ? (g.roles[0]['姓名'] || g.roles[0]['Name']) : "未知";
                    var dateStr = g.date_range || "未知日期";
                    var guestId = dateStr + "_" + firstRoleName;
                    var editAttr = window.guestEditMode ? ' contenteditable="true"' : '';
                    var readonlyAttr = window.guestEditMode ? '' : ' readonly tabindex="-1"';

                    html += '<div id="guest-row-' + realIndex + '" style="' + borderStyle + ' position: relative; padding-right:18px;">';
                    html += '<div class="eraser-btn" title="删除该记录" style="position:absolute; right:0; top:0;" data-group="' + realIndex + '" data-guest-id="' + guestId + '" onclick="window.deleteGuestGroup(this)">✕</div>';

                    // 成员：左侧为角色名/描述，右侧为对应住房分配
                    if (g.roles && g.roles.length > 0) {
                        g.roles.forEach(function(r, roleIdx) {
                            var rName = r['姓名'] || r['Name'] || '未知角色';
                            var metaDetails = [];
                            if(r['种族']) metaDetails.push(r['种族']);
                            if(r['职业']) metaDetails.push(r['职业']);
                            var metaStr = metaDetails.length > 0 ? metaDetails.join(' ') : "";
                            var metaDisplay = metaStr ? ' / ' + metaStr : (window.guestEditMode ? ' / ' : '');
                            var appearanceStr = r['外貌特征'] || "";

                            html += '<div class="guest-member-row">' +
                                '<div class="guest-member-copy">' +
                                    '<div class="guest-role-title">' +
                                        '<span class="guest-role-name guest-editable" data-group="' + realIndex + '" data-role="' + roleIdx + '" data-type="role_name" onblur="window.handleGuestEditableBlur(this)"' + editAttr + '>' + rName + '</span>' +
                                        ((metaDisplay || window.guestEditMode) ? '<span class="guest-role-inline-meta guest-editable" data-group="' + realIndex + '" data-role="' + roleIdx + '" data-type="role_meta" onblur="window.handleGuestEditableBlur(this)"' + editAttr + '>' + metaDisplay + '</span>' : '') +
                                    '</div>' +
                                    ((appearanceStr || window.guestEditMode) ? '<div class="guest-role-details guest-role-appearance guest-editable" data-group="' + realIndex + '" data-role="' + roleIdx + '" data-type="role_appearance" onblur="window.handleGuestEditableBlur(this)"' + editAttr + '>' + appearanceStr + '</div>' : '') +
                                '</div>' +
                                '<div class="guest-room-cell">' +
                                    '<input type="text" class="g-input room-input" value="' + (r.room || '') + '" placeholder="住房分配" data-group="' + realIndex + '" data-role="' + roleIdx + '" readonly title="点击选择房间" onclick="window.openGuestRoomPicker(this, \'role_room\')" />' +
                                '</div>' +
                            '</div>';
                        });
                    }

                    // 其他随行人员
                    if (g.others) {
                        html += '<div class="guest-member-row">' +
                            '<div class="guest-other-info guest-editable" data-group="' + realIndex + '" data-type="others" onblur="window.handleGuestEditableBlur(this)"' + editAttr + '>其他随行人员：' + g.others + '</div>' +
                            '<div class="guest-room-cell">' +
                                '<input type="text" class="g-input room-input" value="' + (g.others_room || '') + '" placeholder="住房分配" data-group="' + realIndex + '" readonly title="点击选择房间" onclick="window.openGuestRoomPicker(this, \'others_room\')" />' +
                            '</div>' +
                        '</div>';
                    }

                    // 目的行
                    html += '<div class="guest-meta-row">' +
                        '<span class="guest-meta-label label-text-sm">目的:</span>' +
                        '<div class="guest-meta-value purpose-input guest-editable" data-group="' + realIndex + '" data-type="custom_purpose" onblur="window.handleGuestEditableBlur(this)"' + editAttr + '>' + (g.custom_purpose || g.purpose || '') + '</div>' +
                    '</div>';

                    // 住宿日期
                    html += '<div class="guest-meta-row">' +
                        '<span class="guest-meta-label label-text-sm">住宿日期:</span>' +
                        '<div class="guest-meta-value date-input guest-editable" data-group="' + realIndex + '" data-type="custom_date" onblur="window.handleGuestEditableBlur(this)"' + editAttr + '>' + (g.custom_date || g.date_range || '') + '</div>' +
                    '</div>';

                    // 备注
                    html += '<div style="display:flex; align-items:center; justify-content:space-between; margin-top:4px; line-height:1.35;">' +
                        '<div style="display:flex; align-items:center; flex:1; min-width:0;">' +
                            '<span style="font-size:10px; color:#78909c; flex-shrink:0;">注:</span>' +
                            '<input type="text" class="g-input note-input" value="' + (g.note || '') + '" placeholder="自由记录备注" data-group="' + realIndex + '" onblur="window.handleGuestInput(this, \'note\')" />' +
                        '</div>' +
                        '<div style="display:flex; align-items:center; flex-shrink:0; margin-left:8px;">' +
                            '<span class="label-text-sm">待付铜币:</span>' +
                            '<div style="display:flex; align-items:center; border-bottom:1px dashed #aaa; margin:0 4px;">' +
                                '<span class="stepper-btn" onclick="window.adjustPayment(this, -10)">-</span>' +
                                '<input type="text" class="g-input pay-input" style="border-bottom:none; margin:0;" value="' + (g.pending_payment || '0') + '" data-group="' + realIndex + '" onblur="window.handleGuestInput(this, \'payment\')" />' +
                                '<span class="stepper-btn" onclick="window.adjustPayment(this, 10)">+</span>' +
                            '</div>' +
                        '</div>' +
                    '</div>' +
                '</div>';
                    }
                }
            container.innerHTML = html;

            // 重新初始化动态生成元素的宽度
            container.querySelectorAll('.auto-width-init').forEach(function(el){
                el.style.width = (el.value.length * 12 + 20) + 'px';
            });
            container.querySelectorAll('.auto-width-init-purpose').forEach(function(el){
                el.style.width = (el.value.length * 12 + 20) + 'px';
            });
        };

        window.openGuestRoomPicker = function(element, type) {
            if (!element) return;
            var groupIdx = parseInt(element.getAttribute('data-group'));
            var roleIdx = element.getAttribute('data-role');
            roleIdx = (roleIdx === null || roleIdx === "") ? null : parseInt(roleIdx);
            if (typeof window.openTavernMap !== 'function') return;
            window.openTavernMap({
                mode: 'pick-room',
                currentRoom: element.value || '',
                onPick: function(roomName) {
                    element.value = roomName || '';
                    element.setAttribute('title', roomName ? ('已分配：' + roomName) : '点击选择房间');
                    window.updateGuestData(groupIdx, type, roleIdx, element.value);
                }
            });
        };
        /* --- 修改点：在翻页时调用渲染函数 --- */
        function toNextPage() { 
            var container = document.currentScript ? document.currentScript.parentElement : document.body;
            var current = container.querySelector('#page-' + currentPage); 
            if(current) { current.style.display = 'none'; current.classList.remove('page-animate'); } 

            currentPage++;
            if (currentPage > totalPages) currentPage = 1; 

            // 当翻到第二页（客人记录页）时，触发JS渲染逻辑以获取最新数据
            if (currentPage === 2) {
                if (window.renderGuestList) window.renderGuestList();
            }

            var next = container.querySelector('#page-' + currentPage); 
            if(next) { next.style.display = 'flex'; void next.offsetWidth;
            next.classList.add('page-animate'); } 
        }

        function toggleModal(modalId, action) { var container = document.currentScript ?
            document.currentScript.parentElement : document.body; var modal = container.querySelector("#" + modalId) || document.getElementById(modalId);
            if (modal) { if (action === 'open') { modal.style.display = 'flex'; } else { modal.style.display = 'none';
            } } }

        /* === 酒馆地图 modal-1 渲染逻辑 === */
        (function(){
            var FLOOR_LABELS = { floor_2: '二层', floor_1: '一层', basement_1: '地下', outdoor: '户外' };
            var FLOOR_ORDER = ['floor_1', 'floor_2', 'outdoor', 'basement_1'];
            var FLOOR_BG = {
