            function isUnlocked(struct, fk) {
                return struct[fk] && typeof struct[fk] === 'object' && Object.keys(struct[fk]).length > 0;
            }

            function buildList() {
                var struct = getStructure();
                var list = [];
                for (var i = 0; i < FLOOR_ORDER.length; i++) {
                    var fk = FLOOR_ORDER[i];
                    if (isUnlocked(struct, fk)) {
