                var $label = document.getElementById('tavern-map-label');
                var $prev = document.getElementById('tavern-map-prev');
                var $next = document.getElementById('tavern-map-next');
                var $empty = document.getElementById('tavern-map-empty');
                var $tip = document.getElementById('tavern-map-tip');
                if (!$img || !$stage || !$overlay) return;

                if (mapState.list.length === 0) {
                    $stage.style.display = 'none';
