                    if ($tip) $tip.textContent = '';
                    return;
                }

                if ($empty) $empty.style.display = 'none';
                if (mapState.index >= mapState.list.length) mapState.index = 0;
                if (mapState.index < 0) mapState.index = mapState.list.length - 1;
                var cur = mapState.list[mapState.index];

                if (cur.img) {
                    $stage.classList.remove('empty-floor');
                    $stage.style.display = '';
                    setMapImage($img, $stage, cur.key, cur.img);
                } else {
                    $img.removeAttribute('src');
                    $img.style.display = 'none';
                    $stage.classList.add('empty-floor');
                    $stage.style.aspectRatio = '';
                    $stage.style.display = '';
                    fitStageToImage();
                }

                if ($label) $label.textContent = cur.label;

                var multi = mapState.list.length > 1;
                if ($prev) $prev.style.display = multi ? 'flex' : 'none';
                if ($next) $next.style.display = multi ? 'flex' : 'none';

                var floor = cur.rooms || {};
                var roomKeys = Object.keys(floor);
                var html = '';
                for (var k = 0; k < roomKeys.length; k++) {
                    var rid = roomKeys[k];
