                    if (hb.h) hitStyle += '--hit-h:' + hb.h + ';';
                    html += '<div class="tavern-map-room' + sel + '" data-room="' + rid + '" style="left:' + pos.x + '%; top:' + pos.y + '%;' + hitStyle + '">' + label + '</div>';
                }
