                    var x = ((e.clientX - rect.left) / rect.width * 100).toFixed(2);
                    var y = ((e.clientY - rect.top) / rect.height * 100).toFixed(2);
                    var c = document.getElementById('tavern-map-coord');
                    if (c) c.textContent = 'x: ' + x + ' y: ' + y;
                    try { console.log('[酒馆地图] 点击坐标: { x: ' + x + ', y: ' + y + ' }'); } catch(err) {}
