        /* === 酒馆地图 modal-1 渲染逻辑 === */
        (function(){
            var FLOOR_LABELS = { floor_2: '二层', floor_1: '一层', basement_1: '地下', outdoor: '户外' };
            var FLOOR_ORDER = ['floor_1', 'floor_2', 'outdoor', 'basement_1'];
            var FLOOR_BG = {
                floor_1: 'https://img.baibai.cv/f/Pgpsg/Tavern1L.png',
                floor_2: 'https://img.baibai.cv/f/6k5IA/Tavern2L.png',
