            var mapState = { index: 0, list: [], roomId: null };
            var mapPickTarget = null;

            function getStructure() {
                try {
                    if (window.parent && typeof window.parent.getTavernStructure === 'function') {
                        return window.parent.getTavernStructure() || {};
                    }
                    if (window.parent && window.parent.TavernHelper) {
                        var v = window.parent.TavernHelper.getVariables({type:'chat'});
                        return (v && v.tavern_structure) || {};
                    }
                } catch (e) {}
                return {};
            }

            function isUnlocked(struct, fk) {
                return struct[fk] && typeof struct[fk] === 'object' && Object.keys(struct[fk]).length > 0;
            }

            function buildList() {
                var struct = getStructure();
                var list = [];
                for (var i = 0; i < FLOOR_ORDER.length; i++) {
                    var fk = FLOOR_ORDER[i];
                    if (isUnlocked(struct, fk)) {
                        list.push({ key: fk, label: FLOOR_LABELS[fk], img: FLOOR_BG[fk] || '', rooms: struct[fk] });
                    }
                }
                return list;
            }

            function fitStageToImage() {
                var viewer = document.getElementById('tavern-map-viewer');
                var stage = document.getElementById('tavern-map-stage');
                var img = document.getElementById('tavern-map-img');
                if (!viewer || !stage) return;
                var vw = viewer.clientWidth, vh = viewer.clientHeight;
                if (!vw || !vh) return;
                var ratio = (img && img.naturalWidth && img.naturalHeight && img.style.display !== 'none')
                    ? img.naturalWidth / img.naturalHeight
                    : 4 / 3;
                var w, h;
                if (vw / vh > ratio) { h = vh; w = h * ratio; }
                else                 { w = vw; h = w / ratio; }
                stage.style.width = w + 'px';
                stage.style.height = h + 'px';
            }

            var mapImageToken = 0;
            function withCacheBust(url) {
                if (!url) return '';
                return url + (url.indexOf('?') === -1 ? '?' : '&') + 'st_retry=' + Date.now();
            }
            function setMapImage(img, stage, floorKey, src) {
                var token = ++mapImageToken;
                var candidates = src ? [src, withCacheBust(src)] : [];
                var index = 0;
                img.referrerPolicy = 'no-referrer';

                function loadNext() {
                    if (token !== mapImageToken) return;
                    if (index >= candidates.length) {
                        img.onload = null;
                        img.onerror = null;
                        img.removeAttribute('src');
                        img.style.display = 'none';
                        stage.classList.add('empty-floor');
                        stage.style.aspectRatio = '';
                        fitStageToImage();
                        try { console.warn('[酒馆地图] 贴图加载失败:', floorKey, src); } catch(e) {}
                        return;
                    }
                    var url = candidates[index++];
                    img.onload = function() {
                        if (token !== mapImageToken) return;
                        stage.classList.remove('empty-floor');
                        stage.style.display = '';
                        img.style.display = 'block';
                        fitStageToImage();
                    };
                    img.onerror = function() { loadNext(); };
                    img.style.display = 'block';
                    img.src = url;
                    if (img.complete && img.naturalWidth > 0) img.onload();
                }

                loadNext();
            }

            function renderMap() {
                mapState.list = buildList();
                var $img = document.getElementById('tavern-map-img');
                var $stage = document.getElementById('tavern-map-stage');
                var $overlay = document.getElementById('tavern-map-overlay');
                var $label = document.getElementById('tavern-map-label');
                var $prev = document.getElementById('tavern-map-prev');
                var $next = document.getElementById('tavern-map-next');
                var $empty = document.getElementById('tavern-map-empty');
                var $tip = document.getElementById('tavern-map-tip');
                if (!$img || !$stage || !$overlay) return;

                if (mapState.list.length === 0) {
                    $stage.style.display = 'none';
                    if ($label) $label.textContent = '';
                    if ($prev) $prev.style.display = 'none';
                    if ($next) $next.style.display = 'none';
                    if ($empty) $empty.style.display = 'flex';
                    if ($tip) $tip.textContent = '';
                    return;
                }

                if ($empty) $empty.style.display = 'none';
                if (mapState.index >= mapState.list.length) mapState.index = 0;
                if (mapState.index < 0) mapState.index = mapState.list.length - 1;
                var cur = mapState.list[mapState.index];

                if (cur.img) {
                    $stage.classList.remove('empty-floor');
                    $stage.style.display = '';
                    setMapImage($img, $stage, cur.key, cur.img);
                } else {
                    $img.removeAttribute('src');
                    $img.style.display = 'none';
                    $stage.classList.add('empty-floor');
                    $stage.style.aspectRatio = '';
                    $stage.style.display = '';
                    fitStageToImage();
                }

                if ($label) $label.textContent = cur.label;

                var multi = mapState.list.length > 1;
                if ($prev) $prev.style.display = multi ? 'flex' : 'none';
                if ($next) $next.style.display = multi ? 'flex' : 'none';

                var floor = cur.rooms || {};
                var roomKeys = Object.keys(floor);
                var html = '';
                for (var k = 0; k < roomKeys.length; k++) {
                    var rid = roomKeys[k];
                    var room = floor[rid] || {};
                    var pos = room.mapPos || { x: 50, y: 50 };
                    var sel = (mapState.roomId === rid) ? ' selected' : '';
                    var name = (room.name || rid).replace(/</g, '&lt;');
                    var label = name;
                    var hb = room.hitbox || {};
                    var hitStyle = '';
                    if (hb.w) hitStyle += '--hit-w:' + hb.w + ';';
                    if (hb.h) hitStyle += '--hit-h:' + hb.h + ';';
                    html += '<div class="tavern-map-room' + sel + '" data-room="' + rid + '" style="left:' + pos.x + '%; top:' + pos.y + '%;' + hitStyle + '">' + label + '</div>';
                }
                $overlay.innerHTML = html;
                setupStageClick();
                Array.prototype.forEach.call($overlay.querySelectorAll('.tavern-map-room'), function(el){
                    var rid = el.getAttribute('data-room');
                    var rinfo = floor[rid] || {};
                    var rname = rinfo.name || rid;
                    if (adjustMode) {
                        el.classList.add('adjustable');
                        var dragging = false;
                        var stageRect = null;
                        el.onpointerdown = function(e) {
                            e.preventDefault(); e.stopPropagation();
                            stageRect = $stage.getBoundingClientRect();
                            dragging = true;
                            try { el.setPointerCapture(e.pointerId); } catch(err) {}
                            el.style.transition = 'none';
                        };
                        el.onpointermove = function(e) {
                            if (!dragging) return;
                            var x = (e.clientX - stageRect.left) / stageRect.width * 100;
                            var y = (e.clientY - stageRect.top) / stageRect.height * 100;
                            x = Math.max(0, Math.min(100, x));
                            y = Math.max(0, Math.min(100, y));
                            el.style.left = x.toFixed(2) + '%';
                            el.style.top = y.toFixed(2) + '%';
                            el.dataset.lastX = x.toFixed(2);
                            el.dataset.lastY = y.toFixed(2);
                            var c = document.getElementById('tavern-map-coord');
                            if (c) c.textContent = rname + ' x:' + x.toFixed(2) + ' y:' + y.toFixed(2);
                        };
                        el.onpointerup = function(e) {
                            if (!dragging) return;
                            dragging = false;
                            try { el.releasePointerCapture(e.pointerId); } catch(err) {}
                            el.style.transition = '';
                            try { console.log('[酒馆地图] ' + rname + ' → mapPos: { x: ' + el.dataset.lastX + ', y: ' + el.dataset.lastY + ' }'); } catch(err) {}
                        };
                        el.onclick = function(e) { e.stopPropagation(); };
                    } else {
                        el.classList.remove('adjustable');
                        el.onpointerdown = null; el.onpointermove = null; el.onpointerup = null;
                        el.onclick = function(){
                            var pickedRoomId = el.getAttribute('data-room');
                            mapState.roomId = pickedRoomId;
                            if (mapPickTarget && typeof mapPickTarget.onPick === 'function') {
                                var pickedRoom = floor[pickedRoomId] || {};
                                mapPickTarget.onPick(pickedRoom.name || pickedRoomId, pickedRoomId, pickedRoom, cur);
                                mapPickTarget = null;
                                toggleModal('modal-1', 'close');
                                return;
                            }
                            renderMap();
                        };
                    }
                });

                if ($tip) {
                    if (mapState.roomId && floor[mapState.roomId]) {
                        var r = floor[mapState.roomId];
                        var rEmoji = (r.emoji || '').replace(/</g, '&lt;');
                        var rName = (r.name || '').replace(/</g, '&lt;');
                        var headLabel = (rEmoji ? rEmoji + ' ' : '') + rName;
                        $tip.innerHTML = '<span class="room-head">' + headLabel + '</span><br><span class="room-purpose">' + (r.purpose || '-') + '</span>' + (r.desc ? '<br>' + r.desc : '');
                    } else {
                        $tip.textContent = roomKeys.length > 0 ? (mapPickTarget ? '点击房间完成住房分配' : '点击房间查看详情') : '';
                    }
                }
            }

            var adjustMode = false;
            var stageClickAttached = false;
            function setupStageClick() {
                if (stageClickAttached) return;
