        .float-item { position: absolute; animation: floatAround 8s ease-in-out infinite; opacity: 0.95; }
        @keyframes floatAround {
            0% { transform: translate(0, 0) rotate(-5deg); }
            50% { transform: translate(0, -15px) rotate(5deg); }
            100% { transform: translate(0, 0) rotate(-5deg); }
        }

        .hero-zone { flex: 1; display: flex; align-items: center; justify-content: center; position: relative; z-index: 5; padding-bottom: 10px; }
        .hero-wrapper { animation: heroPop 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275) backwards; animation-delay: 0.2s; }
        .hero-sticker { width: 150px; height: auto; animation: breathe 4s ease-in-out infinite; }
        @keyframes heroPop { 0% { transform: scale(0.5); opacity: 0; } 100% { transform: scale(1); opacity: 1; } }
        @keyframes breathe { 0%, 100% { transform: scale(1) rotate(0deg); } 50% { transform: scale(1.05) rotate(2deg); } }

        .dock-bar { position: relative; z-index: 10; padding: 0 20px 25px 20px; display: flex; flex-direction: column; gap: 12px; }
        .btn-row { display: flex; gap: 12px; width: 100%; animation: slideUp 0.6s cubic-bezier(0.25, 0.8, 0.25, 1) backwards; }
        .row-1 { animation-delay: 0.3s; } .row-2 { animation-delay: 0.4s; }
        @keyframes slideUp { 0% { transform: translateY(40px); opacity: 0; } 100% { transform: translateY(0); opacity: 1; } }

        .cream-btn {
            flex: 1; background: #fffcf5; border: 2px solid #fff; border-radius: 20px; padding: 10px 0; cursor: pointer;
            display: flex; flex-direction: column; align-items: center; justify-content: center;
            box-shadow: 0 4px 0 #e6dcc5, 0 5px 10px rgba(0,0,0,0.05); transition: all 0.1s; position: relative;
        }
        .cream-btn:active { transform: translateY(4px); box-shadow: 0 0 0 #e6dcc5; }
        .btn-icon { font-size: 20px; margin-bottom: 4px; }
        .btn-txt { font-size: 12px; font-weight: 800; color: #6d665a; letter-spacing: 1px; }

        /* ================= 3. 商城样式 ================= */
        #page-mall { background: var(--bg); position: relative; }
        #page-mall .app-header { background: linear-gradient(90deg, #ff9000, #ff5000); padding: 8px 12px; }

        .mall-search-box { flex: 1; background: #fff; border-radius: 18px; height: 30px; display: flex; align-items: center; padding: 0 10px; }
        #keyword-inp { border: none; outline: none; width: 100%; font-size: 12px; color: #333; background: transparent; }
        #keyword-inp::placeholder { color: #ccc; }
        .mall-go { background: #fff; color: var(--p); border: none; border-radius: 16px; padding: 0 12px; height: 28px; font-size: 12px; font-weight: bold; cursor: pointer; margin-left: 8px; transition: 0.2s; }

        .nav-bar { background: #fff; display: flex; align-items: center; justify-content: space-between; padding: 8px 15px; font-size: 12px; color: var(--txt); box-shadow: 0 2px 5px rgba(0,0,0,0.03); z-index: 1; flex-shrink: 0; }
        .nav-left { display: flex; gap: 20px; }
        .nav-item.active { color: var(--p); font-weight: bold; position: relative; }
        .nav-item.active::after { content: ''; position: absolute; bottom: -8px; left: 50%; transform: translateX(-50%); width: 10px; height: 2px; background: var(--p); border-radius: 2px; }

        .list-zone { flex: 1; overflow-y: auto; padding: 10px; padding-bottom: 15px; display: flex; flex-direction: column; gap: 10px; transition: padding-bottom 0.3s; }
        .list-zone.has-cart { padding-bottom: 70px; }

        /* 商品卡片 */
        .card { background: #fff; border-radius: 10px; padding: 10px; display: flex; gap: 10px; box-shadow: 0 2px 6px rgba(0,0,0,0.02); transition: all 0.2s; }
        .c-img { width: 80px; height: 80px; background: #f9f9f9; border-radius: 6px; display: flex; align-items: center; justify-content: center; font-size: 35px; flex-shrink: 0; }
        .c-img img.emoji { width: 48px !important; height: 48px !important; }
        .c-info { flex: 1; display: flex; flex-direction: column; justify-content: space-between; }
        .c-title-row { line-height: 1.4; color: var(--txt); }
        .c-title-txt { font-weight: bold; font-size: 15px; } 
        .pro-tag { display: inline-block; background: linear-gradient(90deg, #ff0036, #ff5000); color: #fff; font-size: 10px; padding: 0 4px; border-radius: 3px; margin-right: 4px; font-weight: bold; vertical-align: text-bottom; height: 16px; line-height: 16px; }
        .c-desc { font-size: 11px; color: #999; margin-top: 4px; line-height: 1.4; white-space: normal; }
        .c-foot { display: flex; justify-content: space-between; align-items: flex-end; margin-top: 8px; }
        .c-price { color: #ff0036; font-size: 16px; font-weight: 900; }
        .c-sales { font-size: 10px; color: #bbb; margin-left: 4px; }

        .btn-buy { background: #ffebd7; color: var(--p); border: 1px solid var(--p); border-radius: 14px; padding: 4px 12px; font-size: 11px; cursor: pointer; font-weight: bold; transition: 0.2s; }

        /* 数量控制器 */
        .qty-control { display: none; align-items: center; background: #fff; border: 1px solid #ddd; border-radius: 14px; height: 24px; }
        .qty-control.active { display: flex; }
        .qty-btn { width: 24px; height: 100%; border: none; background: transparent; color: var(--txt); font-weight: bold; cursor: pointer; font-size: 14px; }
        .qty-num { width: 30px; text-align: center; font-size: 12px; font-weight: bold; color: var(--txt); }

        /* 购物车栏 */
        .cart-bar { 
            position: absolute; bottom: 15px; left: 15px; right: 15px; 
            background: rgba(0,0,0,0.9); backdrop-filter: blur(8px);
            border-radius: 40px; height: 50px; padding: 0 5px 0 20px; 
            display: flex; align-items: center; justify-content: space-between; 
            color: #fff; box-shadow: 0 5px 20px rgba(0,0,0,0.25);
            transform: translateY(150%); transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1); 
            z-index: 30; 
        }
        .cart-bar.show { transform: translateY(0); }
        .cart-total-hl { color: #ff9000; font-size: 18px; font-weight: 900; margin-left: 5px; }

        .cart-toggle-btn { background: transparent; border: none; color: #ccc; font-size: 12px; cursor: pointer; padding: 5px 10px; }

        .btn-checkout { 
            background: linear-gradient(90deg, #ff9000, #ff5000); border: none; 
            color: #fff; border-radius: 20px; padding: 0 20px; height: 40px; 
            font-weight: bold; cursor: pointer; font-size: 13px; margin-right: 2px; 
            box-shadow: 0 2px 10px rgba(255, 80, 0, 0.3);
        }

        /* 购物车抽屉 */
        .cart-drawer-mask {
            position: absolute; top: 0; left: 0; width: 100%; height: 100%;
            background: rgba(0,0,0,0.5); z-index: 25;
            display: none; opacity: 0; transition: opacity 0.3s;
        }
        .cart-drawer-mask.open { display: block; opacity: 1; }

        .cart-drawer {
            position: absolute; bottom: 0; left: 0; width: 100%; 
            background: #fff; border-radius: 24px 24px 0 0;
            padding: 20px 20px 80px 20px; box-sizing: border-box;
            transform: translateY(100%); transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
            z-index: 26; max-height: 70%; display: flex; flex-direction: column;
        }
        .cart-drawer.open { transform: translateY(0); }

        .drawer-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 15px; border-bottom: 1px solid #eee; padding-bottom: 10px; }
        .drawer-title { font-weight: bold; font-size: 14px; color: #333; }
        .drawer-clear { color: #999; font-size: 12px; cursor: pointer; }
        .drawer-list { overflow-y: auto; flex: 1; }

        .drawer-item { display: flex; justify-content: space-between; align-items: center; padding: 10px 0; border-bottom: 1px solid #f5f5f5; }
        .d-name { font-size: 13px; font-weight: bold; color: #333; }
        .d-price { font-size: 12px; color: #ff5000; margin-left: 5px; }

        .end-tip { text-align: center; color: #ccc; font-size: 11px; margin-top: 10px; margin-bottom: 5px; display: flex; align-items: center; justify-content: center; gap: 5px; }
        .end-tip::before, .end-tip::after { content: ''; display: block; width: 20px; height: 1px; background: #e0e0e0; }

        /* 商城-空状态欢迎页 (搜索前) */
        .mall-welcome {
            display: none; flex: 1; flex-direction: column;
            align-items: center; justify-content: center;
            padding: 20px; background: var(--bg); text-align: center;
        }
        #page-mall.pre-search .mall-welcome { display: flex; }
        #page-mall.pre-search .nav-bar,
        #page-mall.pre-search .mall-balance-bar,
        #page-mall.pre-search .list-zone,
        #page-mall.pre-search .mall-search-box,
        #page-mall.pre-search .mall-go { display: none; }
        .mall-welcome-logo { font-size: 64px; margin-bottom: 14px; line-height: 1; }
        .mall-welcome-title {
            font-size: 28px; font-weight: 900; letter-spacing: 4px;
            background: linear-gradient(90deg, #ff9000, #ff5000);
            -webkit-background-clip: text; -webkit-text-fill-color: transparent;
            margin-bottom: 6px;
        }
        .mall-welcome-sub { color: #999; font-size: 11px; margin-bottom: 28px; letter-spacing: 1px; }
        .mall-welcome-search {
            width: 90%; max-width: 360px; background: #fff;
            border-radius: 24px; height: 42px; display: flex; align-items: center;
            padding: 0 6px 0 14px; box-shadow: 0 4px 16px rgba(255,80,0,0.12);
            border: 1px solid #ffe0cc; box-sizing: border-box;
        }
        #welcome-keyword-inp {
            border: none; outline: none; flex: 1; font-size: 13px;
            color: #333; background: transparent; height: 100%; min-width: 0;
        }
        #welcome-keyword-inp::placeholder { color: #ccc; }
        .welcome-go-btn {
            background: linear-gradient(90deg, #ff9000, #ff5000); color: #fff;
            border: none; border-radius: 20px; padding: 0 18px; height: 32px;
            font-size: 13px; font-weight: bold; cursor: pointer; flex-shrink: 0;
        }
        .mall-welcome-tip { margin-top: 22px; color: #bbb; font-size: 11px; }

        /* ================= 4. 酒馆管家 (左右切换版样式) ================= */
        /* ===== page-butler 深色壁炉主题 ===== */
        #page-butler {
            --b-bg: #1a1a1b;
            --b-card: #252526;
            --b-fire-main: #FF5E02;
            --b-fire-light: #FFB830;
            --b-fire-dark: #E23101;
            --b-log: #3d2516;
            --b-text: #e0e0e0;
            --b-muted: #888;
            background: var(--b-bg);
            color: var(--b-text);
            padding: 0;
        }
        /* 顶部两个角落按钮（绝对定位，不占布局） */
        #page-butler .butler-corners {
            position: absolute; top: 14px; left: 14px; right: 14px;
            display: flex; justify-content: space-between; pointer-events: none;
            z-index: 5;
        }
        #page-butler .butler-corners > * { pointer-events: auto; }
        #page-butler .butler-back-btn {
            width: 32px; height: 32px; border-radius: 50%;
            background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.08);
            color: var(--b-text); font-size: 14px; cursor: pointer; padding: 0;
            display: flex; align-items: center; justify-content: center;
        }
        #page-butler .butler-back-btn:hover { background: rgba(255,255,255,0.12); }
        #page-butler .butler-help-btn {
            width: 28px; height: 28px; border-radius: 50%;
            background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.08);
            color: var(--b-muted); font-size: 12px; cursor: pointer;
            display: flex; align-items: center; justify-content: center;
            margin-top: 2px;
        }
        #page-butler .butler-help-btn:hover { color: var(--b-text); background: rgba(255,255,255,0.12); }

        /* 篝火：绝对定位作为低层背景装饰；木柴右边对齐按钮右边（页面右 28px）。
           木柴在篝火容器里水平居中（90/160 → 距右 35px），所以容器 right = 28 - 35 = -7px。 */
        #page-butler .fireplace-mini {
            position: absolute; top: 30px; right: -7px; z-index: 1;
            width: 160px; height: 150px;
            display: flex; justify-content: center; align-items: flex-end;
            pointer-events: none;
        }
        /* 上层内容（标题 / 按钮）盖在篝火之上 */
        #page-butler .butler-content {
            position: relative; z-index: 2;
            /* 火苗顶端约在 Y≈ 78（top:30 + 48），把标题顶部对齐到这里 */
            padding-top: 80px;
        }
        #page-butler .ambient-glow {
            position: absolute; bottom: 16px; width: 110px; height: 55px;
            background: var(--b-fire-main); filter: blur(40px); opacity: 0.45;
            animation: butler-glow-pulse 3s infinite ease-in-out;
        }
        #page-butler .fire-container {
            position: relative; width: 80px; height: 100px; z-index: 2; bottom: 22px;
        }
        #page-butler .flame {
            position: absolute; bottom: 0; left: 50%;
            transform-origin: bottom center; border-radius: 50% 50% 20% 20%;
            transform: translateX(-50%); filter: blur(1px);
        }
        #page-butler .flame-1 { width: 60px; height: 80px; background: var(--b-fire-dark); animation: butler-flicker 1.5s infinite ease-in-out; opacity: 0.8; }
        #page-butler .flame-2 { width: 45px; height: 60px; background: var(--b-fire-main); animation: butler-flicker 1.2s infinite 0.1s ease-in-out; }
        #page-butler .flame-3 { width: 25px; height: 40px; background: var(--b-fire-light); animation: butler-flicker 1s infinite 0.2s ease-in-out; }
        #page-butler .spark {
            position: absolute; width: 4px; height: 4px; background: white;
            border-radius: 50%; filter: blur(1px); opacity: 0;
            animation: butler-spark-rise 2s infinite linear;
        }
        #page-butler .fire-container .spark:nth-child(4) { left: 30%; animation-delay: 0.2s; }
        #page-butler .fire-container .spark:nth-child(5) { left: 50%; animation-delay: 0.8s; }
        #page-butler .fire-container .spark:nth-child(6) { left: 70%; animation-delay: 1.4s; }
        #page-butler .logs {
            position: absolute; bottom: 14px; width: 90px; height: 12px;
            background: var(--b-log); border-radius: 6px; z-index: 3;
            box-shadow: inset 0 -2px 5px rgba(0,0,0,0.5);
        }
        #page-butler .logs::before, #page-butler .logs::after {
            content: ''; position: absolute; width: 100%; height: 100%;
            background: #2b1a0f; border-radius: 6px;
        }
        #page-butler .logs::before { transform: rotate(15deg); }
        #page-butler .logs::after { transform: rotate(-15deg); }

        @keyframes butler-flicker {
            0%, 100% { transform: translateX(-50%) scale(1, 1) rotate(0deg); }
            33% { transform: translateX(-52%) scale(0.9, 1.1) rotate(-2deg); }
            66% { transform: translateX(-48%) scale(1.1, 0.9) rotate(2deg); }
        }
        @keyframes butler-glow-pulse {
            0%, 100% { opacity: 0.3; transform: scale(1); }
            50% { opacity: 0.6; transform: scale(1.2); }
        }
        @keyframes butler-spark-rise {
            0% { transform: translateY(0) scale(1); opacity: 0; }
            20% { opacity: 1; }
            100% { transform: translateY(-100px) scale(0); opacity: 0; }
        }

        /* 标题栏：与下方按钮左对齐（同一 padding），与火顶端齐平 */
        #page-butler .butler-titlebar {
            padding: 0 28px 8px 28px;
        }
        #page-butler .butler-title {
            font-size: 22px; font-weight: 600; letter-spacing: 1px; color: var(--b-text); margin: 0;
            line-height: 1.1;
        }
        #page-butler .butler-coin {
            margin-top: 4px; font-size: 14px; color: var(--b-fire-light); font-weight: 700; letter-spacing: 0.5px;
        }
        #page-butler .butler-coin .balance-num { color: var(--b-fire-light); }
        /* 灰色随机科普条：底部约与木柴底端齐平 */
        #page-butler .butler-tip {
            margin-top: 22px;
            font-size: 14px; line-height: 1.5;
            color: #6a6a6a; font-weight: 400; letter-spacing: 0.3px;
            min-height: 20px; max-width: 88%;
        }

        /* 三个胶囊按钮（接近直角圆角） —— 在科普条下方留出空隙 */
        #page-butler .butler-buttons {
            display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 12px;
            padding: 24px 28px 28px 28px;
        }
        #page-butler .butler-badge.color-orange { grid-column: 1 / -1; }
        #page-butler .butler-badge {
            display: flex; align-items: center; gap: 10px;
            min-width: 0;
            padding: 14px 16px; border-radius: 6px;
            font-size: 14px; font-weight: 600; letter-spacing: 0.5px;
            cursor: pointer; transition: 0.25s; user-select: none;
            position: relative;
        }
        #page-butler .butler-badge:hover { transform: translateY(-1px); filter: brightness(1.15); }
        #page-butler .butler-badge:active { transform: scale(0.98); }
        #page-butler .butler-badge .badge-icon { font-size: 18px; line-height: 1; }
        #page-butler .butler-badge .badge-label { flex: 1; min-width: 0; white-space: normal; overflow-wrap: anywhere; word-break: break-word; }
        #page-butler .butler-badge .badge-lock {
            position: absolute; left: 12px; top: 50%; transform: translateY(-50%);
            align-items: center; gap: 3px;
            font-size: 11px; font-weight: 700; padding: 4px 7px; border-radius: 5px;
            background: rgba(0,0,0,0.8); color: #fff; white-space: nowrap;
            box-shadow: 0 1px 5px rgba(0,0,0,0.55); pointer-events: none; z-index: 3;
        }
        #page-butler .butler-badge.color-orange { background: rgba(255, 94, 2, 0.12); color: var(--b-fire-main); border: 1px solid rgba(255, 94, 2, 0.35); }
        #page-butler .butler-badge.color-orange:hover { background: rgba(255, 94, 2, 0.2); }
        #page-butler .butler-badge.color-green  { background: rgba(67, 160, 71, 0.12); color: #6dd672;            border: 1px solid rgba(67, 160, 71, 0.35); }
        #page-butler .butler-badge.color-green:hover  { background: rgba(67, 160, 71, 0.2); }
        #page-butler .butler-badge.color-blue   { background: rgba(59, 130, 246, 0.12); color: #7eaaff;           border: 1px solid rgba(59, 130, 246, 0.35); }
        #page-butler .butler-badge.color-blue:hover   { background: rgba(59, 130, 246, 0.2); }
        #page-butler .butler-badge.color-purple { background: rgba(155, 89, 182, 0.12); color: #c79be6;           border: 1px solid rgba(155, 89, 182, 0.35); }
        #page-butler .butler-badge.color-purple:hover { background: rgba(155, 89, 182, 0.22); }
        #page-butler .butler-badge.color-yellow { background: rgba(234, 179, 8, 0.14); color: #f5c542;          border: 1px solid rgba(234, 179, 8, 0.4); }
        #page-butler .butler-badge.color-yellow:hover { background: rgba(234, 179, 8, 0.24); }
        #page-butler .butler-badge.locked { cursor: not-allowed; }
        #page-butler .butler-badge.locked .badge-icon { opacity: 0.3; }
        #page-butler .butler-badge.locked .badge-label { opacity: 0.35; }
        #page-butler .butler-badge.locked:hover { transform: none; filter: none; }
        /* ===== 子页面（修缮 / 跳跃 / 扩建模态）继承 butler 深色风格 ===== */
        #page-repair, #page-jump {
            --b-bg: #1a1a1b;
            --b-card: #252526;
            --b-card-hi: #2f2f30;
            --b-fire-main: #FF5E02;
            --b-fire-light: #FFB830;
            --b-fire-dark: #E23101;
            --b-text: #e0e0e0;
            --b-muted: #888;
            --b-line: rgba(255,255,255,0.08);
            background: var(--b-bg);
            color: var(--b-text);
        }
        #page-repair .app-header,
        #page-jump .app-header {
            background: rgba(0,0,0,0.35) !important;
            border-bottom: 1px solid var(--b-line);
        }
        #page-repair .header-title,
        #page-jump .header-title { color: var(--b-text); }
        #page-repair .btn-back,
        #page-jump .btn-back { color: var(--b-text); }
        #page-repair .balance-pill,
        #page-jump .balance-pill {
            background: rgba(255,184,48,0.1); color: var(--b-fire-light);
            border: 1px solid rgba(255,184,48,0.3);
        }
        #page-repair .btn-mini-icon,
        #page-jump .btn-mini-icon {
            background: rgba(255,255,255,0.06) !important; color: var(--b-text);
            border: 1px solid var(--b-line);
        }

        /* page-repair 主区域 */
        #page-repair .butler-dash { background: var(--b-bg); }
        /* 关键：scan-zone 在原 css 里是白底，这里全部去掉，让深色页面背景透出来 */
        #page-repair .scan-zone {
            background: transparent !important;
            padding: 0 !important; margin-bottom: 0 !important;
            box-shadow: none !important; border-radius: 0 !important;
        }
        /* ===== 全面修缮扫描 ===== */
        #page-repair { position: relative; }
        .fullscan-box {
            background: var(--b-card); border: 1px solid var(--b-line);
            border-radius: 8px; padding: 14px; margin-bottom: 12px; text-align: center;
            position: relative;
        }
        .fullscan-go-btn {
            margin-top: 10px; width: 100%; padding: 10px; border: none; cursor: pointer;
            color: #fff; font-weight: 700; font-size: 14px; border-radius: 6px;
            background: linear-gradient(90deg, var(--b-fire-main), var(--b-fire-light));
        }
        .fullscan-collapse {
            position: absolute; top: 8px; right: 10px; z-index: 6;
            background: rgba(0,0,0,0.25); color: #fff; border: none; cursor: pointer;
            border-radius: 6px; padding: 4px 8px; font-size: 12px;
        }
        .fullscan-result { margin-top: 6px; text-align: left; }
        /* 展开态：铺满 #page-repair，挤掉投入物品窗口 */
