        72% { opacity: 1; transform: scale(1) translateY(0); }
        100% { opacity: 0; transform: scale(0.96) translateY(-26px); }
    }
    @keyframes giftEmojiSpin {
        0% { transform: rotate(-18deg) scale(0.6); }
        20% { transform: rotate(8deg) scale(1.15); }
        40% { transform: rotate(-4deg) scale(1); }
        100% { transform: rotate(0deg) scale(1); }
    }
    /* ===== 礼包清单视图（阶段2） ===== */
    /* card 在清单模式下定宽定高，仪式/清单两视图叠在同一卡片里切换 */
    .gift-toast-card.mode-list {
        width: 300px; height: 360px; padding: 0;
        animation: none; /* 切到清单后停掉仪式的浮现渐隐动画 */
        overflow: hidden;
    }
    .gift-stage { width: 100%; }
    /* 阶段1仪式视图：补回原 card 的居中+间距（多包一层 intro 后需在此重设） */
    .gift-stage-intro { display: flex; flex-direction: column; align-items: center; gap: 10px; }
    .gift-stage-list { display: none; flex-direction: column; height: 100%; box-sizing: border-box; padding: 20px 0 18px 0; }
    .gift-toast-card.mode-list .gift-stage-intro { display: none; }
    .gift-toast-card.mode-list .gift-stage-list { display: flex; animation: giftListFade 0.32s ease-out both; }
    @keyframes giftListFade { from { opacity: 0; } to { opacity: 1; } }
    .gift-list-title {
        text-align: center; font-size: 17px; font-weight: 900; letter-spacing: 1px;
        color: #ffe7a8; text-shadow: 0 2px 8px rgba(0,0,0,0.6);
        padding: 0 20px 14px 20px; flex-shrink: 0;
    }
    /* 滚动区：填满中间，隐形滚动条 */
    .gift-list-scroll {
        flex: 1; min-height: 0; overflow-y: auto; padding: 0 18px;
        display: flex; flex-direction: column; gap: 10px;
        scrollbar-width: none; -ms-overflow-style: none;
    }
    .gift-list-scroll::-webkit-scrollbar { width: 0 !important; height: 0 !important; display: none !important; }
    /* 单个物品卡片：emoji方框(占两行高) + 右侧名/描述 */
    .gift-item-card {
        display: flex; align-items: center; gap: 12px;
        padding: 10px 12px; border-radius: 12px;
        background: rgba(255,255,255,0.06); border: 1px solid rgba(255,215,128,0.18);
        animation: giftCardRise 0.42s cubic-bezier(0.22,1,0.36,1) both;
    }
    @keyframes giftCardRise { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: translateY(0); } }
    .gift-item-emoji {
        flex-shrink: 0; width: 46px; height: 46px; border-radius: 10px;
        display: flex; align-items: center; justify-content: center; font-size: 26px;
        background: rgba(255,184,48,0.14); border: 1px solid rgba(255,215,128,0.35);
    }
    /* 右侧文本列：min-width:0 是单行省略号生效的关键 */
    .gift-item-text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
    .gift-item-name {
        font-size: 14px; font-weight: 700; color: #fff;
        white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    }
    /* 描述：自适应填满单行，满了打省略号（不靠字数） */
    .gift-item-desc {
        font-size: 12px; color: #9a9a9a;
        white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    }
    .gift-list-confirm {
        flex-shrink: 0; margin: 14px 18px 0 18px; padding: 11px 0;
        border: none; border-radius: 14px; cursor: pointer;
        font-size: 15px; font-weight: 800; letter-spacing: 2px; color: #2a1c00;
        background: linear-gradient(135deg, #ffd780, #ffb830);
        box-shadow: 0 4px 16px rgba(255,184,48,0.4); transition: 0.2s;
    }
    .gift-list-confirm:hover { filter: brightness(1.08); transform: translateY(-1px); }
    .gift-list-confirm:active { transform: scale(0.98); }
    </style>
<script src="https://cdn.jsdelivr.net/npm/@twemoji/api@15.1.0/dist/twemoji.min.js" crossorigin="anonymous"></script>
