    // ================= 内置弹窗（替代浏览器原生 alert/confirm）=================
    // 复用 help-modal 深色风格，铺满 iframe 内的 #app-root，不再弹丑陋的浏览器原生框。
    let __uiModalResolver = null;
    function __uiModalResolve(val) {
        const mask = document.getElementById('ui-modal-mask');
        if (mask) mask.style.display = 'none';
        const r = __uiModalResolver;
        __uiModalResolver = null;
        if (typeof r === 'function') r(val);
    }
    function __uiModalOpen(msg, title, showCancel, okText) {
        // 若上一个弹窗还没关，先把它按"取消/否"收掉，避免 resolver 泄漏
        if (typeof __uiModalResolver === 'function') { try { __uiModalResolver(false); } catch (e) {} __uiModalResolver = null; }
        const mask = document.getElementById('ui-modal-mask');
        const t = document.getElementById('ui-modal-title');
        const m = document.getElementById('ui-modal-msg');
        const cancel = document.getElementById('ui-modal-cancel');
        const ok = document.getElementById('ui-modal-ok');
        if (t) t.innerText = title || '提示';
        if (m) m.innerText = (msg == null ? '' : String(msg));
        if (cancel) cancel.style.display = showCancel ? 'block' : 'none';
        if (ok) ok.innerText = okText || (showCancel ? '确定' : '知道了');
        if (mask) mask.style.display = 'flex';
        return new Promise(resolve => { __uiModalResolver = resolve; });
    }
    function uiAlert(msg, title) { return __uiModalOpen(msg, title || '提示', false, '知道了'); }
    function uiConfirm(msg, title) { return __uiModalOpen(msg, title || '确认', true, '确定'); }


