    function readExpandLevels() {
        let upLevel = 1, downLevel = 0;
        try {
            const md = window.parent.Mvu.getMvuData({ type: 'message', message_id: 'latest' });
            const sd = (md && md.stat_data) || {};
            upLevel = Number(sd['酒馆层数']) || 1;
            downLevel = Number(sd['酒馆地下层']) || 0;
        } catch (e) {
            console.warn('[扩建] 读取 MVU 失败', e);
        }
        return { upLevel, downLevel };
    }

    function refreshExpandModal() {
        const { upLevel, downLevel } = readExpandLevels();
        document.getElementById('expand-up-disp').textContent = upLevel;
        document.getElementById('expand-down-disp').textContent = downLevel;

        const btnUp = document.getElementById('expand-btn-up');
        const btnDown = document.getElementById('expand-btn-down');
        if (upLevel >= 2) { btnUp.disabled = true; btnUp.textContent = '⬆️ 已达上限'; }
        else { btnUp.disabled = false; btnUp.textContent = '⬆️ 解锁二楼'; }
        if (downLevel >= 1) { btnDown.disabled = true; btnDown.textContent = '⬇️ 已挖通'; }
        else { btnDown.disabled = false; btnDown.textContent = '⬇️ 解锁地下室'; }
    }

    function tryExpandTavern() {
        if ((Number(tavernStats.level) || 1) < 2) {
            uiAlert(`酒馆扩建未解锁！\n需要酒馆等级 >= 2\n当前等级: ${tavernStats.level || 1}`);
            return;
        }
        refreshExpandModal();
        document.getElementById('expand-mask').style.display = 'flex';
    }

    function closeExpand() {
        document.getElementById('expand-mask').style.display = 'none';
    }

    async function doExpand(direction) {
        const COST = { up: 10000, down: 5000 };
        const cost = COST[direction];
        if (tavernStats.balance < cost) {
            uiAlert(`余额不足！\n需要: ${cost} 铜币\n当前余额: ${tavernStats.balance}`);
            return;
        }
        const fn = window.parent && window.parent.expandTavern;
        if (typeof fn !== 'function') {
            uiAlert('未检测到 expandTavern 接口，请确认「酒馆结构」副脚本已加载');
            return;
        }
        const ok = fn(direction);
        if (!ok) {
            // 副脚本拒绝（通常是结构已满）：把 MVU 同步到上限值，避免按钮一直显示"可解锁"
            try {
                const Mvu = window.parent && window.parent.Mvu;
                if (Mvu && typeof Mvu.getMvuData === 'function' && typeof Mvu.replaceMvuData === 'function') {
                    const md = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                    if (md && md.stat_data) {
                        const key = direction === 'up' ? '酒馆层数' : '酒馆地下层';
                        const max = direction === 'up' ? 2 : 1;
                        if ((Number(md.stat_data[key]) || 0) < max) {
                            md.stat_data[key] = max;
                            await Mvu.replaceMvuData(md, { type: 'message', message_id: 'latest' });
                        }
                    }
                }
            } catch (e) { console.warn('[酒馆扩建] MVU 同步失败', e); }
            refreshExpandModal();
            uiAlert(direction === 'up' ? '解锁失败：地上层已达上限（最多 2 层）' : '解锁失败：地下层已达上限（最多 1 层）');
            return;
        }

        const labels = { up: '地上二层', down: '地下一层' };
        const structName = direction === 'up' ? '酒馆二楼' : '酒馆地下室';

        closeExpand();
        updateButlerUI();
        setLoading(true, `酒馆扩建中：${labels[direction]}...`);

        try {
            const prompt = `{{user}}花费${cost}铜币，让系统为酒馆增加了${structName}结构。`;

            const res = await generate({
                user_input: " ",
                injects: [{ role: 'system', content: prompt, position: 'in_chat', depth: 0, should_scan: true }],
                should_silence: true
            });

            await createChatMessages([{
                role: 'assistant',
                message: (res || '').trim()
            }]);

            // 把 MVU 楼层变量挂在【刚生成的 AI 楼】的快照上：删该楼时 MVU 会自动回滚到上一楼的快照
            try {
                const Mvu = window.parent && window.parent.Mvu;
                if (Mvu && typeof Mvu.getMvuData === 'function' && typeof Mvu.replaceMvuData === 'function') {
                    const md = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                    if (md && md.stat_data) {
                        const key = direction === 'up' ? '酒馆层数' : '酒馆地下层';
                        const base = direction === 'up' ? 1 : 0;
                        const cur = Number(md.stat_data[key]) || base;
                        md.stat_data[key] = cur + 1;
                        await Mvu.replaceMvuData(md, { type: 'message', message_id: 'latest' });
                    }
                }
            } catch (e) {
                console.warn('[酒馆扩建] MVU 楼层变量更新失败', e);
            }

            setLoading(false);
            updateButlerUI();
            uiAlert(`✨ 扩建成功！\n${labels[direction]} 已解锁\n新的剧情已展开，请查看聊天记录。`);
        } catch (e) {
            setLoading(false);
            console.error('[酒馆扩建] 生成失败:', e);
            uiAlert('扩建生成失败，但变量与楼层结构已更新。\n可手动让 AI 续写新场景。');
        }
    }

    // 把当前酒馆已解锁的所有房间列表（含两位 id）拼成 prompt 用文本，
    // 让 AI 输出方案时直接选这些房间的 id，方便后续装修记录稳定匹配回房间。
    function getRoomListForPrompt() {
        try {
            const fn = window.parent && window.parent.getTavernStructure;
            if (typeof fn !== 'function') return '';
            const struct = fn() || {};
            const lines = [];
            for (const fk of ['floor_1', 'floor_2', 'basement_1', 'outdoor']) {
                const floor = struct[fk];
                if (!floor || typeof floor !== 'object') continue;
                const fkLabel = { floor_1: '一层', floor_2: '二层', basement_1: '地下', outdoor: '户外' }[fk];
                for (const rk in floor) {
                    const r = floor[rk];
                    if (!r || !r.id) continue;
                    lines.push(`  [#${r.id}] ${r.name}（${fkLabel} · ${r.purpose || '-'} · ${r.location || '-'}）`);
                }
            }
            return lines.join('\n');
        } catch (e) { return ''; }
    }

    // 把页面滑到刚生成的方案位置；避免用户没意识到结果已出现在下方
    function scrollRepairResultIntoView(targetId) {
        setTimeout(() => {
            const dash = document.querySelector('#page-repair .butler-dash');
            const target = document.getElementById(targetId);
            if (!dash || !target) return;
            const delta = target.getBoundingClientRect().top - dash.getBoundingClientRect().top - 8;
            dash.scrollTo({ top: dash.scrollTop + delta, behavior: 'smooth' });
        }, 80);
    }

    // ================= 物品改造 (Combo) =================
    // state: keyword 是用户输入的房间/关键词；selectedItems 是 Map<id, {id,icon,name,desc}>；
    // plans 是 AI 解析出的方案数组；chosenIdx 是用户当前选中的方案下标。
    const comboState = {
        selectedItems: new Map(),
        plans: [],
        chosenIdx: -1,
    };

    // 读取背包：参考料理台的写法，过滤掉杂物间(inventory_storage_list)中的物品。
    function getButlerInventory() {
        try {
            const vars = (typeof TavernHelper !== 'undefined')
                ? (TavernHelper.getVariables({ type: 'chat' }) || {})
                : ((window.parent && window.parent.TavernHelper)
                    ? (window.parent.TavernHelper.getVariables({ type: 'chat' }) || {})
                    : {});
            const raw = vars.inventory_data || [];
            const hidden = vars.inventory_storage_list || [];
            return raw.filter(i => i && i.id && !hidden.includes(i.id));
        } catch (e) { console.warn('[combo] getButlerInventory failed', e); return []; }
    }

    // 读取杂物间：inventory_data 中 id 在 inventory_storage_list(杂物间)里的物品。
    function getButlerStorage() {
        try {
            const vars = (typeof TavernHelper !== 'undefined')
                ? (TavernHelper.getVariables({ type: 'chat' }) || {})
                : ((window.parent && window.parent.TavernHelper)
                    ? (window.parent.TavernHelper.getVariables({ type: 'chat' }) || {})
                    : {});
            const raw = vars.inventory_data || [];
            const hidden = vars.inventory_storage_list || [];
            return raw.filter(i => i && i.id && hidden.includes(i.id));
        } catch (e) { console.warn('[combo] getButlerStorage failed', e); return []; }
    }

    function renderComboInventoryBar() {
        const $bar = document.getElementById('combo-inv-bar');
        if (!$bar) return;
        const items = getButlerInventory();
        $bar.innerHTML = '';
        items.forEach(it => {
            const div = document.createElement('div');
            div.className = 'combo-chip' + (comboState.selectedItems.has(it.id) ? ' selected' : '');
            div.dataset.id = it.id;
            div.innerHTML = `<span class="chip-emoji">${it.icon || '📦'}</span><span class="chip-name">${it.name || ''}</span>`;
            div.title = `${it.name} (ID:${it.id})${it.desc ? '\n' + it.desc : ''}`;
            div.onclick = () => toggleComboItem(it);
            $bar.appendChild(div);
        });
    }

    function renderComboInputZone() {
        const $zone = document.getElementById('combo-input-zone');
        if (!$zone) return;
        $zone.innerHTML = '';
        for (const it of comboState.selectedItems.values()) {
            const chip = document.createElement('span');
            chip.className = 'combo-input-chip';
            chip.innerHTML = `<span>${it.icon || '📦'}</span><span>${it.name}</span><span class="x" data-id="${it.id}">✕</span>`;
            chip.querySelector('.x').onclick = (e) => { e.stopPropagation(); toggleComboItem(it); };
            $zone.appendChild(chip);
        }
    }

    function toggleComboItem(item) {
        if (comboState.selectedItems.has(item.id)) comboState.selectedItems.delete(item.id);
        else comboState.selectedItems.set(item.id, item);
        renderComboInventoryBar();
        renderComboInputZone();
    }

    // 给 prompt 用：列出当前已解锁房间，并附上当前 desc，让 AI 知道改造的起点是什么样
    function getRoomListWithDescForPrompt() {
        try {
            const fn = window.parent && window.parent.getTavernStructure;
            if (typeof fn !== 'function') return '';
            const struct = fn() || {};
            const lines = [];
            for (const fk of ['floor_1', 'floor_2', 'basement_1', 'outdoor']) {
                const floor = struct[fk];
                if (!floor || typeof floor !== 'object') continue;
                const fkLabel = { floor_1: '一层', floor_2: '二层', basement_1: '地下', outdoor: '户外' }[fk];
                for (const rk in floor) {
                    const r = floor[rk];
                    if (!r || !r.id) continue;
                    lines.push(`  [#${r.id}] ${r.name}（${fkLabel} · ${r.purpose || '-'} · ${r.location || '-'}）：${r.desc || ''}`);
                }
            }
            return lines.join('\n');
        } catch (e) { return ''; }
    }

    async function startComboScan() {
        const keyword = (document.getElementById('combo-room-input').value || '').trim();
        if (comboState.selectedItems.size === 0) { uiAlert('请至少投入一件物品'); return; }

        setLoading(true, keyword ? `正在为 [${keyword}] 设计改造方案...` : '正在为投入的物品挑选合适房间...');

        const items = Array.from(comboState.selectedItems.values());
        const itemsBlock = items.map(i => `  - [ID:${i.id}] ${i.icon || ''} ${i.name}：${i.desc || '（无描述）'}`).join('\n');
        const roomList = getRoomListWithDescForPrompt();
        const roomListBlock = roomList ? `\n\n当前酒馆所有可改造房间（含现有家居描述）：\n${roomList}\n` : '';

        // keyword 选填：有值就按指定房间/思路匹配；留空则让 AI 自行从房间名单里挑最适合投入物品的房间
        const comboTargetLine = keyword
            ? `想把以下物品投入到 [${keyword}] 进行家居改造`
            : `想用以下物品给酒馆做家居改造，请你从下方房间名单里自行挑选最适合这些物品的房间`;
        const comboRule1 = keyword
            ? `1. 必须先在房间名单里精确匹配 [${keyword}]（按编号、名称或关键词模糊判断）。如果命中则每行第一列用对应两位编号；命中不到则放弃输出（仅输出空 <COMBO></COMBO><EVOLUTION>[]</EVOLUTION>）。`
            : `1. 从房间名单里挑选 1~2 个最适合容纳这些物品的房间（按物品用途与房间功能/现有家居判断），每行第一列用对应两位编号；名单为空时才放弃输出（仅输出空 <COMBO></COMBO><EVOLUTION>[]</EVOLUTION>）。`;
        const prompt = `[System]暂停角色扮演，禁止输出正文、状态栏和任何其它格式，仅严格按照以下要求格式输出。
指令: {{user}}${comboTargetLine}，请基于"现有家居描述"结合这些物品，给出 3 到 4 个改造方案。${roomListBlock}

{{user}}投入的物品：
${itemsBlock}

基本要求:
${comboRule1}
2. 每个方案对应一种"投入物品 + 改造手法"组合，方案之间应该有明显差异（投入子集 / 价位 / 风格不同）。
3. 新描述必须基于现有家居描述，投入简单物品（杯子、沙发）→现有家居描述大部分保留，基本固定不变，仅稍作改动，将投入物品关键词放进去（比如桌上放着杯子、靠墙是松软的沙发）；投入高质量物品（如SSR道具、大件家具）→在保留现有家居描述的前提下（字数超限可适当缩略，但尽量留下原先的重要家居关键字，比如原来有个壁炉，你不能加了个SSR道具就把壁炉丢了）则稍微着重（但也不能超过1句话）这件物品的描述。整个描述字数限制在 15 到 80 字以内
   - ❌ 反例：原描述"内侧有一长条柜台，墙边有一壁炉"，投入书架后写成"摆放了书架"（柜台与壁炉凭空消失）。
   - ✅ 正例：同样情况写"内侧有一长条柜台，墙边壁炉旁立了一排枫木书架"。
4. 价格按是否需要安装或费力气来定：不需要安装、不费力气的（直接摆放、点缀、挂上去即可）→ 0 铜币；需要安装、施工或费力气的（砌、装、改管线、大件搬运组装、翻新整改等）→ 50~200 之间的整数，越费工越贵。请贴合实际，不要随意给高价。
5. "消耗物品 ID 列表"必须是上面"投入物品"中的子集，多个用英文逗号分隔；至少消耗 1 件。
6. "用 1~3 句话写清楚这个方案具体做了什么改动，不少于10个字。
7. 你需要为每个方案给出"基建度增量"，范围 1~50 的纯整数，按投入物品的品质与体量判定：普通小件点缀(挂画、摆件、小工具)→1~3；普通家具(桌椅、书架、沙发)→5~10(沙发约8)；大型家具或设备(吧台、壁炉、大型机械、整套设施)→15~25(大型设备约20)；稀有/顶级物品(SSR、传说级、镇店之宝)→可顶格到 40~50。物品越优质、越大型，增量越高，请贴合实际不要随意给满。
8. **善用物品描述里的重要信息。** 如果投入物品的描述里带有值得一提的来历或功能（例如是SSR道具、有特殊纪念意义、或具备某种特别功能/效果），可以考虑在改造方案中提到，让新描述或改动更有故事感与合理性（例如把"曾属于某位名匠的旧砧"设计成房间里被郑重陈列/沿用的标志物）。如无重要描述（比如只是物品基础参数）则正常处理即可，不必强行拔高。

【🌱 演化物品机制】
一些"放着会自己变化"的物品适合用演化模式呈现，例如：
- 种子类（花种、菜种、果种 → 嫩芽 → 成熟植物）
- 蛋类（鸡蛋、鸭蛋 → 小鸡/小鸭 → 母鸡/鸭）
- 幼畜（小奶牛、雏鸟 → 成年奶牛/鸟 → 持续产出）
- 长期熬制品（魔药基底 → 半成品 → 成品）
- 酿酒原料（葡萄、麦芽 → 发酵中 → 陈酿）
- 易腐食物（新鲜面包、牛奶 → 略走味 → 发霉变质）
- 生火（燃烧的火 → 灰烬）
- 信箱/邮件类（空信箱 → 收到信的信箱）
- 其它任何符合"放着会自己变化"直觉的物品

即使所有投入物品都很适合做演化，也**至少保留一半（向下取整）的方案做成"不带演化的普通改造方案"**，让玩家能在【常规改造】和【触发特殊方案】之间有对比可选；不要因为投入的全是演化向物品就把所有方案都做成演化方案。具体配额：**3 个方案时最多 1 条带演化、4 个方案时最多 2 条带演化**。普通方案按基本要求 #3 把投入物品作为常规物件写进新描述（例如同一颗番茄种子，在演化方案里被做成"会逐阶段长大的活物"，在普通方案里就是"撒在花盆里的种子点缀"或"被打包成种子礼盒摆样"——同物两种处理思路）。
演化方案的"新描述"**只描写改造好的房间整体环境与配套布置，不要再提到那个演化物品本身**（演化物品的形态变化由系统单独渲染演化阶段，再写进新描述会重复）。例：投入"番茄种子"且做成演化物品时，✅ 写"翻松的菜畦旁备好水壶与小铲，垄边搭起防风小架"；❌ 不要写"菜畦里播下了番茄种子"。同一方案里**没**变成演化物品的其他投入物品，仍按基本要求 #3 写进新描述。
演化物品仍要写在该方案的"消耗物品 ID 列表"中（视为从背包移到房间）。

楼层差建议（stages 里的 floor_offset，单位 = AI 回复数）：变化快(蛋孵化、面包发霉) 5~10；中等(幼畜成长、酿酒发酵) 15~25；很慢(陈酿、长期熬制) 30~50。每个演化物品给 2~4 个递进阶段，每阶段含 emoji + floor_offset(正整数) + state(≤8字)。

**base_state / state 必须是"此刻该物品长什么样"的名词短语**，描述物品本身，不要用"……中 / 正在……"等动词进行时。✅ 例："刚播种的番茄种子" / "冒头的嫩芽" / "结果的番茄藤" / "孵化中的蛋"（"中"作为形容词修饰名词时 OK，整体仍是名词短语）；❌ 例："番茄播种中" / "发芽中" / "正在结果"。

【🔚 end_type — 到达最后阶段后怎么办】
每条演化必须指定 end_type，三选一：
- **"vanish"**（消失型）：到达最后阶段后下一层就移除。适合：燃烧物(火→余烬→灰)、易腐食物(面包→霉)、一次性消耗品。
- **"periodic"**（周期产出型）：到达最后阶段后停留，每 period_interval 层可收一次产物。适合：母鸡(产蛋)、奶牛(产奶)、果树(结果)、采集池等"会持续产出物品"的物件。**必须同时给出 period_item: {icon, name, desc}**——这就是每周期产出的新物品。
- **"trigger"**（事件触发型）：到达最后阶段后停留，每 period_interval 层可被点击触发一段 AI 续写（带预设的 generate）。适合：信箱(收信)、感应阵(异常)、神龛(神谕)、留言板等"会承接新事件"的物件。**必须同时给出 trigger_keyword**——一句话场景描述，会作为系统提示喂给 AI 让它续写一段正文（例："信箱里收到了一封笔迹陌生的新信件"）。

period_interval 取 5~30 之间的整数，根据物品节奏自定（产蛋密一点 5~8，神谕慢一点 20~30）。vanish 类型不需要 period_interval / period_item / trigger_keyword。

输出格式（必须严格遵守，标签外不得有任何文字）：
<COMBO>
房间编号|房间名|新描述(15~80字)|价格(纯数字)|改造动作摘要(≤20字)|消耗物品ID列表|基建度增量(1~50纯数字)
</COMBO>
<EVOLUTION>
[{
  "plan_idx": 1,
  "item_id": "<消耗物品ID>",
  "base_emoji": "<初始emoji>", "base_state": "<初始形态名词短语，≤8字>",
  "stages": [{"emoji":"<emoji>","floor_offset":<正整数>,"state":"<该阶段形态名词短语，≤8字>"}],
  "end_type": "vanish" | "periodic" | "trigger",
  "period_interval": <仅 periodic/trigger 用，整数 5~30>,
  "period_item": {"icon":"<emoji>","name":"<产物名>","desc":"<可选描述>"},  // 仅 periodic 用
  "trigger_keyword": "<事件场景一句话>"   // 仅 trigger 用
}]
</EVOLUTION>
（plan_idx 从 1 开始，指向上面 <COMBO> 内的方案行号。同一个 plan_idx 可挂多条演化记录。本轮没有任何演化物品则 <EVOLUTION>[]</EVOLUTION>。）
`;
        try {
            const res = await smartGenerate({
                user_input: ' ',
                ordered_prompts: ['world_info_before', 'char_description', buildRecentHistoryPrompt(6), { role: 'system', content: prompt }],
                quiet: true,
            });
            parseComboData(extractTagged(res, 'COMBO'), extractTagged(res, 'EVOLUTION'));
        } catch (e) {
            console.error('[combo] scan failed', e);
            uiAlert('改造方案生成失败，请稍后再试');
        }
        setLoading(false);
    }

    // 6 列：房间编号|房间名|新描述|价格|改造动作|消耗物品ID列表；evolutionText 是 <EVOLUTION>...</EVOLUTION> 里的 JSON
    function parseComboData(text, evolutionText) {
        comboState.plans = [];
        comboState.chosenIdx = -1;
        const $cont = document.getElementById('combo-container');
        $cont.innerHTML = '';

        const lines = String(text || '').split('\n').map(s => s.trim()).filter(s => s.includes('|'));
        for (const line of lines) {
            const parts = line.split('|').map(s => s.trim());
            if (parts.length < 5) continue;
            const roomId = parts[0].replace(/[#\[\]]/g, '');
            const roomName = parts[1].replace(/\s*[（(][^)）]*[)）]\s*$/, '').trim();
            const newDesc = parts[2];
            const cost = parseInt(parts[3], 10) || 0;
            const actionDesc = parts[4];
            const consumeIds = (parts[5] || '').split(/[,，、]/).map(s => s.trim()).filter(Boolean);
            // 第7列：AI 给的基建度增量，clamp 到 1~50；缺省/非法则保底 1
            const aiInfra = parseInt((parts[6] || '').replace(/[^\d-]/g, ''), 10);
            const infraGain = Math.min(50, Math.max(1, Number.isFinite(aiInfra) ? aiInfra : 1));
            // 校验：消耗的 id 必须在玩家投入清单里；不在的丢掉
            const validIds = consumeIds.filter(id => comboState.selectedItems.has(id));
            if (!roomId || !newDesc || validIds.length === 0) continue;
            comboState.plans.push({ roomId, roomName, newDesc, cost, actionDesc, consumeIds: validIds, infraGain, evolutions: [] });
        }

        // 解析 EVOLUTION JSON，按 plan_idx 挂到对应方案上
        if (evolutionText) {
            let evoArr = [];
            try {
                const raw = String(evolutionText).trim();
                if (raw && raw !== '[]') {
                    const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
                    evoArr = JSON.parse(cleaned);
                    if (!Array.isArray(evoArr)) evoArr = [];
                }
            } catch (e) { console.warn('[combo] EVOLUTION JSON 解析失败，跳过演化', e); evoArr = []; }
            for (const evo of evoArr) {
                const idx1 = Number(evo && evo.plan_idx) - 1;
                if (!(idx1 >= 0 && idx1 < comboState.plans.length)) continue;
                const itemId = String(evo.item_id || '').trim();
                if (!itemId || !comboState.selectedItems.has(itemId)) continue;
                const stages = Array.isArray(evo.stages) ? evo.stages.map(s => ({
                    emoji: String(s.emoji || ''),
                    floor_offset: Number(s.floor_offset) || 0,
                    state: String(s.state || ''),
                })).filter(s => s.floor_offset > 0) : [];
                if (stages.length === 0) continue;
                const it = comboState.selectedItems.get(itemId);
                // 解析 end_type 及相关字段
                let endType = String(evo.end_type || 'vanish').toLowerCase();
                if (!['vanish','periodic','trigger'].includes(endType)) endType = 'vanish';
                let periodInterval = Math.round(Number(evo.period_interval) || 0);
                if (periodInterval < 1) periodInterval = 8;
                if (periodInterval > 50) periodInterval = 50;
                let periodItem = null;
                if (endType === 'periodic') {
                    const pi = evo.period_item || {};
                    if (pi && pi.name) {
                        periodItem = { icon: String(pi.icon || '📦'), name: String(pi.name), desc: String(pi.desc || '') };
                    } else { endType = 'vanish'; }
                }
                let triggerKeyword = null;
                if (endType === 'trigger') {
                    const kw = String(evo.trigger_keyword || '').trim();
                    if (kw) triggerKeyword = kw; else endType = 'vanish';
                }
                comboState.plans[idx1].evolutions.push({
                    item_id: itemId,
                    base_emoji: String(evo.base_emoji || (it && it.icon) || '📦'),
                    base_state: String(evo.base_state || ''),
                    stages,
                    itemName: it ? it.name : '',
                    endType,
                    periodInterval,
                    periodItem,
                    triggerKeyword,
                });
            }
        }

        if (comboState.plans.length === 0) {
            $cont.innerHTML = '<div style="text-align:center;color:#999;padding:20px;font-size:12px;">AI 没能给出有效方案，换个房间或关键词再试试？</div>';
            $cont.classList.add('active');
            document.getElementById('combo-foot').classList.remove('active');
            scrollRepairResultIntoView('combo-container');
            return;
        }

        comboState.plans.forEach((p, i) => {
            const card = document.createElement('div');
            card.className = 'combo-plan-card';
            card.dataset.idx = i;
            const itemsLabel = p.consumeIds.map(id => {
                const it = comboState.selectedItems.get(id);
                return it ? `${it.icon || ''}${it.name}` : `ID:${id}`;
            }).join('、');
            const evoLabel = (p.evolutions && p.evolutions.length)
                ? (() => { const _evoEmojis = p.evolutions.map(e => `<span class="combo-plan-evo-emoji">${e.base_emoji || '🌱'}</span>`).join(''); const _evoDetail = p.evolutions.map(e => { const tag = e.endType === 'periodic' ? `[周期产 ${e.periodItem ? e.periodItem.icon + e.periodItem.name : '?'}/${e.periodInterval}楼]` : e.endType === 'trigger' ? `[事件触发/${e.periodInterval}楼]` : '[自然消失]'; return `${e.base_emoji}${e.itemName || ''}→${e.stages.map(s => s.emoji).join('→')} ${tag}`; }).join(' / '); return `<div class="combo-plan-evo"><div class="combo-plan-evo-trigger" onclick="event.stopPropagation(); this.parentElement.classList.toggle('expanded');">${_evoEmojis}<span>触发特殊方案！</span></div><div class="combo-plan-evo-detail">🌱 ${_evoDetail}</div></div>`; })()
                : '';
            card.innerHTML = `
                <div class="combo-plan-head">
                    <span class="combo-plan-title">${fsGetRoomEmoji({areaId: p.roomId, areaName: p.roomName})} ${p.roomName} · 方案 ${i+1}${(p.evolutions && p.evolutions.length) ? ' 🌱' : ''}</span>
                    <span class="combo-plan-cost">${p.cost} 铜币 · 🏛️ 基建+${p.infraGain}</span>
                </div>
                <div class="combo-plan-action">🛠 ${p.actionDesc}</div>
                <div class="combo-plan-newdesc">${p.newDesc}</div>
                <div class="combo-plan-items">将消耗：${itemsLabel}</div>
                ${evoLabel}
            `;
            card.onclick = () => selectComboPlan(i);
            $cont.appendChild(card);
        });
        $cont.classList.add('active');
        document.getElementById('combo-foot').classList.add('active');
        updateComboFoot();
        scrollRepairResultIntoView('combo-container');
    }

    function selectComboPlan(idx) {
        comboState.chosenIdx = (comboState.chosenIdx === idx) ? -1 : idx;
        document.querySelectorAll('#combo-container .combo-plan-card').forEach(c => {
            c.classList.toggle('selected', Number(c.dataset.idx) === comboState.chosenIdx);
        });
        updateComboFoot();
    }

    function updateComboFoot() {
        const p = comboState.plans[comboState.chosenIdx];
        document.getElementById('combo-cost-disp').innerText = p ? p.cost : 0;
        document.getElementById('combo-items-disp').innerText = p ? p.consumeIds.length : 0;
        const infraEl = document.getElementById('combo-infra-disp');
        if (infraEl) infraEl.innerText = p ? p.infraGain : 0;
        document.getElementById('btn-combo-confirm').disabled = !p;
    }

        // ================= 全面修缮扫描 =================
    const fullscanState = { areas: [], chosen: {}, viewTier: {} };

    const FULLSCAN_TIER_COST = { low: 100, mid: 1000, high: 5000 };
    const FULLSCAN_TIER_LABEL = { low: '初级', mid: '中级', high: '高级' };

    function fsSanitizeHex(s) {
        const v = String(s || '').trim();
        return /^#[0-9a-fA-F]{6}$/.test(v) ? v : null;
    }
    function fsClampInt(v, min, max, dft) {
        let n = parseInt(v, 10);
        if (!Number.isFinite(n)) return dft;
        if (n < min) n = min;
        if (n > max) n = max;
        return n;
    }
    function fsPickFallbackColor(summary) {
        const s = String(summary || '');
        if (/香|花|玫瑰|芬芳|氛/.test(s)) return '#E84393';
        if (/洁|扫|净|清洁|擦|拖/.test(s)) return '#66CCFF';
        if (/修|补|换|整|固/.test(s)) return '#F0932B';
        if (/菌|毒|消|防疫/.test(s)) return '#00B894';
        return '#74B9FF';
    }
    // 按 name 兜底反查房间（findRoomById 找不到时用）
    function fsFindRoomByName(name) {
        try {
            const fn = window.parent && window.parent.getTavernStructure;
            if (typeof fn !== 'function') return null;
            const struct = fn() || {};
            const target = String(name || '').trim();
            if (!target) return null;
            for (const fk of ['floor_1', 'floor_2', 'basement_1', 'outdoor']) {
                const floor = struct[fk];
                if (!floor || typeof floor !== 'object') continue;
                for (const rk in floor) {
                    const r = floor[rk];
                    if (r && String(r.name || '').trim() === target) {
                        return { floorKey: fk, roomId: rk, room: r };
                    }
                }
            }
        } catch (e) {}
        return null;
    }

    // 按 area 查房间 emoji（先 id 再 name，查不到给默认）
    function fsGetRoomEmoji(area) {
        try {
            const findFn = window.parent && window.parent.findRoomById;
            let hit = null;
            if (typeof findFn === 'function' && area.areaId) hit = findFn(area.areaId);
            if (!hit) hit = fsFindRoomByName(area.areaName);
            if (hit && hit.room && hit.room.emoji) return hit.room.emoji;
        } catch (e) {}
        return '🏠';
    }

    // 取近 n 楼对话，拼成一条 system prompt（失败回退到全量 chat_history 占位）
    function buildRecentHistoryPrompt(n) {
        try {
            if (typeof getChatMessages !== 'function') return 'chat_history';
            const all = getChatMessages('0-{{lastMessageId}}') || [];
            const recent = all.slice(-n);
            if (!recent.length) return 'chat_history';
            const text = recent.map(m => {
                const role = (m.role === 'user') ? '用户' : (m.role === 'assistant' ? 'AI' : '系统');
                return role + '：' + String(m.message || '').slice(0, 800);
            }).join('\n');
            return { role: 'system', content: '[以下是近期剧情，如用户**本次投入装修的物品**已出现在近期剧情中，**并在近期剧情中使用该物品完成装修/装饰**，则用户想法可能是补一个房间描述方案。那么，你需要在遵守给定字数、强调、格式等规则的前提下，按照该物品在近期剧情中是如何进行房间装修的，给出相应的房间描述方案（意思就是按照剧情反推描述方案，剧情里是怎么装修的，方案就怎么写）。如果没出现这种\'投入物品在近期剧情中有出现，本次目的是补一个房间描述方案\'的情况，请忽略本要求]\n' + text };
        } catch (e) {
            return 'chat_history';
        }
    }

    const FULLSCAN_INSTRUCTION = '[System]暂停角色扮演，禁止输出正文、状态栏和任何其它格式，仅严格按照以下要求格式输出，本次回复必须体现以下指令执行后的结果，不进行任何形式的二次确认或解释。\n指令: 基于酒馆目前的装潢情况，输出酒馆目前 5 个最需要修缮或升级的设施 / 某个房间（如大厅、马厩、1号客房...可以是 <Tavern_Infrastructure> 已有记录的区域，也可以是下方区域名单里其它尚未修缮的区域（含荒地等空地）；但只能从下方「酒馆区域名单」里选，禁止虚构名单外的区域）。\n对于每个区域，必须严格提供 3 个不同价位的升级方案：\n低级方案（消耗 100 铜币）：简单的修补、清洁、清新空气或增加小物件，也可以是目前亟待修整的地方（如窗户烂了、大门破了、水管堵了等小型修整）。\n简单的修补、清洁或增加小物件(如{{random:矮人重工锻造风,温馨田园原木风,精灵自然藤蔓风,现代简约快捷酒店风,中世纪复古风}}摆件/小家装)。\n中级方案（消耗 1000 铜币）：更换家具或翻新，也可以是中、大型修整（如设备损坏、房顶塌了等）。\n更换家具或翻新。(如{{random:矮人重工锻造风,温馨田园原木风,精灵自然藤蔓风,现代简约快捷酒店风,中世纪复古风}}的{{random:小型照明设备,家具,局部家装}})\n高级方案（消耗 5000 铜币）：大型的硬装整改翻新。\n大型的硬装整改翻新(如{{random:水电(选一),墙面或地板材质,西幻风,布景或现代风装修,恒温法阵,照明设备}})。\n注意: 如区域在 <Tavern_Infrastructure> 中已有修缮记录，应以相关修缮记录为基础，判断目前该区域基建水平，设计符合价位的方案描述。';

    function buildFullScanFormatSpec() {
        return [
            '',
            '【方案类型判定（kind）】',
            '- 若方案新增 / 更换家居、家具或结构（翻新、换床、砌墙、加吧台、大型整改）→ kind 为 "hard"，必须给 new_desc。',
            '- 若方案只是清洁 / 除味 / 修补门窗水管 / 摆香薰等不改变家居构成的小修小补 → kind 为 "buff"，必须给 buff_name、buff_color、buff_duration，且不要给 new_desc。',
