            'new_desc 必须包含该区域现有描述里的全部标志性大件（柜台 / 壁炉 / 床 / 吧台 / 楼梯等），只可调整语序、追加新内容，绝不可删除或让原有家居凭空消失。总字数 30~120。',
            '',
            '【buff 字段】',
            '- buff_name：≤6 字，展示在彩色标签里（示例：一尘不染 / 玫瑰香氛 / 明亮 / 坚固大门 / 神秘感 / 阴暗 / 暧昧氛围 / 魔法秘氛 / 翻新窗户 / 温馨）。',
            '- buff_color：一个 #RRGGBB 颜色码，要求中高饱和、明度适中、语义贴合，偏奶油风 / 布丁风那种柔和又有高级感的调子（不要发灰、不要荧光刺眼）。务必避开太浅发白（接近背景米色 #FFFEF1）和太深发黑（接近夜间背景 #2F3640）的颜色，否则会糊进背景看不清。示例：玫瑰香氛粉 #F48FB1 / 清洁冰蓝 #7EC8E3 / 温馨暖橙 #F0A868 / 魔法神秘紫 #A98EDA / 阴暗墨青 #5C7A89 / 暧昧绛红 #C96A7B。',
            '- buff_duration：该氛围持续的楼层数，建议 20~40 的整数。',
            '',
            '【其它要求】',
            '- 正好 5 个区域，每个区域正好 3 个方案，tier 依次为 low / mid / high。',
            '- area_id 与 area_name 必须严格取自上方区域名单（含荒地等空地）：area_id 必须是名单里的两位编号，area_name 用名单里的房间名，不得自创名单外的区域、也不得编造名称或把编号留空。',
            '- summary：1~3 句话的行为描述，中级、高级方案summary应该踩到new_desc中新增改动的每一个关键词（如新的关键改造、配置、家具等）。',
            '',
            '输出格式（必须严格遵守，标签外不得有任何文字）：',
            '<REPAIR>',
            '[',
            '  {"area_id":"01","area_name":"入口大厅","plans":[',
            '    {"tier":"low","cost":100,"kind":"buff","summary":"清扫并喷洒香氛","buff_name":"玫瑰香氛","buff_color":"#E84393","buff_duration":30},',
            '    {"tier":"mid","cost":1000,"kind":"hard","summary":"更换吧台桌椅","new_desc":"（含原文全部家居的完整新描述）"},',
            '    {"tier":"high","cost":5000,"kind":"hard","summary":"大厅整体翻新","new_desc":"（含原文全部家居的完整新描述）"}',
            '  ]}',
            ']',
            '</REPAIR>'
        ].join('\n');
    }

    async function startFullScan() {
        const page = document.getElementById('page-repair');
        if (page) page.classList.add('fullscan-expanded');
        const collapseBtn = document.getElementById('fullscan-collapse');
        if (collapseBtn) collapseBtn.style.display = 'block';
        setLoading(true, '正在巡查全馆，制定修缮方案...');
        try {
            const roomList = getRoomListWithDescForPrompt();
            const roomListBlock = roomList ? ('\n\n当前酒馆区域名单（含编号与现有描述）：\n' + roomList + '\n') : '';
            // 选填的改造意向：用户在输入框写了房间/关键词/思路时，作为倾向提示喂给 AI（留空则纯自动巡查）
            const fsKeyword = ((document.getElementById('fullscan-room-input') || {}).value || '').trim();
            const fsKeywordBlock = fsKeyword ? ('\n\n【{{user}}的改造意向（请优先围绕此意向选区域、定方案，但仍保持每区 3 档价位）】：' + fsKeyword + '\n') : '';
            const prompt = FULLSCAN_INSTRUCTION + roomListBlock + fsKeywordBlock + '\n' + buildFullScanFormatSpec();
            const res = await smartGenerate({
                user_input: ' ',
                ordered_prompts: ['world_info_before', 'char_description', buildRecentHistoryPrompt(10), { role: 'system', content: prompt }],
                quiet: true,
            });
            parseFullScanData(extractTagged(res, 'REPAIR'));
        } catch (e) {
            console.error('[fullscan] 扫描失败', e);
            uiAlert('全面扫描失败，请稍后再试。');
        } finally {
            setLoading(false);
        }
    }

    function parseFullScanData(jsonText) {
        fullscanState.areas = [];
        fullscanState.chosen = {};
        fullscanState.viewTier = {};
        let arr = [];
        try {
            const cleaned = String(jsonText || '').replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
            if (cleaned && cleaned !== '[]') {
                arr = JSON.parse(cleaned);
                if (!Array.isArray(arr)) arr = [];
            }
        } catch (e) {
            console.warn('[fullscan] JSON 解析失败', e);
            arr = [];
        }

        for (const a of arr) {
            if (!a || !Array.isArray(a.plans)) continue;
            const plans = a.plans.map(p => {
                const kind = (String(p.kind || '').toLowerCase() === 'buff') ? 'buff' : 'hard';
                const tier = ['low', 'mid', 'high'].includes(p.tier) ? p.tier : 'low';
                const cost = FULLSCAN_TIER_COST[tier];
                const base = { tier, cost, kind, summary: String(p.summary || '').slice(0, 60) };
                if (kind === 'hard') {
                    base.newDesc = String(p.new_desc || '').trim();
                } else {
                    base.buffName = String(p.buff_name || '修缮').slice(0, 8);
                    base.buffColor = fsSanitizeHex(p.buff_color) || fsPickFallbackColor(base.summary);
                    base.buffDuration = fsClampInt(p.buff_duration, 10, 60, 30);
                }
                return base;
            }).filter(p => p.kind === 'hard' ? !!p.newDesc : !!p.buffName);
            if (!plans.length) continue;
            fullscanState.areas.push({
                areaId: String(a.area_id || '').replace(/[#\[\]]/g, '').trim(),
                areaName: String(a.area_name || '').trim() || '未命名区域',
                plans,
            });
        }
        renderFullScanAreas();
    }

    function renderFullScanAreas() {
        const box = document.getElementById('fullscan-result');
        if (!box) return;
        if (!fullscanState.areas.length) {
            box.innerHTML = '<div style="padding:16px;text-align:center;opacity:0.7">没有扫描到可修缮的方案，可稍后再试。</div>';
            return;
        }
        let html = '';
        fullscanState.areas.forEach((area, ai) => {
            const emoji = fsGetRoomEmoji(area);
            const name = escapeFsHtml(area.areaName);
            const total = area.plans.length;
            let ti = Number(fullscanState.viewTier[ai]);
            if (!(ti >= 0 && ti < total)) ti = 0;
            const plan = area.plans[ti];
            const added = (fullscanState.chosen[ai] === ti);
            const planBody = plan.kind === 'buff'
                ? ('<span class="fullscan-buff-preview" style="background:' + plan.buffColor + '">' + escapeFsHtml(plan.buffName) + '</span>')
                : ('<div class="fullscan-c-desc">' + escapeFsHtml(plan.newDesc || '') + '</div>');
            const tierTag = (FULLSCAN_TIER_LABEL[plan.tier] || '') + (plan.kind === 'buff' ? ' ✨buff' : '');
            html += '<div class="fullscan-c' + (added ? ' added' : '') + '" data-ai="' + ai + '">'
                + '<div class="fullscan-c-head">'
                +   '<div class="fullscan-c-name">' + emoji + ' ' + name + '</div>'
                +   '<button class="fullscan-c-add' + (added ? ' added' : '') + '" onclick="fsTogglePlan(' + ai + ')">' + (added ? '✓ 已加入' : '+ 加入预算') + '</button>'
                + '</div>'
                + '<div class="fullscan-c-tier">' + tierTag + '</div>'
                + '<div class="fullscan-c-summary">' + escapeFsHtml(plan.summary) + '</div>'
                + planBody
                + '<div class="fullscan-c-pricerow">'
                +   '<button class="fullscan-c-arrow" onclick="fsSwitchTier(' + ai + ',-1)" ' + (total <= 1 ? 'disabled' : '') + '>‹</button>'
                +   '<span class="fullscan-c-price">' + plan.cost + ' 铜币</span>'
                +   '<button class="fullscan-c-arrow" onclick="fsSwitchTier(' + ai + ',1)" ' + (total <= 1 ? 'disabled' : '') + '>›</button>'
                + '</div>'
                + '</div>';
        });
        html += '<div class="fullscan-foot">';
        html += '<div class="fullscan-foot-info">合计花费 <span id="fullscan-cost-disp" style="color:#c08a3e;font-weight:700">0</span> 铜币 · 已选 <span id="fullscan-count-disp">0</span> 项 ';
        html += '<label class="fullscan-silent-toggle" title="勾选后仅在本地更新数据，不发送消息也不触发 AI 续写正文"><input type="checkbox" id="fullscan-silent-mode"> 🔇 不生成正文</label></div>';
        html += '<button class="fullscan-confirm-btn" id="fullscan-confirm-btn" onclick="fullScanSubmit()" disabled>确认修缮</button>';
        html += '</div>';
        box.innerHTML = html;
        updateFullScanFoot();
    }

    function escapeFsHtml(s) {
        return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }

    function fsSwitchTier(ai, dir) {
        const area = fullscanState.areas[ai];
        if (!area) return;
        const total = area.plans.length;
        let ti = Number(fullscanState.viewTier[ai]);
        if (!(ti >= 0 && ti < total)) ti = 0;
        ti = (ti + dir + total) % total;
        fullscanState.viewTier[ai] = ti;
        renderFullScanAreas();
    }

    function fsTogglePlan(ai) {
        const area = fullscanState.areas[ai];
        if (!area) return;
        let ti = Number(fullscanState.viewTier[ai]);
        if (!(ti >= 0 && ti < area.plans.length)) ti = 0;
        if (fullscanState.chosen[ai] === ti) {
            delete fullscanState.chosen[ai];
        } else {
            fullscanState.chosen[ai] = ti;
        }
        renderFullScanAreas();
    }


function getFullScanChosen() {
        const out = [];
        for (const ai in fullscanState.chosen) {
            const area = fullscanState.areas[ai];
            if (!area) continue;
            const plan = area.plans[fullscanState.chosen[ai]];
            if (plan) out.push({ area, plan });
        }
        return out;
    }

    function updateFullScanFoot() {
        const chosen = getFullScanChosen();
        const total = chosen.reduce((s, x) => s + x.plan.cost, 0);
        const costEl = document.getElementById('fullscan-cost-disp');
        const cntEl = document.getElementById('fullscan-count-disp');
        const btn = document.getElementById('fullscan-confirm-btn');
        if (costEl) costEl.textContent = total;
        if (cntEl) cntEl.textContent = chosen.length;
        if (btn) btn.disabled = chosen.length === 0;
    }

    function collapseFullScan() {
        const page = document.getElementById('page-repair');
        if (page) page.classList.remove('fullscan-expanded');
        const collapseBtn = document.getElementById('fullscan-collapse');
        if (collapseBtn) collapseBtn.style.display = 'none';
        const box = document.getElementById('fullscan-result');
        if (box) box.innerHTML = '';
        fullscanState.areas = [];
        fullscanState.chosen = {};
        fullscanState.viewTier = {};
    }

    async function fullScanSubmit() {
        const chosen = getFullScanChosen();
        if (!chosen.length) return;
        const silent = !!(document.getElementById('fullscan-silent-mode') && document.getElementById('fullscan-silent-mode').checked);
        const total = chosen.reduce((s, x) => s + x.plan.cost, 0);
        if (total > tavernStats.balance) {
            uiAlert('余额不足！\n需支付: ' + total + '\n当前余额: ' + tavernStats.balance);
            return;
        }

        const findFn = window.parent && window.parent.findRoomById;
        const updateFn = window.parent && window.parent.updateRoomData;
        const addEvoFn = window.parent && window.parent.addEvolution;

        const resolved = [];
        const detailParts = [];
        for (const { area, plan } of chosen) {
            let hit = null;
            try {
                if (typeof findFn === 'function' && area.areaId) hit = findFn(area.areaId);
                if (!hit) hit = fsFindRoomByName(area.areaName);
            } catch (e) { console.warn('[fullscan] 房间匹配失败', e); }
            resolved.push({ area, plan, hit });
            detailParts.push(area.areaName + '(花费' + plan.cost + '铜币进行' + plan.summary + ')');
        }

        // 拼系统事件文本（含余额扣减，infraGain = 总花费/100，每 100 铜 +1 基建，多选叠加、不封顶）
        const infraGain = Math.max(1, Math.round(total / 100));
        const detail = detailParts.join('、');
        const msg = '> [系统事件] {{user}}花费了' + total + '铜币，使用系统的全面修缮功能：' + detail + '。(基建度增加' + infraGain + ')';

        // === 先把消息/正文发出去，再改 desc/buff 变量 ===
        // 这样 AI 看到的消息里不含"已经改好的描述"，不会困惑"为什么还要再装修一次"
        if (silent) {
            if (typeof getChatMessages !== 'function' || typeof setChatMessages !== 'function') {
                uiAlert('静默修缮失败：当前环境没有 setChatMessages API，请取消勾选「不生成正文」后重试。');
                return;
            }
            try {
                const all = getChatMessages('0-{{lastMessageId}}');
                if (!all || all.length === 0) {
                    uiAlert('静默修缮失败：聊天里还没有任何楼层，无法追加。请先生成至少一条消息再试。');
                    return;
                }
                const last = all[all.length - 1];
                const STATUS_RE = /<tavern_status>[\s\S]*?<\/tavern_status>/;
                let statusOldBlock = null, statusFoundIdx = -1, statusFoundMsgId = -1;
                for (let i = all.length - 1; i >= 0; i--) {
                    const m = String(all[i].message || '').match(STATUS_RE);
                    if (m) { statusOldBlock = m[0]; statusFoundIdx = i; statusFoundMsgId = all[i].message_id; break; }
                }
                let statusNewBlock = null;
                if (statusOldBlock) {
                    let v = statusOldBlock;
                    const _infraRes = applyInfraGainToStatus(v, infraGain); v = _infraRes.text;
                    v = v.replace(/(当前余额\s*[:：|]\s*)(\d+(?:\.\d+)?)/, (mm, pre, num) => { const n = Math.max(0, (parseFloat(num) || 0) - total); return pre + (Number.isInteger(n) ? n : n.toFixed(1)); });
                    statusNewBlock = v;
                }
                const wrapped = '<player_silent>\n' + msg + '\n</player_silent>';
                const updates = [];
                const refreshIds = [last.message_id];
                // 先把 <player_silent>（只含系统事件/指令，绝不含 <tavern_status> 副本）追加到最后一楼尾部。
                // 关键：早期版本把改好的 status 也塞进了 player_silent，而 player_silent 块会永久留在楼层真实存储里，
                // 导致同一楼连续静默操作时楼层里出现多个 <tavern_status>，第二次匹配/替换就错位、改不到真 status。
                // 这里改成：status 永远只原地改“正文里那唯一一个真 status”，不再生成 status 副本。
                let newLastText = String(last.message || '').replace(/\s+$/, '') + '\n\n' + wrapped;
                if (statusNewBlock) {
                    if (statusFoundIdx === all.length - 1) {
                        // status 就在最后一楼：在已追加 player_silent 的文本上原地替换那个真 status
                        newLastText = newLastText.replace(STATUS_RE, statusNewBlock);
                    } else {
                        // status 在更早的楼：单独更新那一楼的真 status
                        const oldText = String(all[statusFoundIdx].message || '');
                        updates.push({ message_id: statusFoundMsgId, message: oldText.replace(STATUS_RE, statusNewBlock) });
                        refreshIds.push(statusFoundMsgId);
                    }
                }
                updates.push({ message_id: last.message_id, message: newLastText });
                await setChatMessages(updates, { refresh: 'none' });
                try {
                    const Mvu = window.parent && window.parent.Mvu;
                    if (Mvu && typeof Mvu.getMvuData === 'function' && typeof Mvu.replaceMvuData === 'function') {
                        const md = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                        if (md && md.stat_data) {
                            const bal = Number(md.stat_data['酒馆当前余额']) || 0;
                            md.stat_data['酒馆当前余额'] = Math.max(0, bal - total);
                            const infra = Number(md.stat_data['酒馆基建']) || 0;
                            const _infraTotal = Math.max(0, infra + infraGain);
                            md.stat_data['酒馆基建'] = _infraTotal % 100;
                            const _lvCur = Number(md.stat_data['酒馆等级']) || 1;
                            md.stat_data['酒馆等级'] = _lvCur + Math.floor(_infraTotal / 100);
                            await Mvu.replaceMvuData(md, { type: 'message', message_id: 'latest' });
                        }
                    }
                } catch (e2) { console.warn('[fullscan] silent: MVU 同步失败', e2); }
                for (const mid of refreshIds) {
                    try {
                        if (typeof tavern_events !== 'undefined' && typeof eventEmit !== 'undefined') {
                            eventEmit(tavern_events.MESSAGE_UPDATED, mid);
                        }
                    } catch (e2) { console.warn('[fullscan] silent: eventEmit MESSAGE_UPDATED failed', e2); }
                }
            } catch (e) {
                console.error('[fullscan] silent append failed', e);
                uiAlert('静默修缮失败：' + (e && e.message ? e.message : e));
                return;
            }
        } else {
            // 触发正文模式：把"写 desc / 加 buff 变量"延迟到消息真正发送之后再落地，
            // 避免 AI 续写时看到已经修好的房间描述而纳闷"为什么还要修"。
            injectInput(msg, true, applyFullScanVars);
        }

        // === 落地函数：写 desc / 加 buff（silent 同步调用；触发正文模式作为 afterSend 回调）===
        function applyFullScanVars() {
            for (const { area, plan, hit } of resolved) {
                if (plan.kind === 'hard') {
                    if (hit && typeof updateFn === 'function') {
                        try { updateFn(hit.floorKey, hit.roomId, { desc: plan.newDesc }); }
                        catch (e) { console.warn('[fullscan] desc 写回失败', e); }
                    }
                } else {
                    if (hit && typeof addEvoFn === 'function') {
                        try {
                            addEvoFn(hit.room && hit.room.id ? hit.room.id : area.areaId, {
                                kind: 'buff',
                                itemName: plan.buffName,
                                color: plan.buffColor,
                                duration: plan.buffDuration,
                                baseEmoji: '✨',
                                baseState: plan.buffName,
                                endType: 'vanish',
                                stages: [],
                            });
                        } catch (e) { console.warn('[fullscan] addEvolution 失败', e); }
                    }
                }
            }
        }
        if (silent) applyFullScanVars();

        // 计数用于汇总提示（提交前即可由 resolved 推定，不依赖变量何时落地）
        let hardCount = 0, buffCount = 0, missCount = 0;
        for (const { plan, hit } of resolved) {
            if (plan.kind === 'hard') {
                if (hit && typeof updateFn === 'function') hardCount++; else missCount++;
            } else {
                if (hit && typeof addEvoFn === 'function') buffCount++; else missCount++;
            }
        }

        const summaryParts = [];
        if (hardCount) summaryParts.push('硬装修缮 ' + hardCount + ' 处');
        if (buffCount) summaryParts.push('新增氛围 buff ' + buffCount + ' 个');
        if (missCount) summaryParts.push(missCount + ' 处未匹配到房间（已跳过落地，仅记账）');
        uiAlert('✅ 全面修缮完成（' + (summaryParts.join('；') || '无变更') + '）');
        collapseFullScan();
    }

    async function comboSubmit() {
        const p = comboState.plans[comboState.chosenIdx];
        if (!p) return;
        const silent = !!(document.getElementById('combo-silent-mode') && document.getElementById('combo-silent-mode').checked);
        if (p.cost > tavernStats.balance) {
