            return;
        }
        // 预判：是否能写回 desc（用于消息文案与后续落地），不在此处真正写入
        const findFn = window.parent && window.parent.findRoomById;
        const updateFn = window.parent && window.parent.updateRoomData;
        const addFn = window.parent && window.parent.addEvolution;
        let hit = null;
        try { if (typeof findFn === 'function') hit = findFn(p.roomId); } catch (e) { console.warn('[combo] findRoomById fail', e); }
        const willUpdateDesc = !!(hit && typeof updateFn === 'function');
        const evoPlanned = (p.evolutions && p.evolutions.length) ? p.evolutions.length : 0;

