        const detail = p.cost > 0 ? `${p.roomName}(花费${p.cost}铜币进行${p.actionDesc})` : `${p.roomName}(进行${p.actionDesc})`;
        const itemDelBlock = '<Item>\n' + p.consumeIds.map(id => `CMD:DEL | ${id}`).join('\n') + '\n</Item>';
        const evoMsg = evoPlanned > 0 ? `\n（房间内新增 ${evoPlanned} 件演化物品，会随楼层推移逐步变化）` : '';
        const msg = `> [系统事件] {{user}}${p.cost > 0 ? `花费了${p.cost}铜币，` : ``}使用系统的基建修缮功能进行物品改造：${detail}。\n(基建度增加${p.infraGain})${evoMsg}\n\n${itemDelBlock}`;

        // 4) 投递（先把消息/正文发出去）
        if (silent) {
            if (typeof getChatMessages !== 'function' || typeof setChatMessages !== 'function') {
                uiAlert('静默改造失败：当前环境没有 setChatMessages API，请改用普通改造。');
                return;
            }
            try {
                const all = getChatMessages('0-{{lastMessageId}}');
                if (!all || all.length === 0) {
                    uiAlert('静默改造失败：聊天里还没有任何楼层，无法追加。请先生成至少一条消息再试。');
                    return;
                }
                const last = all[all.length - 1];
                const STATUS_RE = /<tavern_status>[\s\S]*?<\/tavern_status>/;
                let statusOldBlock = null, statusFoundIdx = -1, statusFoundMsgId = -1;
                for (let i = all.length - 1; i >= 0; i--) {
                    const m = String(all[i].message || '').match(STATUS_RE);
                    if (m) { statusOldBlock = m[0]; statusFoundIdx = i; statusFoundMsgId = all[i].message_id; break; }
                }
                let statusNewBlock = null;
                if (statusOldBlock) {
                    let v = statusOldBlock;
                    const _infraRes = applyInfraGainToStatus(v, p.infraGain); v = _infraRes.text;
                    v = v.replace(/(当前余额\s*[:：|]\s*)(\d+(?:\.\d+)?)/, (mm, pre, num) => { const n = Math.max(0, (parseFloat(num) || 0) - p.cost); return pre + (Number.isInteger(n) ? n : n.toFixed(1)); });
                    statusNewBlock = v;
                }
                const wrapped = '<player_silent>\n' + msg + '\n</player_silent>';
                const updates = [];
                const refreshIds = [last.message_id];
                // 先把 <player_silent>（只含系统事件/指令，绝不含 <tavern_status> 副本）追加到最后一楼尾部。
                // 关键：早期版本把改好的 status 也塞进了 player_silent，而 player_silent 块会永久留在楼层真实存储里，
                // 导致同一楼连续静默操作时楼层里出现多个 <tavern_status>，第二次匹配/替换就错位、改不到真 status。
                // 这里改成：status 永远只原地改“正文里那唯一一个真 status”，不再生成 status 副本。
                let newLastText = String(last.message || '').replace(/\s+$/, '') + '\n\n' + wrapped;
                if (statusNewBlock) {
                    if (statusFoundIdx === all.length - 1) {
                        // status 就在最后一楼：在已追加 player_silent 的文本上原地替换那个真 status
                        newLastText = newLastText.replace(STATUS_RE, statusNewBlock);
                    } else {
                        // status 在更早的楼：单独更新那一楼的真 status
                        const oldText = String(all[statusFoundIdx].message || '');
                        updates.push({ message_id: statusFoundMsgId, message: oldText.replace(STATUS_RE, statusNewBlock) });
                        refreshIds.push(statusFoundMsgId);
                    }
                }
                updates.push({ message_id: last.message_id, message: newLastText });
                await setChatMessages(updates, { refresh: 'none' });
                try {
                    const Mvu = window.parent && window.parent.Mvu;
                    if (Mvu && typeof Mvu.getMvuData === 'function' && typeof Mvu.replaceMvuData === 'function') {
                        const md = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                        if (md && md.stat_data) {
                            const bal = Number(md.stat_data['酒馆当前余额']) || 0;
                            md.stat_data['酒馆当前余额'] = Math.max(0, bal - p.cost);
                            const infra = Number(md.stat_data['酒馆基建']) || 0;
                            const _infraTotal = Math.max(0, infra + p.infraGain);
                            md.stat_data['酒馆基建'] = _infraTotal % 100;
                            const _lvCur = Number(md.stat_data['酒馆等级']) || 1;
                            md.stat_data['酒馆等级'] = _lvCur + Math.floor(_infraTotal / 100);
                            await Mvu.replaceMvuData(md, { type: 'message', message_id: 'latest' });
                        }
                    }
                } catch (e2) { console.warn('[combo] silent: MVU sync fail', e2); }
                for (const mid of refreshIds) {
                    try {
                        if (typeof tavern_events !== 'undefined' && typeof eventEmit !== 'undefined') {
                            eventEmit(tavern_events.MESSAGE_UPDATED, mid);
                        }
                    } catch (e2) { console.warn('[combo] silent: eventEmit fail', e2); }
                }
            } catch (e) {
                console.error('[combo] silent append failed', e);
                uiAlert('静默改造失败：' + (e && e.message ? e.message : e));
                return;
            }
        } else {
            // 触发正文模式：把"改 desc / 加演化变量"延迟到消息真正发送之后再落地，
            // 避免 AI 在续写时看到的房间描述已经是改造后的样子而纳闷"为什么还要修"。
            injectInput(msg, true, () => {
                try {
                    if (willUpdateDesc) updateFn(hit.floorKey, hit.roomId, { desc: p.newDesc });
                } catch (e) { console.warn('[combo] desc write fail (afterSend)', e); }
                try {
                    if (typeof addFn === 'function' && p.evolutions && p.evolutions.length) {
                        for (const evo of p.evolutions) {
                            addFn(p.roomId, {
                                itemName: evo.itemName,
                                baseEmoji: evo.base_emoji,
                                baseState: evo.base_state,
                                stages: evo.stages,
                                endType: evo.endType,
                                periodInterval: evo.periodInterval,
                                periodItem: evo.periodItem,
                                triggerKeyword: evo.triggerKeyword,
                            });
                        }
                    }
                } catch (e) { console.warn('[combo] addEvolution fail (afterSend)', e); }
            });
        }

        // UI 收尾立即执行（不依赖变量是否已落地）
        comboState.selectedItems.clear();
        comboState.plans = [];
        comboState.chosenIdx = -1;
        document.getElementById('combo-room-input').value = '';
        document.getElementById('combo-container').innerHTML = '';
        document.getElementById('combo-container').classList.remove('active');
        document.getElementById('combo-foot').classList.remove('active');
        renderComboInventoryBar();
        renderComboInputZone();

        if (silent) {
            // 静默模式不发消息给 AI，变量同步落地无副作用
            let descUpdated = false;
            try {
                if (willUpdateDesc) { updateFn(hit.floorKey, hit.roomId, { desc: p.newDesc }); descUpdated = true; }
            } catch (e) { console.warn('[combo] desc write fail (silent)', e); }
            let evoAddedCount = 0;
            try {
                if (typeof addFn === 'function' && p.evolutions && p.evolutions.length) {
                    for (const evo of p.evolutions) {
                        addFn(p.roomId, {
                            itemName: evo.itemName,
                            baseEmoji: evo.base_emoji,
                            baseState: evo.base_state,
                            stages: evo.stages,
                            endType: evo.endType,
                            periodInterval: evo.periodInterval,
                            periodItem: evo.periodItem,
                            triggerKeyword: evo.triggerKeyword,
                        });
                        evoAddedCount++;
                    }
                }
            } catch (e) { console.warn('[combo] addEvolution fail (silent)', e); }
            const parts = [];
            parts.push(descUpdated ? '描述已更新' : '描述未更新（未找到房间 ID）');
            if (p.consumeIds.length) parts.push(`将消耗 ${p.consumeIds.length} 件物品`);
            if (evoAddedCount > 0) parts.push(`新增 ${evoAddedCount} 件演化物品`);
            uiAlert(`✅ 静默改造完成（${parts.join('；')}）`);
        } else if (!willUpdateDesc) {
