        }
    }

    // ================= 幸运之池 =================
    const RATES = { R: 0.8, SR: 0.15, SSR: 0.05 };

    function doDraw(count) {
        const cost = count * 100;

        if (cost > tavernStats.balance) {
            uiAlert(`余额不足！\n需支付: ${cost}\n当前余额: ${tavernStats.balance}`);
            return;
        }

        let results = [];
        for (let i = 0; i < count; i++) {
            const rand = Math.random();
            let quality = 'R';
            if (rand > 1 - RATES.SSR) quality = 'SSR'; 
            else if (rand > 1 - RATES.SSR - RATES.SR) quality = 'SR';
            results.push(quality);
        }

        if (count === 10 && !results.some(r => r === 'SR' || r === 'SSR')) { results[9] = 'SR'; }

        renderBoxes(results);

        let injectText = "";
        if (count === 1) {
            const q = results[0];
            let lightDesc = "蓝光"; let itemLevel = "普通(R)";
            if (q === 'SR') { lightDesc = "紫光"; itemLevel = "稀有(SR)"; }
            if (q === 'SSR') { lightDesc = "耀眼的金光"; itemLevel = "传说(SSR)"; }
            injectText = `> [系统事件] {{user}}花费${cost}铜币在系统的幸运之池里进行单抽，随着${lightDesc}浮现，一个${itemLevel}道具被抽了出来。`;
        } else {
            const listStr = results.map(r => `[${r}]`).join('、');
            const ssrCount = results.filter(r=>r==='SSR').length;
            const srCount = results.filter(r=>r==='SR').length;
            const rCount = 10 - ssrCount - srCount;
            injectText = `> [系统事件] {{user}}花费${cost}铜币在系统的幸运之池里进行十连抽，随着一阵光芒闪烁，结果如下：\n${listStr}\n(统计：SSR×${ssrCount}，SR×${srCount}，R×${rCount})`;
        }
        injectInput(injectText, true);
    }

