    // ================= 员工合同补录 =================
    // 思路：让 AI 输出未录入员工的 <New_Employee_Profile>，用 <player_silent> 包裹追加到最新一楼尾部。
    //   - <player_silent> 内容由玩家侧 promptOnly 正则从 prompt 剥掉，对 AI 隐身，避免它复述/学样输出员工档案
    //   - <New_Employee_Profile> 是对楼层全文扫描的，裹在 <player_silent> 里照样会被物品栏扫到
    //   - 追加后用 eventEmit(MESSAGE_UPDATED) 触发物品栏 clearCheckpoint + 全量重扫，写入 inventory_staff_data
    async function startStaffResign() {
        if (!(await uiConfirm('系统将检查目前对话中是否有"实际加入酒馆但尚未补签"的员工，并自动补录到员工档案。继续？'))) return;
        setLoading(true, '正在核对员工档案...');
        try {
            // 1. 读取已录入员工
            const vars = (typeof TavernHelper !== 'undefined')
                ? (TavernHelper.getVariables({ type: 'chat' }) || {})
                : ((window.parent && window.parent.TavernHelper)
                    ? (window.parent.TavernHelper.getVariables({ type: 'chat' }) || {})
                    : {});
            const existingStaff = vars.inventory_staff_data || [];
            const existingNames = existingStaff.map(s => s['姓名'] || s['Name'] || s['name']).filter(Boolean);

            // 2. 让 AI 比对剧情找出未录入员工
            const prompt = `[System]暂停角色扮演，禁止输出正文与状态栏。请审视目前对话历史，找出"已经在剧情中正式加入酒馆工作（被{{user}}雇佣或主动入职）但尚未在员工档案中"的员工。
已录入员工：${existingNames.length ? existingNames.join('、') : '（暂无）'}

输出要求：
1. 判定为可补录员工必须同时满足：①对话历史里有明确的入职/受雇情节（被{{user}}雇佣或主动入职），仅在世界书/设定里出现、本场剧情没真正入职的不算；②不是客人/路人/未达成雇佣的人物。员工不限种族与形态——史莱姆、动物、傀儡、亡灵等非人同样可补录；若没有正式名字，就用其称谓/类别作为"姓名"（如"史莱姆"）。
2. 如全部已录入或无新员工，仅输出空字符串，不要解释。
3. 否则按以下严格格式输出（一名员工一个块，块外不得有任何内容、解释、状态栏）：
<New_Employee_Profile>
【姓名:xxx|性别:xxx|种族:xxx|外貌:xxx|性格:xxx|工作内容:xxx|报酬:xxx|备注:xxx】
</New_Employee_Profile>
4. 信息要长期、客观、几乎不会变化（禁短期易变信息如"今天穿了白裙"）。
5. 只允许"姓名"、"性别"、"种族"、"外貌"、"性格"、"工作内容"、"报酬"、"备注"这几个键，不要凭空增加其它键。`;

            const res = await smartGenerate({
                user_input: ' ',
                ordered_prompts: ['world_info', 'chat_history', { role: 'system', content: prompt }],
                quiet: true
            });

            // 3. 抽取所有 <New_Employee_Profile> 块
            const blocks = (res || '').match(/<New_Employee_Profile>[\s\S]*?<\/New_Employee_Profile>/gi) || [];

            // 4. 过滤已存在姓名（防 AI 复读已录入员工）
            const existingSet = new Set(existingNames.map(n => n.trim()));
            const freshBlocks = blocks.filter(b => {
                const inner = b.match(/【([\s\S]*?)】/);
                if (!inner) return false;
                const nameMatch = inner[1].match(/姓名\s*[：:]\s*([^|｜】]+)/);
                if (!nameMatch) return false;
                const name = nameMatch[1].trim();
                return name && !existingSet.has(name);
            });

            if (!freshBlocks.length) {
                setLoading(false);
                uiAlert('🔍 未发现需要补签的员工，所有在职员工都已录入。');
                return;
            }

            // 5. 用 <player_silent> 包裹追加到最新一楼尾部（玩家侧 promptOnly 正则负责对 AI 隐身）
            const combined = freshBlocks.join('\n');
            try {
                if (typeof getChatMessages !== 'function' || typeof setChatMessages !== 'function') {
                    throw new Error('当前环境缺少 getChatMessages / setChatMessages API');
                }
                const all = getChatMessages('0-{{lastMessageId}}');
                if (!all || all.length === 0) throw new Error('聊天里还没有任何楼层，无法追加');
                const last = all[all.length - 1];
                const wrapped = '<player_silent>\n' + combined + '\n</player_silent>';
                const newText = String(last.message || '').replace(/\s+$/, '') + '\n\n' + wrapped;
                await setChatMessages([{ message_id: last.message_id, message: newText }], { refresh: 'none' });

                // 6. 触发物品栏全量重扫（修改的是已扫过的楼层，必须走 MESSAGE_UPDATED → clearCheckpoint + 全量）
                try {
                    if (typeof tavern_events !== 'undefined' && typeof eventEmit !== 'undefined') {
                        await eventEmit(tavern_events.MESSAGE_UPDATED, last.message_id);
                    }
                } catch (e2) { console.warn('[员工补签] eventEmit 触发重扫失败，物品栏将在下次消息时刷新', e2); }
            } catch (e) {
                setLoading(false);
                console.error('[员工补签] 写入失败', e);
                uiAlert('❌ 补签写入失败：' + (e && e.message ? e.message : e));
                return;
            }

            setLoading(false);
            uiAlert(`✅ 已补签 ${freshBlocks.length} 名员工：\n${freshBlocks.map(b => {
                const m = b.match(/姓名\s*[：:]\s*([^|｜】]+)/);
                return m ? '• ' + m[1].trim() : '';
            }).filter(Boolean).join('\n')}\n\n请打开物品栏-员工查看。`);
        } catch (e) {
            console.error('[员工合同补录] 失败', e);
            setLoading(false);
            uiAlert('❌ 补签失败：' + (e && e.message ? e.message : e));
        }
    }

