    function tradeEscapeHtml(str) {
        if (str == null) return '';
        const d = document.createElement('div');
        d.textContent = String(str);
        return d.innerHTML;
    }

    function tryOpenTrade() {
        if (!isTradeUnlocked()) {
            document.getElementById('trade-unlock-mask').style.display = 'flex';
            return;
        }
        openTradeBoard();
    }

    function closeTradeUnlock() {
        document.getElementById('trade-unlock-mask').style.display = 'none';
    }

    async function confirmUnlockTrade() {
        if (tavernStats.balance < TRADE_UNLOCK_COST) {
            uiAlert(`余额不足！
需要: ${TRADE_UNLOCK_COST} 铜币
当前: ${tavernStats.balance}`);
            return;
        }
        // 与刷新委托一致：同时改最近一层状态栏余额 + MVU 变量
        await deductTradeCost(TRADE_UNLOCK_COST);

        await _setChatVar('物易物_unlocked', true);
        closeTradeUnlock();
        await getTavernStats();
        updateButlerUI();
        uiAlert('✅ 物易物委托栏已解锁！本次聊天内可永久使用。');
        openTradeBoard();
    }

    function openTradeBoard() {
        openApp('trade');
        const balEl = document.querySelector('#page-trade .trade-balance-disp');
        if (balEl) balEl.textContent = tavernStats.balance;
        // 进入时不主动生成委托——必须点「刷新委托」付费才出。tradeState.cards 保留上一次未结算的（如果有）
        if (!tradeState.cards || tradeState.cards.length === 0) {
            renderTradeCards([]);
        } else {
            renderTradeCards(tradeState.cards);
        }
        renderTradeInvBar();
        updateSettleBtn();
    }

    function renderTradeCards(cards) {
        tradeState.cards = cards.map(c => ({
            source: c.source || '',
            content: c.content || '',
            slots: (Array.isArray(c.slots) && c.slots.length === 3) ? c.slots.slice() : [null, null, null],
        }));
        // 根据当前 slots 重建 placedItems（防止状态漂移）
        tradeState.placedItems = new Set();
        for (const c of tradeState.cards) {
            for (const s of c.slots) { if (s && s.id) tradeState.placedItems.add(s.id); }
        }
        const con = document.getElementById('trade-cards-container');
        if (!con) return;
        if (!tradeState.cards.length) {
            con.innerHTML = `<div class='trade-empty-tip'>还没有委托。<br>点击上方「刷新委托」获取新一批。</div>`;
            return;
        }
        con.innerHTML = tradeState.cards.map((c, i) =>
            `<div class='trade-card' data-card-idx='${i}'>`
            + `<div class='trade-card-source'>—— ${tradeEscapeHtml(c.source)}</div>`
            + `<div class='trade-card-text'>${tradeEscapeHtml(c.content)}</div>`
            + `<div class='trade-card-slots'>`
            + [0,1,2].map(si => {
                const slot = c.slots[si];
                if (slot && slot.id) {
                    const sn = tradeEscapeHtml(slot.name || '');
                    const sd = tradeEscapeHtml(slot.desc || '');
                    const sicon = tradeEscapeHtml(slot.icon || '📦');
                    return `<div class='trade-slot filled' data-card-idx='${i}' data-slot-idx='${si}' data-item-id='${tradeEscapeHtml(slot.id)}' data-item-name='${sn}' data-item-desc='${sd}'>`
                        + `<span class='chip-icon'>${sicon}</span>`
                        + `<span class='chip-name' data-text='${sn}'>${sn}</span>`
                        + `</div>`;
                }
                return `<div class='trade-slot' data-card-idx='${i}' data-slot-idx='${si}'><span class='slot-empty-hint'>+</span></div>`;
            }).join('')
            + `</div></div>`
        ).join('');
        bindTradeDragEvents();
    }

    function renderTradeInvBar() {
        const bar = document.getElementById('trade-inv-bar');
        if (!bar) return;
        const isStorage = tradeState.invSource === 'storage';
        const getter = isStorage
            ? ((typeof getButlerStorage === 'function') ? getButlerStorage : null)
            : ((typeof getButlerInventory === 'function') ? getButlerInventory : null);
        const inv = getter ? getter() : [];
        const toggleLabel = isStorage ? '📦 杂物间 ›' : '🎒 背包 ›';
        const toggleHtml = `<div class='trade-inv-toggle' data-trade-src-toggle='1' title='点击切换 背包 / 杂物间'>${toggleLabel}</div>`;
        if (!inv || !inv.length) {
            const emptyText = isStorage ? '杂物间是空的' : '背包是空的';
            bar.innerHTML = toggleHtml + `<div style='flex:0 0 100%; padding: 12px; color: #888; font-size: 12px;'>${emptyText}</div>`;
            bindTradeSrcToggle();
            return;
        }
        bar.innerHTML = toggleHtml + inv.map(it => {
            const cls = 'trade-inv-chip' + (tradeState.placedItems.has(it.id) ? ' is-placed' : '');
            const safeId = tradeEscapeHtml(it.id);
            const safeName = tradeEscapeHtml(it.name || '');
            const safeDesc = tradeEscapeHtml(it.desc || '');
            const icon = tradeEscapeHtml(it.icon || '📦');
            return `<div class='${cls}' data-item-id='${safeId}' data-item-name='${safeName}' data-item-desc='${safeDesc}'>`
                + `<span class='chip-icon'>${icon}</span>`
                + `<span class='chip-name' data-text='${safeName}'>${safeName}</span>`
                + `</div>`;
        }).join('');
        bindTradeSrcToggle();
        bindTradeDragEvents();
    }

    function bindTradeSrcToggle() {
        const bar = document.getElementById('trade-inv-bar');
        if (!bar) return;
        const tgl = bar.querySelector('[data-trade-src-toggle]');
        if (!tgl || tgl._tradeSrcBound) return;
        tgl._tradeSrcBound = true;
        tgl.addEventListener('click', function (e) {
            e.preventDefault(); e.stopPropagation();
            tradeState.invSource = (tradeState.invSource === 'storage') ? 'bag' : 'storage';
            renderTradeInvBar();
        });
    }

    function updateSettleBtn() {
        const btn = document.getElementById('trade-settle-btn');
        if (!btn) return;
        const hasAny = tradeState.cards.some(c => c.slots && c.slots.some(s => s && s.id));
        btn.disabled = !hasAny;
    }

    // ===== 拖拽：长按启动 + 鼠标/触屏统一（参考料理台） =====
    const tradeDrag = {
        timer: null, isDragging: false, isTouch: false,
        startX: 0, startY: 0, helper: null,
        source: null, cachedSlotRects: [], cachedBarRect: null,
    };

    function bindTradeDragEvents() {
        const wire = (el) => {
            if (el._tradeBound) return;
            el._tradeBound = true;
            el.addEventListener('mousedown', tradeOnInputStart);
            el.addEventListener('touchstart', tradeOnInputStart, { passive: false });
            el.addEventListener('mouseenter', () => {
                if (tradeDrag.isDragging) return;
                tradeShowTooltip(el, el.dataset.itemName || '', el.dataset.itemDesc || '');
            });
            el.addEventListener('mouseleave', () => {
                if (tradeDrag.isDragging) return;
                tradeHideTooltip();
            });
        };
        document.querySelectorAll('#trade-inv-bar .trade-inv-chip:not(.is-placed)').forEach(wire);
        document.querySelectorAll('#trade-cards-container .trade-slot.filled').forEach(wire);
    }

    // ===== Tooltip（hover 显示 + 拖拽时跟随鼠标） =====
    let tradeTooltipEl = null;
    function tradeEnsureTooltip() {
        if (!tradeTooltipEl) {
            tradeTooltipEl = document.createElement('div');
            tradeTooltipEl.className = 'trade-tooltip';
            document.body.appendChild(tradeTooltipEl);
        }
        return tradeTooltipEl;
    }
    function tradeShowTooltip(target, name, desc) {
        if (!desc) return;
        const tt = tradeEnsureTooltip();
        tt.textContent = desc;
        tt.style.display = 'block';
        const r = target.getBoundingClientRect();
        tt.style.left = (r.left + r.width / 2) + 'px';
        tt.style.top = (r.top - 8) + 'px';
        tt.style.transform = 'translate(-50%, -100%)';
    }
    function tradeMoveTooltip(x, y) {
        if (!tradeTooltipEl) return;
        tradeTooltipEl.style.left = x + 'px';
        tradeTooltipEl.style.top = (y - 12) + 'px';
        tradeTooltipEl.style.transform = 'translate(-50%, -100%)';
    }
    function tradeHideTooltip() {
        if (tradeTooltipEl) tradeTooltipEl.style.display = 'none';
    }

    function tradeOnInputStart(e) {
        if (tradeDrag.isDragging || (e.button && e.button !== 0)) return;
        const evt = e.touches ? e.touches[0] : e;
        const fromEl = e.currentTarget;
        let source = null;
        if (fromEl.classList.contains('trade-inv-chip')) {
            const id = fromEl.dataset.itemId;
            const bagInv = (typeof getButlerInventory === 'function') ? getButlerInventory() : [];
            const storageInv = (typeof getButlerStorage === 'function') ? getButlerStorage() : [];
            const item = bagInv.find(i => String(i.id) === String(id)) || storageInv.find(i => String(i.id) === String(id));
            if (!item) return;
            source = { kind: 'bar', item: { id: item.id, name: item.name || '', icon: item.icon || '📦', desc: item.desc || '' }, fromEl };
        } else if (fromEl.classList.contains('trade-slot') && fromEl.classList.contains('filled')) {
            const cardIdx = Number(fromEl.dataset.cardIdx);
            const slotIdx = Number(fromEl.dataset.slotIdx);
            const item = tradeState.cards[cardIdx] && tradeState.cards[cardIdx].slots[slotIdx];
            if (!item) return;
            source = { kind: 'slot', cardIdx, slotIdx, item, fromEl };
        } else { return; }
        tradeDrag.source = source;
        tradeDrag.startX = evt.clientX;
        tradeDrag.startY = evt.clientY;
        tradeDrag.isTouch = !!e.touches;
        fromEl.classList.add('is-pressed');
        const delay = tradeDrag.isTouch ? 120 : 20;
        tradeDrag.timer = setTimeout(() => tradeStartDrag(evt), delay);
        document.addEventListener('mousemove', tradeOnInputMove);
        document.addEventListener('touchmove', tradeOnInputMove, { passive: false });
        document.addEventListener('mouseup', tradeOnInputEnd);
        document.addEventListener('touchend', tradeOnInputEnd);
    }

    function tradeStartDrag(evt) {
        if (!tradeDrag.source) return;
        tradeDrag.isDragging = true;
        const src = tradeDrag.source;
        src.fromEl.classList.remove('is-pressed');
        src.fromEl.style.opacity = '0.3';

        const helper = document.createElement('div');
        helper.className = 'trade-drag-helper';
        helper.textContent = src.item.icon || '📦';
        helper.style.left = (evt.clientX - 21) + 'px';
        helper.style.top = (evt.clientY - 21) + 'px';
        document.body.appendChild(helper);
        tradeDrag.helper = helper;

        tradeDrag.cachedSlotRects = Array.from(document.querySelectorAll('#trade-cards-container .trade-slot')).map(s => ({
            el: s, rect: s.getBoundingClientRect(),
            cardIdx: Number(s.dataset.cardIdx), slotIdx: Number(s.dataset.slotIdx),
        }));
        const bar = document.getElementById('trade-inv-bar');
        if (bar) tradeDrag.cachedBarRect = { el: bar, rect: bar.getBoundingClientRect() };
        const it = src.item;
        tradeShowTooltip(src.fromEl, it.name || '', it.desc || '');
        tradeMoveTooltip(evt.clientX, evt.clientY);
    }

    function tradeOnInputMove(e) {
        const evt = e.touches ? e.touches[0] : e;
        if (!tradeDrag.isDragging) {
            const dx = evt.clientX - tradeDrag.startX, dy = evt.clientY - tradeDrag.startY;
            const dist = Math.hypot(dx, dy);
            // 触屏：长按计时器没到点之前，只要手指动得超过阈值就判为「滚动找物品」，
            // 直接放弃这次拖拽意图（清掉计时器、解除按压、断开监听），让物品栏正常上下滚。
            // 纵向滑动阈值更小（更容易判成滚动），横向需要动得更多才放弃。
            if (tradeDrag.isTouch) {
                const absX = Math.abs(dx), absY = Math.abs(dy);
                if (absY > 10 || absX > 16) {
                    if (tradeDrag.timer) { clearTimeout(tradeDrag.timer); tradeDrag.timer = null; }
                    if (tradeDrag.source) tradeDrag.source.fromEl.classList.remove('is-pressed');
                    document.removeEventListener('mousemove', tradeOnInputMove);
                    document.removeEventListener('touchmove', tradeOnInputMove);
                    document.removeEventListener('mouseup', tradeOnInputEnd);
                    document.removeEventListener('touchend', tradeOnInputEnd);
                    tradeDrag.source = null;
                }
                return;
            }
            // 桌面端：保持原有小阈值，移动即取消长按等待
            if (dist > 3) {
                if (tradeDrag.timer) { clearTimeout(tradeDrag.timer); tradeDrag.timer = null; }
                if (tradeDrag.source) tradeDrag.source.fromEl.classList.remove('is-pressed');
            }
            return;
        }
        if (e.cancelable) e.preventDefault();
        if (tradeDrag.helper) {
            tradeDrag.helper.style.left = (evt.clientX - 21) + 'px';
            tradeDrag.helper.style.top = (evt.clientY - 21) + 'px';
        }
        tradeMoveTooltip(evt.clientX, evt.clientY);
        document.querySelectorAll('#page-trade .highlight').forEach(el => el.classList.remove('highlight'));
        let hit = false;
        for (const cs of tradeDrag.cachedSlotRects) {
            const r = cs.rect;
            if (evt.clientX >= r.left && evt.clientX <= r.right && evt.clientY >= r.top && evt.clientY <= r.bottom) {
                cs.el.classList.add('highlight'); hit = true; break;
            }
        }
        if (!hit && tradeDrag.cachedBarRect) {
            const r = tradeDrag.cachedBarRect.rect;
            if (evt.clientX >= r.left && evt.clientX <= r.right && evt.clientY >= r.top && evt.clientY <= r.bottom) {
                tradeDrag.cachedBarRect.el.classList.add('highlight');
            }
        }
    }

    function tradeOnInputEnd(e) {
        if (tradeDrag.timer) { clearTimeout(tradeDrag.timer); tradeDrag.timer = null; }
        document.removeEventListener('mousemove', tradeOnInputMove);
        document.removeEventListener('touchmove', tradeOnInputMove);
        document.removeEventListener('mouseup', tradeOnInputEnd);
        document.removeEventListener('touchend', tradeOnInputEnd);
        document.querySelectorAll('#page-trade .is-pressed').forEach(el => el.classList.remove('is-pressed'));

        if (!tradeDrag.isDragging) { tradeHideTooltip(); tradeDrag.source = null; return; }
        tradeDrag.isDragging = false;
        const src = tradeDrag.source;
        const evt = e.changedTouches ? e.changedTouches[0] : e;

        let target = null;
        for (const cs of tradeDrag.cachedSlotRects) {
            const r = cs.rect;
            if (evt.clientX >= r.left && evt.clientX <= r.right && evt.clientY >= r.top && evt.clientY <= r.bottom) {
                target = { kind: 'slot', cardIdx: cs.cardIdx, slotIdx: cs.slotIdx }; break;
            }
        }
        if (!target && tradeDrag.cachedBarRect) {
            const r = tradeDrag.cachedBarRect.rect;
            if (evt.clientX >= r.left && evt.clientX <= r.right && evt.clientY >= r.top && evt.clientY <= r.bottom) {
                target = { kind: 'bar' };
            }
        }

        if (target) {
            if (src.kind === 'slot') {
                const c = tradeState.cards[src.cardIdx];
                if (c) c.slots[src.slotIdx] = null;
            }
            tradeState.placedItems.delete(src.item.id);
            if (target.kind === 'slot') {
                const c = tradeState.cards[target.cardIdx];
                if (c) {
                    const old = c.slots[target.slotIdx];
                    if (old && old.id) tradeState.placedItems.delete(old.id);
                    c.slots[target.slotIdx] = src.item;
                    tradeState.placedItems.add(src.item.id);
                }
            }
        }

        tradeHideTooltip();
        if (tradeDrag.helper) { tradeDrag.helper.remove(); tradeDrag.helper = null; }
        document.querySelectorAll('#page-trade .highlight').forEach(el => el.classList.remove('highlight'));
        if (src && src.fromEl) src.fromEl.style.opacity = '';
        tradeDrag.cachedSlotRects = [];
        tradeDrag.cachedBarRect = null;
        tradeDrag.source = null;

        renderTradeCards(tradeState.cards);
        renderTradeInvBar();
        updateSettleBtn();
    }

    async function deductTradeCost(cost) {
        // 1. 找最近一条带 <tavern_status> 的楼层，把里面的「当前余额: N」原地改成 N - cost
        //    这样状态栏 EJS 下次重跑会读到新值，跟 MVU 保持同步——不需要新增 <player_silent>。
        try {
            if (typeof getChatMessages === 'function' && typeof setChatMessages === 'function') {
                const all = getChatMessages('0-{{lastMessageId}}');
                if (all && all.length > 0) {
                    const STATUS_RE = /<tavern_status>[\s\S]*?<\/tavern_status>/;
                    let foundIdx = -1, foundMsgId = -1;
                    for (let i = all.length - 1; i >= 0; i--) {
                        if (STATUS_RE.test(String(all[i].message || ''))) {
                            foundIdx = i; foundMsgId = all[i].message_id; break;
                        }
                    }
                    if (foundIdx >= 0) {
                        const oldText = String(all[foundIdx].message || '');
                        const newText = oldText.replace(STATUS_RE, (block) =>
                            block.replace(/(当前余额\s*[:：|]\s*)(\d+(?:\.\d+)?)/, (mm, pre, num) => {
                                const n = Math.max(0, (parseFloat(num) || 0) - cost);
                                return pre + (Number.isInteger(n) ? n : n.toFixed(1));
                            })
                        );
                        if (newText !== oldText) {
                            await setChatMessages([{ message_id: foundMsgId, message: newText }], { refresh: 'none' });
                            // 注意：这里不能 eventEmit(MESSAGE_UPDATED)。本系统 iframe 就挂在带 <tavern_status>
                            // 的最新楼层里，触发该楼层重渲染会把 iframe 整个重载，导致界面跳回首页、委托卡片丢失。
                            // 余额在下方第 2 步用 MVU 同步，状态栏文本会在下次自然渲染时刷新，这里静默改源文本即可。
                        }
                    }
                }
            }
        } catch (e) { console.warn('[委托栏] 修改楼层余额失败', e); }

        // 2. 直接更新 MVU 余额（立刻反映到 tavernStats 缓存）
        try {
            const Mvu = window.parent && window.parent.Mvu;
            if (Mvu && typeof Mvu.getMvuData === 'function' && typeof Mvu.replaceMvuData === 'function') {
                const md = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                if (md && md.stat_data) {
                    const cur = Number(md.stat_data['酒馆当前余额']) || 0;
                    md.stat_data['酒馆当前余额'] = cur - cost;
                    await Mvu.replaceMvuData(md, { type: 'message', message_id: 'latest' });
                }
            }
        } catch (e) { console.warn('[委托栏] MVU 扣费失败', e); }
    }

    async function refreshTradeCommissions() {
        if (tavernStats.balance < TRADE_REFRESH_COST) {
            uiAlert('余额不足！\n需要 ' + TRADE_REFRESH_COST + ' 铜币，当前 ' + tavernStats.balance);
            return;
        }
        if (tradeState.cards.length > 0) {
            if (!(await uiConfirm('当前已经有委托卡片，刷新会清空所有未结算的进度。\n确认刷新吗？'))) return;
        }

        const btn = document.getElementById('trade-refresh-btn');
        if (btn) { btn.disabled = true; btn.textContent = '🔄 委托收集中...'; }
        setLoading(true, '系统正在从远方收集委托...');

        try {
            const prompt = `[System] 你是「物易物委托栏」的委托收集系统。请生成 5-6 份委托。

## 风格基调
