]
</TRADE_RESULT>

- emoji 一个表达委托方此刻情绪的大号 emoji（满意 😊 / 困惑 🤨 / 愤怒 😡 / 震惊 😱 / 感动 🥲 / 搞笑 🤣 / 离谱 🤪 等，自由发挥）
- rewards 可以是空数组 []
- 不能漏任何提交的 card_idx`;

            const res = await smartGenerate({
                user_input: ' ',
                ordered_prompts: ['world_info_before', { role: 'system', content: prompt }],
                quiet: true,
            });

            const match = (res || '').match(/<TRADE_RESULT>([\s\S]*?)<\/TRADE_RESULT>/);
            if (!match) throw new Error('AI 没有返回 <TRADE_RESULT>...</TRADE_RESULT> 包裹的内容');
            const arrMatch = match[1].match(/\[[\s\S]*\]/);
            if (!arrMatch) throw new Error('找不到 JSON 数组');
            let results;
            try { results = JSON.parse(arrMatch[0]); }
            catch (pe) { throw new Error('返回的不是合法 JSON：' + pe.message); }
            if (!Array.isArray(results) || !results.length) throw new Error('返回的不是非空数组');

            pendingTradeResults = { results, submitted: submittedCards };
            renderTradeResultModal();
            document.getElementById('trade-result-mask').style.display = 'flex';
        } catch (e) {
            console.error('[委托栏] 结算失败:', e);
            uiAlert('结算失败：' + (e.message || e));
        } finally {
            setLoading(false);
        }
    }

    function renderTradeResultModal() {
        const body = document.getElementById('trade-result-body');
        if (!body || !pendingTradeResults) return;
        const submittedByIdx = new Map();
        for (const c of pendingTradeResults.submitted) submittedByIdx.set(c.card_idx, c);

        body.innerHTML = pendingTradeResults.results.map(r => {
            const sub = submittedByIdx.get(r.card_idx);
            const source = sub ? sub.source : '???';
            const rewards = Array.isArray(r.rewards) ? r.rewards : [];
            const rewardsHtml = rewards.length
                ? `<div class='trade-result-rewards'>` + rewards.map(rw => {
                    const icon = tradeEscapeHtml(rw.icon || '🎁');
                    const name = tradeEscapeHtml(rw.name || '');
                    const desc = tradeEscapeHtml(rw.desc || '');
                    return `<span class='trade-result-reward-chip' title='${desc}'>${icon} ${name}</span>`;
                }).join('') + `</div>`
                : `<div class='trade-result-reward-empty'>（委托方没给回礼）</div>`;
            return `<div class='trade-result-card'>`
                + `<div class='trade-result-emoji'>${tradeEscapeHtml(r.emoji || '🤔')}</div>`
                + `<div class='trade-result-info'>`
                +   `<div class='trade-result-source'>—— ${tradeEscapeHtml(source)}</div>`
                +   `<div class='trade-result-reply'>${tradeEscapeHtml(r.reply || '')}</div>`
                +   rewardsHtml
                + `</div>`
                + `</div>`;
        }).join('');
    }

    function closeTradeResult() {
        const mask = document.getElementById('trade-result-mask');
        if (mask) mask.style.display = 'none';
        pendingTradeResults = null;
    }

    async function confirmTradeResult() {
        if (!pendingTradeResults) { closeTradeResult(); return; }
        const { results, submitted } = pendingTradeResults;

        const dels = [];
        const adds = [];
        for (const sub of submitted) {
            for (const s of sub.slots) {
                if (s && s.id) dels.push('CMD:DEL | ' + s.id);
            }
            const r = results.find(x => Number(x.card_idx) === Number(sub.card_idx));
            if (r && Array.isArray(r.rewards)) {
                for (const rw of r.rewards) {
                    const icon = String(rw.icon || '🎁').trim();
                    const name = String(rw.name || '').trim();
                    const desc = String(rw.desc || '').trim();
                    const prizeDesc = desc.startsWith('系统内置小游戏的游戏奖品。') ? desc : `系统内置小游戏的游戏奖品。${desc}`;
                    if (!name) continue;
                    adds.push(`CMD:ADD | ${icon} | ${name} | ${prizeDesc}`);
                }
            }
        }

        if (dels.length === 0 && adds.length === 0) {
            closeTradeResult();
            tradeState.cards = [];
            tradeState.placedItems = new Set();
            renderTradeCards([]);
            renderTradeInvBar();
            updateSettleBtn();
            return;
        }

        const itemBlock = '<Item>\n' + [...dels, ...adds].join('\n') + '\n</Item>';
        const wrapped = '<player_silent>\n' + itemBlock + '\n</player_silent>';

        try {
            if (typeof getChatMessages !== 'function' || typeof setChatMessages !== 'function') {
                throw new Error('当前环境缺少 setChatMessages API');
            }
            const all = getChatMessages('0-{{lastMessageId}}');
            if (!all || all.length === 0) throw new Error('聊天里还没有任何楼层，无法追加');
            const last = all[all.length - 1];
            const newText = String(last.message || '').replace(/\s+$/, '') + '\n\n' + wrapped;
            await setChatMessages([{ message_id: last.message_id, message: newText }], { refresh: 'none' });
            try {
                if (typeof tavern_events !== 'undefined' && typeof eventEmit !== 'undefined') {
                    eventEmit(tavern_events.MESSAGE_UPDATED, last.message_id);
                }
            } catch (e) {}
        } catch (e) {
            console.error('[委托栏] 写入 Item 块失败:', e);
            uiAlert('交付失败：' + (e.message || e));
            return;
        }

        closeTradeResult();
        tradeState.cards = [];
        tradeState.placedItems = new Set();
        renderTradeCards([]);
        renderTradeInvBar();
        updateSettleBtn();

        uiAlert('✅ 结算完成\n交付 ' + dels.length + ' 件物品，获得 ' + adds.length + ' 件回礼');
    }

        // 把基建度增量应用到状态栏 <tavern_status> 文本：满 100 进位（等级 +1、基建度 -100，分母恒 100）。
    // 静默装修绕过了 AI，需要前端自己进位，否则基建度会累积成 123/100 这种。
    // 返回 { text, carry }：text 是改好的 block 文本，carry 是本次升的级数。
    function applyInfraGainToStatus(block, infraGain) {
        let carry = 0;
        let v = String(block);
        v = v.replace(/(基建度\s*[:：|]\s*)(\d+)(?:\s*\/\s*\d+)?/, (mm, pre, num) => {
            const total = Math.max(0, (parseInt(num, 10) || 0) + (Number(infraGain) || 0));
            carry = Math.floor(total / 100);
            return pre + (total % 100) + '/100';
        });
        if (carry > 0) {
            v = v.replace(/(等级\s*[:：|]\s*(?:LV|Lv|lv)?\s*)(\d+)/i, (mm, pre, num) => pre + ((parseInt(num, 10) || 1) + carry));
        }
        return { text: v, carry: carry };
    }

    // ================= 兑换礼包（导入 JSON，复刻商城静默购买入库）=================
    // 礼包 JSON 格式：{ "commands": [ "CMD:ADD | 🪙 | 金币 | 闪闪发光", ... ] }
    // 安全：默认只放行 CMD:ADD 开头的行（防礼包夹带 CMD:DEL 等）；要允许任意 CMD 把下面 filter 那行删掉即可。
    function redeemGiftPack() {
        const input = document.createElement("input");
        input.type = "file";
        input.accept = ".json,application/json";
        input.style.display = "none";
        input.addEventListener("change", () => {
            const file = input.files && input.files[0];
            input.remove();
            if (!file) return;
            if (file.size > 100 * 1024) { uiAlert("礼包文件过大（>100KB），已取消。"); return; }
            const reader = new FileReader();
            reader.onerror = () => uiAlert("文件读取失败。");
            reader.onload = () => applyGiftPack(String(reader.result || ""));
            reader.readAsText(file);
        });
        document.body.appendChild(input);
        input.click();
    }

    async function applyGiftPack(text) {
        // 1. 解析 JSON（绝不 eval）
        let data;
        try { data = JSON.parse(text); }
        catch (e) { uiAlert("礼包内容不是有效的 JSON。"); return; }

        // 2. 取出 commands 数组，只放行 CMD:ADD 开头的行
        const rawCmds = Array.isArray(data && data.commands) ? data.commands : [];
        const cmds = rawCmds
            .map(c => String(c == null ? "" : c).trim())
            .filter(c => /^CMD:ADD\b/i.test(c));   // ← 只允许 CMD:ADD；想放开就删这一行的 .filter(...)
        if (cmds.length === 0) { uiAlert("礼包里没有有效的 CMD:ADD 指令。"); return; }

        // 2.5 礼包名称 + emoji（缺省兜底）
        const giftName = (data && typeof data.name === "string" && data.name.trim()) ? data.name.trim() : "神秘礼包";
        const giftEmoji = (data && typeof data.emoji === "string" && data.emoji.trim()) ? data.emoji.trim() : "🎁";

        // 3. 包成 <player_silent><Item>...</Item></player_silent>（与商城静默购买一致）
        const itemBlock = "<Item>\n" + cmds.join("\n") + "\n</Item>";
        const wrapped = "<player_silent>\n" + itemBlock + "\n</player_silent>";

        if (typeof getChatMessages !== "function" || typeof setChatMessages !== "function") {
            uiAlert("兑换失败：当前环境没有 setChatMessages API。");
            return;
        }
        // 先确认有楼层可写，避免动画播完才发现没法入库
        const all = getChatMessages("0-{{lastMessageId}}");
        if (!all || all.length === 0) { uiAlert("兑换失败：聊天里还没有任何楼层，无法入库。请先生成至少一条消息再试。"); return; }
        // 入库目标：写「上一楼末尾」而非最新楼。最新楼挂着本系统 iframe，
        // eventEmit(MESSAGE_UPDATED) 会重渲染该楼导致 iframe 重载、跳回首页；
        // 改写上一楼则只重渲染上一楼，iframe 不受影响。只有 1 楼时兜底写最新楼。
        const target = all.length >= 2 ? all[all.length - 2] : all[all.length - 1];

        // 4. 先播仪式动画（emoji+名称 浮现渐隐，约1.6s），动画完整放完后再入库+eventEmit。
        //    顺序很重要：eventEmit(MESSAGE_UPDATED) 可能重载本 iframe（跳回首页），
        //    放在动画之后就不会打断动画，仪式感已经看完。
        // 解析每条 CMD:ADD | emoji | 物品名 | 描述(可选) → 清单数据
        const giftItems = cmds.map(function (line) {
            const parts = String(line).split("|").map(function (x) { return x.trim(); });
            // parts[0]="CMD:ADD", [1]=emoji, [2]=名称, [3]=描述
            return { emoji: parts[1] || "🎁", name: parts[2] || "未知物品", desc: parts[3] || "" };
        }).filter(function (it) { return it.name; });
        showGiftToast(giftEmoji, giftName, giftItems);
        setTimeout(async () => {
            try {
                const newText = String(target.message || "").replace(/\s+$/, "") + "\n\n" + wrapped;
                await setChatMessages([{ message_id: target.message_id, message: newText }], { refresh: "none" });
                try {
                    if (typeof tavern_events !== "undefined" && typeof eventEmit !== "undefined") {
                        eventEmit(tavern_events.MESSAGE_UPDATED, target.message_id);
                    }
                } catch (e2) { console.warn("[兑换礼包] eventEmit 失败", e2); }
            } catch (e) {
                console.error("[兑换礼包] 写入失败", e);
                uiAlert("兑换失败：" + (e && e.message ? e.message : e));
            }
        }, 1650);
    }

    // 礼包提示：阶段1 显示「emoji+礼包名」仪式视图 2 秒 → 阶段2 淡入物品清单（不自动消失，点「收下」才关）
    function showGiftToast(emoji, name, items) {
        const mask = document.getElementById("gift-toast-mask");
        const card = document.getElementById("gift-toast-card");
        const emo = document.getElementById("gift-toast-emoji");
        const nm = document.getElementById("gift-toast-name");
        if (!mask || !card || !emo || !nm) return;
        const list = Array.isArray(items) ? items : [];

        // —— 阶段1：仪式视图（沿用原浮现动画）——
        card.classList.remove("mode-list");          // 回到仪式视图
        emo.textContent = emoji || "🎁";
        nm.textContent = name || "神秘礼包";
        mask.classList.remove("show");
        void mask.offsetWidth;                        // 强制重排，让动画从头播
        mask.classList.add("show");

        // 关闭函数：隐藏遮罩并复位，便于下次兑换
        const closeGift = function () {
            mask.classList.remove("show");
            card.classList.remove("mode-list");
        };

        // 点遮罩空白处（卡片之外）也可关闭；点卡片本身不关。用 onclick 覆盖避免重复绑定
        mask.onclick = function (e) { if (e.target === mask) closeGift(); };

        // —— 2 秒后：阶段2 物品清单 ——
        setTimeout(function () {
            if (!mask.classList.contains("show")) return;   // 期间被关掉就不切了
            const scroll = document.getElementById("gift-list-scroll");
            const okBtn = document.getElementById("gift-list-confirm");
            if (!scroll || !okBtn) { setTimeout(closeGift, 200); return; }

            // 渲染物品卡片（逐个 stagger 上浮）
            scroll.innerHTML = "";
            list.forEach(function (it, i) {
                const row = document.createElement("div");
                row.className = "gift-item-card";
                row.style.animationDelay = (i * 0.06) + "s";
                const box = document.createElement("div");
                box.className = "gift-item-emoji";
                box.textContent = it.emoji || "🎁";
                const txt = document.createElement("div");
                txt.className = "gift-item-text";
                const nmEl = document.createElement("div");
                nmEl.className = "gift-item-name";
                nmEl.textContent = it.name || "未知物品";
                txt.appendChild(nmEl);
                if (it.desc) {
                    const dEl = document.createElement("div");
                    dEl.className = "gift-item-desc";
                    dEl.textContent = it.desc;
                    dEl.title = it.desc;                       // 被省略时悬停看全文
                    txt.appendChild(dEl);
                }
                row.appendChild(box);
                row.appendChild(txt);
                scroll.appendChild(row);
            });

            // 切到清单视图（淡入）
            card.classList.add("mode-list");

            // 「收下」：点了才关。用 onclick 覆盖避免重复绑定累积
            okBtn.onclick = closeGift;
        }, 2000);
    }

    // ================= 通用注入 =================
    function injectInput(txt, autoSend=false, afterSend=null) {
        try {
            const box = window.parent.document.getElementById('send_textarea');
            if(box) { 
                const prev = box.value;
                box.value = prev ? prev + "\n" + txt : txt; 
                box.dispatchEvent(new Event('input', {bubbles:true})); box.focus(); 
                if(autoSend) setTimeout(()=>{ const btn=window.parent.document.getElementById('send_but'); if(btn) btn.click(); if(typeof afterSend === 'function') setTimeout(afterSend, 1000); }, 200);
                else if(typeof afterSend === 'function') setTimeout(afterSend, 1000);
            }
        } catch(e) { console.error(e); }
    }

    // 注：generateRaw / createChatMessages 由 JS Slash Runner 注入到 iframe 全局。
    // 旧版直接 bare 调用就是用的全局。新版之前包装成 parentWin.xxx 是错的（主页面没这俩函数），
    // 会导致空间跳跃/酒馆扩建生成完后 AI 回复消失在控制台 warn 里。删掉包装后行为与旧版一致。
</script>
</body>
</html>
