import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

// === 1. 必须把这个清洗逻辑加回来 ===
// 它的作用：把 "Lv5"、"100/200"、"1000铜币" 这种脏文本强行变成数字
const cleanNumber = z.union([z.string(), z.number()])
  .transform((val) => {
    if (typeof val === 'number') return val;
    const str = String(val).trim();
    // 移除所有非数字、非负号的开头字符 (处理 "Lv5" -> "5")
    const cleanedStr = str.replace(/^[^\d-]+/, '');
    // 解析整数 (处理 "12/100" -> 12)
    const num = parseInt(cleanedStr, 10);
    return isNaN(num) ? 0 : num;
  })
  .pipe(z.number()); // 最终输出纯数字


// === 2. 定义变量结构 ===
export const Schema = z.object({
  // --- 数值类变量 (使用 cleanNumber) ---
  // 这里必须用 cleanNumber，否则正则抓到的字符串会让 z.number() 报错回滚到默认值
  酒馆等级: cleanNumber.prefault(1).describe('酒馆当前的等级'),
  酒馆基建: cleanNumber.prefault(0).describe('酒馆基建进度'),
  酒馆特殊名声: cleanNumber.prefault(0).describe('酒馆特殊服务名声'),
  酒馆当前余额: cleanNumber.prefault(0).describe('酒馆持有的铜币总数'),
  酒馆层数: cleanNumber.prefault(1).describe('酒馆地上层数，1或2'),
  酒馆地下层: cleanNumber.prefault(0).describe('地下层数，0或1'),
  // --- 文本类变量 (使用 z.string) ---
  // 时间和地点本身就是文字，所以直接用 z.string() 是没问题的
  当前时间: z.string().prefault("清晨").describe("当前的剧情时间"),
  当前地点: z.string().prefault("酒馆大厅").describe("当前所在的地点")
});

// === 3. 注册结构 ===
$(() => {
  registerMvuSchema(Schema);
})

/**
 * 强制开启提示词模板(EjsTemplate)的特定功能
 * 对应截图中的三个选项：
 * 1. 处理楼层消息 -> render_enabled
 * 2. 渲染楼层时注入 RENDER 世界书条目 -> render_loader_enabled
 * 3. 处理代码块 -> code_blocks_enabled
 */

(async function() {
    // 检查 EjsTemplate 对象是否存在 (确保插件已安装并加载)
    if (typeof EjsTemplate !== 'undefined') {

        // 获取当前设置作为参考（可选，方便调试）
        const currentFeatures = EjsTemplate.getFeatures();
        console.log("更新前设置:", currentFeatures);

        // 强制更新设置
        EjsTemplate.setFeatures({
            // 对应：处理楼层消息
            render_enabled: true,

            // 对应：渲染楼层时注入 RENDER 世界书条目
            render_loader_enabled: true,

            // 对应：处理代码块
            code_blocks_enabled: true
        });

        // 再次获取以确认更新
        const newFeatures = EjsTemplate.getFeatures();
        console.log("更新后设置:", newFeatures);

        // 已移除成功弹窗
    } else {
        // 已移除错误弹窗
        // 如果未检测到对象，现在将静默失败，不在界面报错
        console.error("错误：未检测到 EjsTemplate 对象");
    }
})();

