            outdoor_wasteland_2: { id: '23', emoji: '🌾', name: '荒地', purpose: '未开发', location: '酒馆外围东侧空地', desc: '东侧空地',   mapPos: { x: 72, y: 54 } },
            outdoor_wasteland_3: { id: '24', emoji: '🌾', name: '荒地', purpose: '未开发', location: '酒馆外围北侧空地，位于酒馆后方', desc: '北侧空地',   mapPos: { x: 53, y: 30 } },
        },
    };

    // ============ 读写工具 ============
    function getTavernHelper() {
        try { if (typeof TavernHelper !== 'undefined' && TavernHelper) return TavernHelper; } catch (e) {}
        try { if (window.parent && window.parent.TavernHelper) return window.parent.TavernHelper; } catch (e) {}
        try { if (window.top && window.top.TavernHelper) return window.top.TavernHelper; } catch (e) {}
        return null;
    }

    function getVars() {
        try {
            const helper = getTavernHelper();
            if (!helper || typeof helper.getVariables !== 'function') return {};
            return helper.getVariables({ type: 'chat' }) || {};
        } catch (e) {
            console.warn('[tavern-structure] getVars failed', e);
            return {};
        }
    }

    function saveStructure(data) {
        try {
            const helper = getTavernHelper();
            if (!helper || typeof helper.insertOrAssignVariables !== 'function') return false;
            helper.insertOrAssignVariables({ tavern_structure: data }, { type: 'chat' });
            return true;
        } catch (e) {
            console.warn('[tavern-structure] saveStructure failed', e);
            return false;
        }
    }

    function getStatData() {
        return getVars().stat_data || {};
    }

    function saveStatData(stat) {
        try {
            TavernHelper.insertOrAssignVariables({ stat_data: stat }, { type: 'chat' });
        } catch (e) {
            console.warn('[酒馆结构] saveStatData failed', e);
        }
    }

    function clone(o) {
        return JSON.parse(JSON.stringify(o));
    }

    // ============ 初始化与迁移 ============
    // 启动时：若结构不存在则按"一楼+户外"初始化；若存在则补齐 mapPos/outdoor 等新字段
    // 不会覆盖玩家已经改过的 name/desc/purpose
    // 把结构补全到「至少 floor_1 + outdoor 已解锁、其他楼层占位」的状态。
    // 任何时候调用都安全；getTavernStructure 也会先调一次，防止 chat var 被外部清空导致全锁。
    function ensureStructure() {
        let structure = getVars().tavern_structure;
        let modified = false;

        if (!structure || typeof structure !== 'object' || Array.isArray(structure)) {
            structure = {};
            modified = true;
        }

        // floor_1 是默认开局区，缺失/空对象/null 都补回来
        if (!structure.floor_1 || typeof structure.floor_1 !== 'object' || Object.keys(structure.floor_1).length === 0) {
            structure.floor_1 = clone(DEFAULT_STRUCTURE.floor_1);
            modified = true;
            console.log('[酒馆结构] 补回缺失的 floor_1');
        }
        // outdoor 同理
        if (!structure.outdoor || typeof structure.outdoor !== 'object' || Object.keys(structure.outdoor).length === 0) {
            structure.outdoor = clone(DEFAULT_STRUCTURE.outdoor);
            modified = true;
        }
        // floor_2 / basement_1 默认锁定（null 占位）
        if (!('floor_2' in structure)) { structure.floor_2 = null; modified = true; }
        if (!('basement_1' in structure)) { structure.basement_1 = null; modified = true; }

        // 给已存在的房间回填 mapPos / id / emoji（不覆盖玩家改过的字段）
        for (const floorKey of ['floor_1', 'floor_2', 'basement_1', 'outdoor']) {
            const floor = structure[floorKey];
            if (!floor || typeof floor !== 'object') continue;
            const defaultFloor = DEFAULT_STRUCTURE[floorKey];
            if (!defaultFloor) continue;
            for (const roomId in floor) {
                const room = floor[roomId];
                const defRoom = defaultFloor[roomId];
                if (!room || !defRoom) continue;
                if (!room.mapPos && defRoom.mapPos) { room.mapPos = { ...defRoom.mapPos }; modified = true; }
                if (!room.id && defRoom.id)         { room.id = defRoom.id;                modified = true; }
                if (!room.emoji && defRoom.emoji)   { room.emoji = defRoom.emoji;          modified = true; }
                if (!room.location && defRoom.location) { room.location = defRoom.location;    modified = true; }
            }
        }

        if (modified) saveStructure(structure);
        return structure;
    }

    function bootEnsureStructure(retry = 0) {
        const helper = getTavernHelper();
        const helperReady = helper
            && typeof helper.getVariables === 'function'
            && typeof helper.insertOrAssignVariables === 'function';

        if (!helperReady) {
            if (retry < 40) {
                setTimeout(() => bootEnsureStructure(retry + 1), 250);
            } else {
                console.warn('[tavern-structure] TavernHelper not ready; init skipped');
            }
            return;
        }

        ensureStructure();
        console.log('[tavern-structure] tavern_structure auto init checked');
    }

    bootEnsureStructure();

    // ============ 对外 API ============
    // 副脚本运行在自己的 iframe 里，必须把 API 挂到主页面（window.top），
    // 兄弟 iframe（同层系统/物品栏/底部状态栏）才能透过 window.parent 找到它。
    const HOST = (function () {
        try { if (window.top && window.top !== window) return window.top; } catch (e) {}
        try { if (window.parent && window.parent !== window) return window.parent; } catch (e) {}
        return window;
    })();

    HOST.getTavernStructure = function () {
        // 每次读取都先确保 floor_1 / outdoor 至少存在，防止外部清空 chat var 后 UI 全锁
        return ensureStructure();
    };

    HOST.getTavernFloor = function (floorKey) {
        const structure = HOST.getTavernStructure();
        return structure[floorKey] || null;
    };

    HOST.updateRoomData = function (floorKey, roomId, newData) {
        const structure = HOST.getTavernStructure();
        if (!structure[floorKey] || !structure[floorKey][roomId]) {
            console.warn('[酒馆结构] 找不到房间:', floorKey, '>', roomId);
            return false;
        }
        structure[floorKey][roomId] = { ...structure[floorKey][roomId], ...newData };
        saveStructure(structure);
        HOST.dispatchEvent(new CustomEvent('tavern-structure-changed', { detail: { floorKey, roomId } }));
        return true;
    };

    HOST.unlockTavernFloor = function (floorKey) {
        const structure = HOST.getTavernStructure();
        if (structure[floorKey] && typeof structure[floorKey] === 'object' && Object.keys(structure[floorKey]).length > 0) {
            console.log('[酒馆结构]', floorKey, '已存在，跳过');
            return false;
        }
        const defaultFloor = DEFAULT_STRUCTURE[floorKey];
        if (!defaultFloor) {
            console.warn('[酒馆结构] 没有', floorKey, '的默认模版');
            return false;
        }
        structure[floorKey] = clone(defaultFloor);
        saveStructure(structure);
        console.log('[酒馆结构]', floorKey, '解锁完成');
        return true;
    };

    // 升级唯一入口：原子地写 MVU 层数 + 解锁楼层 + 通知 UI
    // direction: 'up' 升二层 / 'down' 挖地下层
    HOST.expandTavern = function (direction) {
        const stat = getStatData();
        if (direction === 'up') {
            const cur = Number(stat['酒馆层数']) || 1;
            if (cur >= 2) {
                console.warn('[酒馆结构] 地上层已达上限（2 层）');
                return false;
            }
            stat['酒馆层数'] = cur + 1;
            saveStatData(stat);
            HOST.unlockTavernFloor('floor_2');
        } else if (direction === 'down') {
            const cur = Number(stat['酒馆地下层']) || 0;
            if (cur >= 1) {
                console.warn('[酒馆结构] 地下层已达上限（1 层）');
                return false;
            }
            stat['酒馆地下层'] = cur + 1;
            saveStatData(stat);
            HOST.unlockTavernFloor('basement_1');
        } else {
            console.warn('[酒馆结构] expandTavern 方向无效:', direction);
            return false;
        }
        HOST.dispatchEvent(new CustomEvent('tavern-expanded', { detail: { direction } }));
        return true;
    };

    // 通过房间 ID 反查所属楼层和 roomId（结构 key）
    HOST.findRoomById = function (id) {
        if (!id) return null;
        const structure = HOST.getTavernStructure();
        const targetId = String(id).trim();
        for (const floorKey of ['floor_1', 'floor_2', 'basement_1', 'outdoor']) {
            const floor = structure[floorKey];
            if (!floor || typeof floor !== 'object') continue;
            for (const roomId in floor) {
                const r = floor[roomId];
                if (r && String(r.id || '').trim() === targetId) {
                    return { floorKey, roomId, room: r };
                }
            }
        }
        return null;
    };

    // 提取所有装修记录条目（不限房间），每条带 {id, name, cost, actionDesc, date}
    // 兼容两种格式：
    //   1) 新版：[#01]入口大厅(花费100铜币进行xxx) 或 入口大厅[#01](花费100铜币进行xxx)
    //   2) 老版：入口大厅(花费100铜币进行xxx) —— 没有 id，靠 name 匹配
    function extractAllRenoEntries() {
        const renoList = getVars().inventory_renovation_list || [];
        const out = [];
        // 捕获组：m[1]=前置 id（可选），m[2]=区域名（可能含后置 [#XX]）, m[3]=cost, m[4]=action
        const re = /(?:\[#(\d{2,3})\]\s*)?([^、,，()（）]+?(?:[（(][^)）]*[)）])?)\s*[（(]花费(\d+)铜币进行([\s\S]*?)[)）](?:[、,，]|$)/g;
        for (const entry of renoList) {
            if (!entry || !entry.detail) continue;
            re.lastIndex = 0;
            let m;
            while ((m = re.exec(entry.detail)) !== null) {
                let id = m[1] || '';
                let name = (m[2] || '').trim();
                // 兼容 "入口大厅 [#01]" 这种 id 在名字后面的写法
                const tailIdMatch = name.match(/\[#(\d{2,3})\]\s*$/);
                if (!id && tailIdMatch) {
                    id = tailIdMatch[1];
                    name = name.replace(/\s*\[#\d{2,3}\]\s*$/, '').trim();
                }
                out.push({
                    id,
                    name,
                    cost: parseInt(m[3], 10) || 0,
                    actionDesc: (m[4] || '').trim(),
                    date: entry.date || '未知日期',
                });
            }
        }
        return out;
    }

    // 取某间房的装修记录：先按 id 精确匹配，再按 name 兜底（兼容老条目）
    HOST.getRoomRenovations = function (floorKey, roomId) {
        const structure = HOST.getTavernStructure();
        const room = structure[floorKey] && structure[floorKey][roomId];
        if (!room) return [];
        const targetId = String(room.id || '').trim();
        const targetName = String(room.name || '').trim();

        const result = [];
        for (const e of extractAllRenoEntries()) {
            const idHit = targetId && e.id && e.id === targetId;
            const nameHit = !e.id && targetName && e.name === targetName;
            if (idHit || nameHit) {
                result.push({ date: e.date, cost: e.cost, actionDesc: e.actionDesc });
            }
        }
        return result;
    };

    // ============ 演化物品 (Evolution) ============
    // 数据结构：chat var inventory_evolution_list = [
    //   { id, roomId, baseEmoji, baseState, itemName, stages:[{emoji,floor_offset,state},...], placed_at_floor, created_at }
    // ]
    // 楼层 = 已发生的 AI 回复数 (assistant role 消息数)
    function getCurrentFloor() {
        try {
            let fn = (typeof getChatMessages === 'function') ? getChatMessages
                   : (typeof TavernHelper !== 'undefined' && TavernHelper.getChatMessages) ? TavernHelper.getChatMessages
                   : null;
            if (!fn) return 0;
            const msgs = fn('0-{{lastMessageId}}', { role: 'assistant' });
            return Array.isArray(msgs) ? msgs.length : 0;
        } catch (e) { console.warn('[酒馆结构] getCurrentFloor failed', e); return 0; }
    }
    HOST.getCurrentFloor = getCurrentFloor;

    function getEvolutionList() { return getVars().inventory_evolution_list || []; }
    function saveEvolutionList(list) {
        try { TavernHelper.insertOrAssignVariables({ inventory_evolution_list: list }, { type: 'chat' }); }
        catch (e) { console.warn('[酒馆结构] saveEvolutionList failed', e); }
    }

    HOST.addEvolution = function (roomId, evo) {
        if (!roomId || !evo) return null;
        const list = getEvolutionList();
        const id = 'evo_' + Date.now() + '_' + Math.floor(Math.random() * 10000);
        const stages = Array.isArray(evo.stages) ? evo.stages
            .map(s => ({ emoji: String(s.emoji || ''), floor_offset: Number(s.floor_offset) || 0, state: String(s.state || '') }))
            .filter(s => s.floor_offset > 0)
            .sort((a, b) => a.floor_offset - b.floor_offset) : [];
        // === end_type / period / periodItem / triggerKeyword ===
        let endType = String(evo.endType || 'vanish').toLowerCase();
        if (!['vanish', 'periodic', 'trigger'].includes(endType)) endType = 'vanish';
        let periodInterval = Number(evo.periodInterval) || 0;
        if (endType === 'periodic' || endType === 'trigger') {
            if (periodInterval < 1) periodInterval = 10;
        } else {
            periodInterval = 0;
        }
        let periodItem = null;
        if (endType === 'periodic' && evo.periodItem && evo.periodItem.name) {
            periodItem = {
                icon: String(evo.periodItem.icon || '📦'),
                name: String(evo.periodItem.name),
                desc: String(evo.periodItem.desc || ''),
            };
        }
        let triggerKeyword = '';
        if (endType === 'trigger') triggerKeyword = String(evo.triggerKeyword || '').trim();
        // 缺关键字段时降级为 vanish，避免半残
        if (endType === 'periodic' && !periodItem) endType = 'vanish';
        if (endType === 'trigger' && !triggerKeyword) endType = 'vanish';
        // === buff 子类型：随楼层褪色、约 duration 层后自动消失（kind='buff'）===
        const kind = (String(evo.kind || '').toLowerCase() === 'buff') ? 'buff' : 'normal';
        const color = /^#[0-9a-fA-F]{6}$/.test(String(evo.color || '')) ? String(evo.color) : null;
        let duration = Number(evo.duration) || 0;
        if (kind === 'buff') {
            if (duration < 1) duration = 30; // buff 默认存活 30 层
            endType = 'vanish';             // buff 本质就是定时消失
        }
        const placed_at_floor = getCurrentFloor();
        const lastStageOffset = stages.length ? stages[stages.length - 1].floor_offset : 0;
        const lastActionAt = placed_at_floor + lastStageOffset; // 到达最终阶段那一层；周期/触发的"起算点"
        const entry = {
            id,
            roomId: String(roomId).trim(),
            itemName: String(evo.itemName || ''),
            baseEmoji: String(evo.baseEmoji || '📦'),
            baseState: String(evo.baseState || ''),
            stages,
            endType,
            periodInterval,
            periodItem,
            triggerKeyword,
            kind,
            color,
            duration,
            lastActionAt,
            placed_at_floor,
            created_at: Date.now(),
        };
        list.push(entry);
        saveEvolutionList(list);
        try { HOST.dispatchEvent(new CustomEvent('tavern-evolution-changed', { detail: { roomId, evoId: id } })); } catch(e){}
        return id;
    };    HOST.removeEvolution = function (evoId) {
        const list = getEvolutionList();
        const newList = list.filter(e => e.id !== evoId);
        if (newList.length === list.length) return false;
        saveEvolutionList(newList);
        try { HOST.dispatchEvent(new CustomEvent('tavern-evolution-changed', { detail: { evoId } })); } catch(e){}
        return true;
    };

    HOST.getRoomEvolutions = function (roomId) {
        if (!roomId) return [];
        const target = String(roomId).trim();
        const list = getEvolutionList();
        const cur = getCurrentFloor();
        return list
            .filter(e => String(e.roomId || '').trim() === target)
            .map(e => {
                const elapsed = cur - (e.placed_at_floor || 0);
                let stage = { emoji: e.baseEmoji, state: e.baseState };
                let next = null;
                for (const s of (e.stages || [])) {
                    if (elapsed >= s.floor_offset) stage = s;
                    else { next = s; break; }
                }
                // 周期/触发状态计算（仅最终阶段后有效）
                const endType = e.endType || 'vanish';
                const periodInterval = Number(e.periodInterval) || 0;
                const atFinalStage = (next === null);
                let actionReady = false;
                let floorsToAction = null;
                if (atFinalStage && (endType === 'periodic' || endType === 'trigger') && periodInterval > 0) {
                    const lastStageOffset = (e.stages && e.stages.length) ? e.stages[e.stages.length - 1].floor_offset : 0;
                    const baseFloor = (e.placed_at_floor || 0) + lastStageOffset;
                    const lastAt = (typeof e.lastActionAt === 'number') ? e.lastActionAt : baseFloor;
                    const sinceLast = cur - lastAt;
                    actionReady = sinceLast >= periodInterval;
                    floorsToAction = Math.max(0, periodInterval - sinceLast);
                }
                return {
                    id: e.id,
                    itemName: e.itemName,
                    placed_at_floor: e.placed_at_floor,
                    elapsed,
                    kind: e.kind || 'normal',
                    color: e.color || null,
                    duration: Number(e.duration) || 0,
                    currentStage: { emoji: stage.emoji, state: stage.state },
                    nextStage: next ? { emoji: next.emoji, state: next.state } : null,
                    floorsToNext: next ? Math.max(0, next.floor_offset - elapsed) : null,
                    endType,
                    periodInterval,
                    periodItem: e.periodItem || null,
                    triggerKeyword: e.triggerKeyword || '',
                    actionReady,
                    floorsToAction,
                };
            });
    };        // ============ periodic 收取 / trigger 触发 / vanish 自动移除 ============

    HOST.collectPeriodicEvolution = function (evoId) {
        if (!evoId) return null;
        const list = getEvolutionList();
        const entry = list.find(e => e.id === evoId);
        if (!entry) return null;
        if ((entry.endType || 'vanish') !== 'periodic') return null;
        if (!entry.periodItem || !entry.periodItem.name) return null;
        const cur = getCurrentFloor();
        const lastStageOffset = (entry.stages && entry.stages.length) ? entry.stages[entry.stages.length - 1].floor_offset : 0;
        const baseFloor = (entry.placed_at_floor || 0) + lastStageOffset;
        const lastAt = (typeof entry.lastActionAt === 'number') ? entry.lastActionAt : baseFloor;
        const periodInterval = Number(entry.periodInterval) || 0;
        if (periodInterval <= 0 || (cur - lastAt) < periodInterval) return null;
        entry.lastActionAt = lastAt + periodInterval; // 推进一个周期，保留积压
        saveEvolutionList(list);
        try { HOST.dispatchEvent(new CustomEvent('tavern-evolution-changed', { detail: { evoId } })); } catch(e){}
        return { icon: entry.periodItem.icon, name: entry.periodItem.name, desc: entry.periodItem.desc || '' };
    };

    HOST.markTriggerFired = function (evoId) {
        if (!evoId) return null;
        const list = getEvolutionList();
        const entry = list.find(e => e.id === evoId);
        if (!entry) return null;
        if ((entry.endType || 'vanish') !== 'trigger') return null;
        if (!entry.triggerKeyword) return null;
        const cur = getCurrentFloor();
        const lastStageOffset = (entry.stages && entry.stages.length) ? entry.stages[entry.stages.length - 1].floor_offset : 0;
        const baseFloor = (entry.placed_at_floor || 0) + lastStageOffset;
        const lastAt = (typeof entry.lastActionAt === 'number') ? entry.lastActionAt : baseFloor;
        const periodInterval = Number(entry.periodInterval) || 0;
        if (periodInterval <= 0 || (cur - lastAt) < periodInterval) return null;
        entry.lastActionAt = lastAt + periodInterval;
        saveEvolutionList(list);
        try { HOST.dispatchEvent(new CustomEvent('tavern-evolution-changed', { detail: { evoId } })); } catch(e){}
        return { keyword: entry.triggerKeyword };
    };

    // vanish 类型：到最后阶段后的下一楼自动从列表里移除
    function sweepVanishEvolutions() {
        try {
            const list = getEvolutionList();
            if (!list || !list.length) return;
            const cur = getCurrentFloor();
            const survivors = list.filter(e => {
                if ((e.endType || 'vanish') !== 'vanish') return true;
                const elapsed = cur - (e.placed_at_floor || 0);
                // buff：无中间阶段，按 duration 存活（活到 duration-1 层，第 duration 层消失）
                if ((e.kind || 'normal') === 'buff') {
                    const dur = Number(e.duration) || 30;
                    return elapsed < dur;
                }
                const lastStageOffset = (e.stages && e.stages.length) ? e.stages[e.stages.length - 1].floor_offset : 0;
                return elapsed <= lastStageOffset; // 超出最后阶段一楼即移除
            });
            if (survivors.length !== list.length) {
                saveEvolutionList(survivors);
                try { HOST.dispatchEvent(new CustomEvent('tavern-evolution-changed', { detail: { sweep: true } })); } catch(e){}
            }
        } catch (e) { console.warn('[酒馆结构] sweepVanishEvolutions failed', e); }
    }
    HOST.sweepVanishEvolutions = sweepVanishEvolutions;

    try {
        if (typeof eventOn === 'function' && typeof tavern_events !== 'undefined') {
            eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, sweepVanishEvolutions);
            eventOn(tavern_events.MESSAGE_DELETED, sweepVanishEvolutions);
            eventOn(tavern_events.MESSAGE_SWIPED, sweepVanishEvolutions);
            eventOn(tavern_events.MESSAGE_UPDATED, sweepVanishEvolutions);
            eventOn(tavern_events.CHAT_CHANGED, () => {
                bootEnsureStructure();
                sweepVanishEvolutions();
            });
        }
    } catch (e) { console.warn('[酒馆结构] eventOn 注册失败', e); }

    console.log('[酒馆结构] v2 脚本加载完成（含 expandTavern / getRoomRenovations / addEvolution）, API 挂载于', HOST === window ? 'window' : 'window.top/parent');
})();

