                } catch (e) { console.error('Twemoji error:', e); }
            });
        }
    }

    function smartParse(rawStr) {
        if (!rawStr) return [];
        let str = rawStr.replace(/<[^>]+>/g, '').trim();
        str = str.replace(/[（）]/g, m => m === '（' ? '(' : ')');
        if (str.startsWith('|') || str.startsWith('｜') || str.startsWith('/')) str = str.substring(1);
        if (str.endsWith('|') || str.endsWith('｜') || str.endsWith('/')) str = str.substring(0, str.length - 1);
        const separator = str.includes('|') ? '|' : (str.includes('｜') ? '｜' : '/');
        const parts = str.split(separator);
        return parts.map(p => { let s = p.trim(); if (s.startsWith('(') && s.endsWith(')')) s = s.substring(1, s.length - 1).trim(); return s; }).filter(p => p !== "");
    }

    function isCurrencyLikeText(value) {
        const s = String(value || '').replace(/\s+/g, '');
        return /混合[货貨][币幣]|[金银銀铜銅][币幣]/.test(s);
    }

    function isLikelyIconField(value) {
        const s = String(value || '').trim();
        return s.length > 0 && s.length <= 6 && /[\p{Extended_Pictographic}\u2600-\u27BF]/u.test(s);
    }

    function getCommandNamePart(parts, startIndex = 0) {
        const fields = (parts || []).slice(startIndex);
        if (fields.length === 0) return '';
        return (fields.length >= 2 && isLikelyIconField(fields[0])) ? fields[1] : fields[0];
    }

    function shouldSkipInventoryAdd(parts) {
        // 只检查“名称”位置，避免“估值：5金币”这类描述把普通道具误判成货币。
        return isCurrencyLikeText(getCommandNamePart(parts, 0));
    }

    function shouldSkipInventoryMod(parts) {
        // MOD 也可能把已有物品改成铜币/金币，因此同样拦截货币名称。
        return isCurrencyLikeText(getCommandNamePart(parts, 1));
    }

    function isCurrencyInventoryItem(item) {
        return item && isCurrencyLikeText(item.name);
    }

    function removeFirstInventoryById(list, id) {
        const idx = (list || []).findIndex(x => x && x.id === id);
