    /** 将当前价目表导出为 JSON 文件 */
    // 通用文件保存：兼容部分点了"导出"没反应的手机浏览器（UC/QQ/微信内置/部分安卓自带浏览器）
    // 思路：先尝试标准 <a download> 下载；若浏览器不支持 download 或下载被拦截，
    // 自动弹出一个浮层，把 JSON 文本直接展示出来，并提供"复制"按钮，用户长按/复制即可保存。
    function thSaveTextFile(filename, text, mimeType) {
        mimeType = mimeType || 'application/json';
        let downloadTriggered = false;
        try {
            const a = document.createElement('a');
            // 只有在浏览器认得 download 属性时才走 Blob 下载，否则直接进入兜底浮层
            if ('download' in a) {
                const blob = new Blob([text], { type: mimeType });
                const url = URL.createObjectURL(blob);
                a.href = url;
                a.download = filename;
                a.style.display = 'none';
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                setTimeout(() => { try { URL.revokeObjectURL(url); } catch(e) {} }, 4000);
                downloadTriggered = true;
            }
        } catch (e) {
            console.warn('[inv] 标准下载失败，改用文本浮层兜底', e);
            downloadTriggered = false;
        }
        // 不支持 download 的浏览器：直接展示文本浮层（最稳妥，任何浏览器都能复制保存）
        if (!downloadTriggered) {
            thShowExportFallback(filename, text);
        }
        return downloadTriggered;
    }

    // 兜底浮层：展示导出文本 + 复制按钮，给无法触发下载的浏览器用
    function thShowExportFallback(filename, text) {
        $('#th-export-fallback-ui').remove();
        const safeText = $('<div>').text(text).html();
        const $mask = $(
            '<div id="th-export-fallback-ui" style="position:fixed; inset:0; z-index:100010; background:rgba(0,0,0,0.5); display:flex; align-items:center; justify-content:center; padding:20px; box-sizing:border-box;">' +
            '<div style="background:#FFFEF1; border:2px solid #8B5A2B; border-radius:12px; width:100%; max-width:340px; max-height:80vh; display:flex; flex-direction:column; padding:12px; box-sizing:border-box;">' +
            '<div style="font-weight:bold; color:#5D4037; margin-bottom:6px; font-size:14px;">📋 导出数据（手动保存）</div>' +
            '<div style="font-size:11px; color:#a07850; margin-bottom:8px; line-height:1.5;">当前浏览器无法直接下载文件。请点击"复制全部"，再粘贴到记事本/备忘录保存为 <b>' + filename + '</b>；或长按下方文本框全选复制。</div>' +
            '<textarea readonly style="flex:1; min-height:160px; width:100%; box-sizing:border-box; font-family:monospace; font-size:11px; padding:6px; border:1px solid #ccc; border-radius:6px; resize:none; color:#5D4037; background:#fff;">' + safeText + '</textarea>' +
            '<div style="display:flex; gap:8px; justify-content:flex-end; margin-top:10px;">' +
            '<div class="th-btn th-export-copy" style="padding:6px 14px; border-radius:6px; background:#8B5A2B; color:#fff; border:none; cursor:pointer; font-weight:bold;">复制全部</div>' +
            '<div class="th-btn th-export-close" style="padding:6px 14px; border-radius:6px; background:#fff; border:1px solid #8B5A2B; color:#5D4037; cursor:pointer; font-weight:bold;">关闭</div>' +
            '</div></div></div>'
        );
        $('body').append($mask);
        const $ta = $mask.find('textarea');
        $mask.find('.th-export-copy').on('click', async () => {
            let ok = false;
            try {
                if (navigator.clipboard && navigator.clipboard.writeText) {
                    await navigator.clipboard.writeText(text);
                    ok = true;
                }
            } catch (e) {}
            if (!ok) {
                // execCommand 兜底（老 WebView）
                try {
                    $ta[0].focus();
                    $ta[0].select();
                    $ta[0].setSelectionRange(0, text.length);
                    ok = document.execCommand('copy');
                } catch (e) {}
            }
            if (window.toastr) {
                if (ok) toastr.success('已复制到剪贴板', '系统');
                else toastr.info('请长按文本框手动全选复制', '系统');
            }
        });
        $mask.find('.th-export-close').on('click', () => $mask.remove());
        $mask.on('click', (e) => { if (e.target === $mask[0]) $mask.remove(); });
    }

