function normalize(str) {
    return String(str || "").replace(/\s+/g, "");
}

function extractDateKey(str) {
    if (!str) return "";
    const lastRi = str.lastIndexOf("日");
    if (lastRi === -1) return normalize(str);
    const lastYue = str.lastIndexOf("月", lastRi);
    if (lastYue === -1) return normalize(str);
    const monthPart = str.substring(Math.max(0, lastYue - 2), lastYue);
    const dayPart = str.substring(lastYue + 1, lastRi);
    return normalize(monthPart + dayPart);
}

function getCurrentMvuDateText() {
    let rawToday = "";
    try {
        const mvuInterface = window.Mvu || (window.parent && window.parent.Mvu);
        if (mvuInterface) {
            const mvuData = mvuInterface.getMvuData({ type: 'message', message_id: 'latest' });
            if (mvuData && mvuData.stat_data && mvuData.stat_data['当前时间']) rawToday = mvuData.stat_data['当前时间'];
            else {
                const chatData = mvuInterface.getMvuData({ type: 'chat' });
                if (chatData && chatData.stat_data && chatData.stat_data['当前时间']) rawToday = chatData.stat_data['当前时间'];
            }
        }
    } catch (e) { console.error(e); }
    return rawToday || "";
}

function chineseDayToNumber(text) {
    const s = normalize(String(text || "").replace(/^第/, ""));
    if (!s) return null;
    if (/^\d+$/.test(s)) return parseInt(s, 10);
    const map = { 零:0, 〇:0, 一:1, 二:2, 两:2, 三:3, 四:4, 五:5, 六:6, 七:7, 八:8, 九:9 };
    if (Object.prototype.hasOwnProperty.call(map, s)) return map[s];
    if (s === "十") return 10;
    if (s.indexOf("廿") === 0) return 20 + (map[s.charAt(1)] || 0);
    if (s.indexOf("卅") === 0) return 30 + (map[s.charAt(1)] || 0);
    if (s.indexOf("卌") === 0) return 40 + (map[s.charAt(1)] || 0);
    const tenIndex = s.indexOf("十");
    if (tenIndex !== -1) {
        const left = s.slice(0, tenIndex);
        const right = s.slice(tenIndex + 1);
        const tens = left ? map[left] : 1;
        const ones = right ? map[right] : 0;
        if (typeof tens === 'number' && typeof ones === 'number') return tens * 10 + ones;
    }
    return null;
}

function parseWorldDatePart(text) {
    const raw = String(text || "").trim();
    const match = raw.match(/([^\s~～（）()，,：:]+月)\s*第?([零〇一二两三四五六七八九十廿卅卌\d]+)日/);
    if (!match) return null;
    const day = chineseDayToNumber(match[2]);
    if (day === null) return null;
    return { raw: raw, month: match[1], day: day };
}

function relativeDateLabel(dayDiff) {
    if (dayDiff === -1) return '昨天';
    if (dayDiff === 0) return '今天';
    if (dayDiff === 1) return '明天';
    if (dayDiff < 0) return Math.abs(dayDiff) + '日前';
    return dayDiff + '日后';
}

function formatRelativeDatePart(part, todayPart) {
    return relativeDateLabel(part.day - todayPart.day) + '（' + part.raw + '）';
}

function formatGuestDateRange(dateRange) {
    const raw = String(dateRange || "").trim();
    if (!raw) return "";
    const parts = raw.split(/[~～]/);
    if (parts.length < 2) return raw;
    const startPart = parseWorldDatePart(parts[0]);
    const endPart = parseWorldDatePart(parts.slice(1).join('~'));
    const todayPart = parseWorldDatePart(getCurrentMvuDateText());
    if (!startPart || !endPart || !todayPart) return raw;
    if (startPart.month !== endPart.month) return raw;
    if (startPart.month !== todayPart.month || endPart.month !== todayPart.month) return raw;
    return formatRelativeDatePart(startPart, todayPart) + '~' + formatRelativeDatePart(endPart, todayPart);
}

