    function refreshGuestPrompt(guestList) {
        let content = '';
        if (guestList && guestList.length > 0) {
            let body = `<Current_Guest_Group_Info>\n以下是当前在酒馆入住的客人团体信息表：\n`;

            guestList.forEach((g, i) => {
                const displayDate = g.custom_date || g.date_range || '';
                const displayPurpose = g.custom_purpose || g.purpose || '';
                const displayDateWithRelative = formatGuestDateRange(displayDate);

                let statusParts = [];
                if (g.note) statusParts.push('备注: ' + g.note);
                if (g.pending_payment && g.pending_payment != '0') statusParts.push('待支付: ' + g.pending_payment);
                const statusStr = statusParts.length > 0 ? ' [' + statusParts.join(' | ') + ']' : '';

                body += `\n【团体 ${i + 1}】\n`;
                if ((g.roles && g.roles.length > 0) || g.others) body += `成员:\n`;
                if (g.roles && g.roles.length > 0) {
                    g.roles.forEach(r => {
                        const rName = r['姓名'] || r['Name'] || '';
                        if (!rName) return;
                        const rRoom = r.room ? `(入住房间：${r.room})` : '(未分配房间)';
                        const gender = r['性别'] || r['Gender'] || '';
                        const race = r['种族'] || '';
                        const job = r['职业'] || '';
                        const appearance = r['外貌特征'] || '';
                        const identity = [race, job].filter(Boolean).join('、');
                        let descParts = [];
                        if (gender) descParts.push(gender);
                        if (identity) descParts.push(identity);
                        let detailStr = descParts.length > 0 ? descParts.join('，') + '。' : '';
                        if (appearance) detailStr += String(appearance).replace(/[。.]$/, '') + '。';
                        if (detailStr) detailStr += ' ';
                        body += `  ${rName}：${detailStr}${rRoom}\n`;
                    });
                }
                if (g.others) {
                    const oRoom = g.others_room ? ` (入住房间：${g.others_room})` : '';
                    body += `  其他随行人员: ${g.others}${oRoom}\n`;
                }
                if (displayPurpose || statusStr) body += `事由：${displayPurpose}${statusStr}\n`;
                if (displayDateWithRelative) body += `住宿时间：${displayDateWithRelative}\n`;
            });
            body += `\n</Current_Guest_Group_Info>`;
            content = body;
        }
        if (typeof TavernHelper !== 'undefined') {
            TavernHelper.insertOrAssignVariables({ inventory_ai_view_guests: content }, { type: 'chat' });
        }
        // 注销旧 inject ID（迁移期清理）
        if (typeof uninjectPrompts !== 'undefined') uninjectPrompts([CONFIG.guestPromptId || 'th_guest_info_prompt']);
    }

        function refreshPricePrompt(listData = null, slotsData = null) {
        if (!listData) listData = getPriceData();
        if (!slotsData) slotsData = getPriceSlotsData();

        // 价目板行
        let boardLines = [];
        const count = listData.length - 1;
        for (let i = 0; i < count; i++) {
            if (listData[i] && listData[i].name && listData[i].price) {
                boardLines.push(`${listData[i].name}-${listData[i].price}`);
            }
        }
        // 「老板特别服务-面议」是固定长驻项目：无论用户有没有填其它价目，都始终列出，
        // 这样价目板永远至少有这一行，AI 也就总能知道这项服务可点（此前只在有其它价目/备注时才加，
        // 导致用户什么都没写时整个价目板不写入变量）。
        {
            const noteObj = listData[listData.length - 1];
            const noteContent = (noteObj && noteObj.note) ? `(${noteObj.note})` : '';
            boardLines.push(`老板特别服务${noteContent}-面议`);
        }

        // 商品架行
        const fullInventory = getVars()[CONFIG.varDataKey] || [];
        let shelfLines = [];
        slotsData.forEach(slot => {
            if (slot.id) {
                const item = fullInventory.find(it => it.id === slot.id);
                if (item) {
                    const priceStr = slot.price ? slot.price : '定价待定';
                    const descStr = item.desc ? `(${item.desc})` : '';
                    shelfLines.push(`[ID:${item.id}] ${item.name}${descStr}-${priceStr}`);
                }
            }
        });

        // 公告
        const noticeText = getVars()[CONFIG.varNoticeKey] || '';

        // ---- 信息库 → inventory_ai_view_tariff 变量 ----
        let info = '';
        if (boardLines.length > 0 || shelfLines.length > 0 || noticeText) {
            info = `<Tavern_Tariff>\n`;
            if (boardLines.length > 0) info += `[酒馆价目板]\n${boardLines.join('\n')}\n`;
            if (shelfLines.length > 0) info += `[酒馆商品架]\n${shelfLines.join('\n')}\n`;
            if (noticeText) info += `[公告板]\n${noticeText}\n`;
            info += `</Tavern_Tariff>`;
        }
        if (typeof TavernHelper !== 'undefined') {
            TavernHelper.insertOrAssignVariables({ inventory_ai_view_tariff: info }, { type: 'chat' });
        }

        // ---- 指令 → in_chat depth 998 ----
        const RULE_ID = 'th_tariff_rule_prompt';
        // 旧主 ID 注销 + 新指令 ID 注销（先清，后按需注入）
        if (typeof uninjectPrompts !== 'undefined') uninjectPrompts([CONFIG.pricePromptId, RULE_ID]);
        if (shelfLines.length > 0) {
            const ruleContent = `<Tariff_Rule>
[购买说明]
当客人成功购买<Tavern_Tariff>商品架上的某件商品时，请在本轮正文末尾附上以下格式的指令，系统将据此自动将该商品从货架移除：
<Item>
CMD:DEL | 该商品对应的ID
</Item>
（例：客人购买了 [ID:003] 的商品，则附上 <Item>\\nCMD:DEL | 003\\n</Item>）
</Tariff_Rule>`;
            const injection = { id: RULE_ID, position: 'in_chat', depth: 998, role: 'system', content: ruleContent, should_scan: true };
            if (typeof injectPrompts !== 'undefined') injectPrompts([injection]);
        }
    }

