    async function appendUpdateToChat(text, successMsg) {
        // 新改造：不再创建隐藏楼层，把指令包裹在 <player_silent> 内追加到"最新一楼"尾部
        //   - 永远追加到最大 message_id 那楼，确保 DEL 一定在 ADD 之后，扫描顺序正确
        //   - <player_silent> 是用户手动操作的标记，与 AI 用的 <Item> 区分；AI 见到这个陌生标签
        //     通常会归到结构噪声忽略掉。如果要 AI 完全看不到，自己装一个 regex 把它从 prompt 里剥掉
        //   - 注意：如果用户对最新一楼做 swipe / 重 roll，新 swipe 里没有这段追加，本次操作会丢失
        try {
            if (typeof getChatMessages !== 'function' || typeof setChatMessages !== 'function') {
                console.error('[inv appendUpdateToChat] 当前环境缺少 getChatMessages / setChatMessages');
                return;
            }
            const all = getChatMessages('0-{{lastMessageId}}');
            if (!all || all.length === 0) {
                console.warn('[inv appendUpdateToChat] 聊天里还没有任何楼层，跳过');
                return;
            }
            const last = all[all.length - 1];
            const wrapped = '<player_silent>\n' + text + '\n</player_silent>';
            const newText = String(last.message || '').replace(/\s+$/, '') + '\n\n' + wrapped;
            await setChatMessages([{ message_id: last.message_id, message: newText }], { refresh: 'none' });
            if (window.toastr) toastr.success(successMsg, '系统');
            closeDetailPopup();
            closeEditPopup();
            // 修改的是已扫过的楼层，增量扫无法识别 —— 清掉 checkpoint 走全量扫
            try { clearCheckpoint(); } catch (e) {}
            performScan('full');
        } catch (e) { console.error('[inv appendUpdateToChat]', e); }
    }

