    function extractStaffNameFromProfile(text) {
        if (!text) return '';
        const blockMatch = String(text).match(/<New_Employee_Profile>\s*[\s\S]*?【([\s\S]*?)】[\s\S]*?<\/New_Employee_Profile>/i);
        const content = blockMatch ? blockMatch[1] : String(text);
        const kvRe = /([^|｜【]+?)\s*[：:]\s*([\s\S]*?)(?=(?:\s*[|｜])|(?:\s*】)|$)/g;
        let m;
        while ((m = kvRe.exec(content)) !== null) {
            const key = m[1].trim();
            if (key === '姓名' || key === 'Name' || key === 'name') return m[2].trim();
        }
        return '';
    }

