    // =================================================================
    // === 核心扫描逻辑 ===
    // mode: 'full'（全量，用于删改楼） | 'incremental'（增量，仅新消息）
    // forceCheckpoint: true 时强制在扫描后保存检查点（手动建立检查点时使用）
    // =================================================================
    function performScan(mode, forceCheckpoint) {
        if (mode === undefined) mode = 'full';
        if (forceCheckpoint === undefined) forceCheckpoint = false;

        let allMessages;
        if (typeof getChatMessages !== 'undefined') allMessages = getChatMessages('0-{{lastMessageId}}');
        else if (typeof TavernHelper !== 'undefined') allMessages = TavernHelper.getChatMessages('0-{{lastMessageId}}');
        if (!allMessages) return;

        // ---- 增量扫描：确定起点，并从检查点恢复初始状态 ----
        let scanFromIndex = 0;
        let checkpoint = null;

        let maxId = getMaxId();
        const dbMap = getDbMap();
        let currentInventory = [];
        const usedMapKeys = new Set();
        const achievementMap = new Map();
        const staffMap = new Map();
        // 【v95 员工持久化】staffSeen: 姓名 -> 首次出现的 message_id（招募楼归属）。
        // 员工不再"扫不到就丢"，而是按"招募楼是否仍存在"决定去留。
        const staffSeen = new Map();
        // 当前聊天中真实存在的 message_id 集合（用于增量保存时校验招募楼仍在）。
        const existingMsgIds = new Set(allMessages.map(m => m.message_id));
        let renovationList = [];
        currentWorldDate = "";

        // 【v95 员工持久化】关键设计：message_id 是楼层位置索引，删中间楼会使后续楼层重排，
        // 因此 firstMsgId 只在"楼层不重排"的增量场景可靠。两种模式分别处理：
        //   · 增量（新消息触发，只往后加楼，旧楼 id 稳定）→ 预载持久化映射，避免重扫旧楼导致员工丢失。
        //   · 全量（删楼/swipe/改楼触发，楼层可能重排）→ 不预载，纯从 0 楼重扫，
        //     扫到谁谁在、招募楼被删者自然消失，不受重排影响。这正是"删招募楼员工才消失"的正确实现。
        if (mode === 'incremental') {
            const persistedStaffMap = getVars()[CONFIG.varStaffMapKey] || {};
            for (const [name, rec] of Object.entries(persistedStaffMap)) {
                if (!rec || typeof rec !== 'object') continue;
                if (rec.data) staffMap.set(name, rec.data);
                if (rec.firstMsgId != null) staffSeen.set(name, rec.firstMsgId);
            }
        }

        if (mode === 'incremental') {
            checkpoint = getCheckpoint();
            if (checkpoint && checkpoint.message_id != null) {
                // 找到检查点之后第一条消息的下标
                const cpMsgId = checkpoint.message_id;
                scanFromIndex = allMessages.findIndex(m => m.message_id > cpMsgId);
                if (scanFromIndex === -1) scanFromIndex = allMessages.length; // 没有新消息

                // 从检查点恢复状态
                // 【修复 ID 重复 Bug】不能直接用 checkpoint.maxId 覆盖：
                // 检查点只在 full 模式保存，但 dbMap/maxId 在每次增量扫后都已写回全局变量，
                // 导致 checkpoint.maxId 长期落后于真实最大已分配 ID。
                // 必须取 max(globalMaxId, checkpoint.maxId)，否则 ++maxId 会回退并产生重复 "001"。
                maxId = Math.max(maxId, checkpoint.maxId || 0);
                Object.assign(dbMap, checkpoint.dbMap || {});
                // 把检查点里所有 dbMap 的 key 都标记为"使用中"，防止被清理
                Object.keys(checkpoint.dbMap || {}).forEach(k => usedMapKeys.add(k));
                if (checkpoint.inventory) currentInventory = [...checkpoint.inventory];
                if (checkpoint.achievements) checkpoint.achievements.forEach(a => achievementMap.set(a.name, a));
                // 员工：检查点快照只作补充，最终以持久化映射（上面已预载）为准。
                // 这里仅在持久化映射缺失时回填，避免快照与映射不一致时丢人。
                if (checkpoint.staff) checkpoint.staff.forEach(s => {
                    const name = s['姓名'] || s['Name'] || s['name'];
                    if (name && !staffMap.has(name)) staffMap.set(name, s);
                });
                if (checkpoint.staffSeen) {
                    Object.entries(checkpoint.staffSeen).forEach(([n, fid]) => {
                        if (!staffSeen.has(n) && fid != null && existingMsgIds.has(fid)) staffSeen.set(n, fid);
                    });
                }
                if (checkpoint.renovationList) renovationList = [...checkpoint.renovationList];
                if (checkpoint.worldDate) currentWorldDate = checkpoint.worldDate;
            } else {
                // 没有检查点，退化为全量扫描
                mode = 'full';
                scanFromIndex = 0;
                // 【v95】退化为全量：清掉刚才按增量预载的员工，改为纯重扫，
                // 否则招募楼已删的员工会被预载残留误留。
                staffMap.clear();
                staffSeen.clear();
            }
        }

        // 全量扫描 + 导入基准：若存在 importBase，以导入数据为初始状态，
        // 并且只扫描导入时刻之后的新消息，避免重放旧消息导致物品重复叠加。
        if (mode === 'full') {
            // 读取独立存储的导入基准（删楼触发的 clearCheckpoint 不会清掉它）
            let _importBase = null;
            try { if (typeof TavernHelper !== 'undefined') _importBase = TavernHelper.getVariables({ type: 'chat' })[CONFIG.varImportBaseKey] || null; } catch(e) {}
            if (_importBase) {
                currentInventory = [...(_importBase.inventory || [])];
                // 【修复 ID 重复 Bug】同上：取 max 而非覆盖，避免 importBase.maxId 落后导致 ++maxId 倒退
                maxId = Math.max(maxId, _importBase.maxId || 0);
                Object.assign(dbMap, _importBase.dbMap || {});
                Object.keys(_importBase.dbMap || {}).forEach(k => usedMapKeys.add(k));
                if (_importBase.achievements) _importBase.achievements.forEach(a => achievementMap.set(a.name, a));
                // 导入的员工：归属到"导入时刻所在楼层"，使其不因招募楼不在当前聊天而被误删。
                if (_importBase.staff) _importBase.staff.forEach(s => {
                    const n = s['姓名']||s['Name']||s['name'];
                    if (n) {
                        staffMap.set(n, s);
                        if (!staffSeen.has(n)) {
                            const anchor = _importBase.importedAtMsgId != null ? _importBase.importedAtMsgId
                                         : (allMessages.length > 0 ? allMessages[0].message_id : 0);
                            staffSeen.set(n, anchor);
                        }
                    }
                });
                if (_importBase.renovationList) renovationList = [...(_importBase.renovationList)];
                // 【修复 Bug 1】只扫描导入时刻之后的新消息，防止旧消息被重放叠加
                if (_importBase.importedAtMsgId != null) {
                    // 新格式导出文件：精确跳到导入后的第一条新消息
                    const importScanStart = allMessages.findIndex(m => m.message_id > _importBase.importedAtMsgId);
                    scanFromIndex = importScanStart === -1 ? allMessages.length : importScanStart;
                } else {
                    // 【兼容旧格式导出文件】没有 importedAtMsgId 字段时，
                    // 放弃 importBase 里的物品初始值，退化为纯全量扫描，
                    // 至少保证不会叠加，避免 Bug 1 复现。
                    currentInventory = [];
                    maxId = 0;
                    Object.keys(_importBase.dbMap || {}).forEach(k => { delete dbMap[k]; usedMapKeys.delete(k); });
                    achievementMap.clear();
                    staffMap.clear();
                    staffSeen.clear();
                    renovationList = [];
                }
            }
        }

        // --- 0. dbMap 格式迁移（旧格式 → 新格式，保证全量重扫不会重新分配 ID）---
        // 旧格式 key: "msgId_add_N"（N 是跨消息的全局累计序号，受 usedMapKeys.size 影响）
        // 新格式 key: "msgId_add_M"（M 是该条消息内的独立序号，从 0 开始）
        // 迁移策略：按 msgId 分组，保留 assignedId 不变，只把 key 重新编号为 0,1,2...
        // 幂等：已经是新格式的 key 运行后结果不变；可以安全地在每次全量扫里执行。
        (function migrateLegacyDbMapKeys() {
            const groups = {};
            Object.entries(dbMap).forEach(([key, id]) => {
                const m = key.match(/^(\d+)_add_(\d+)$/);
                if (m) {
                    const mid = m[1];
                    if (!groups[mid]) groups[mid] = [];
                    groups[mid].push({ key, seq: parseInt(m[2], 10), id });
                }
            });
            Object.entries(groups).forEach(([mid, entries]) => {
                // 按原有序号排序，保证重编号后相对顺序不变
                entries.sort((a, b) => a.seq - b.seq);
                entries.forEach((entry, i) => {
                    const newKey = `${mid}_add_${i}`;
                    if (entry.key !== newKey) {
                        dbMap[newKey] = entry.id;
                        delete dbMap[entry.key];
                        // usedMapKeys 同步更新
                        if (usedMapKeys.has(entry.key)) {
                            usedMapKeys.delete(entry.key);
                            usedMapKeys.add(newKey);
                        }
                    }
                });
            });
        })();

        // 【修复 ID 重复 Bug】最终保险：maxId 必须 ≥ 任何已分配 ID 的最大数值。
        // 这样 ++maxId 一定产生全新 ID，不会与 dbMap/currentInventory 中现有 ID 冲突，
        // 彻底消除"陆续新增物品 ID 全是 001 / inventory_max_id 停在 0"的现象。
        {
            const _mFromMap = computeMaxIdFromDbMap(dbMap);
            const _mFromInv = computeMaxIdFromInventory(currentInventory);
            if (_mFromMap > maxId) maxId = _mFromMap;
            if (_mFromInv > maxId) maxId = _mFromInv;
        }

        // 【修复 ID 粘连 Bug】dbMap 的 value 去重：
        // 历史数据中可能出现多个 key 映射到同一个 ID（典型症状：两个物品共用 "001"，
        // 点重新扫描也改不过来）。按消息/序号升序保留首条映射，其余重新分配全新 ID，
        // 这样相关物品在后续扫描里会获得彼此独立的 ID。
        (function dedupeDbMapValues() {
            const valueGroups = {};
            Object.entries(dbMap).forEach(([key, id]) => {
                if (id === null || id === undefined || id === "") return;
                const parsed = String(key).match(/^(\d+)_add_(\d+)$/);
                const mid = parsed ? parseInt(parsed[1], 10) : Number.MAX_SAFE_INTEGER;
                const seq = parsed ? parseInt(parsed[2], 10) : Number.MAX_SAFE_INTEGER;
                if (!valueGroups[id]) valueGroups[id] = [];
                valueGroups[id].push({ key, mid, seq });
            });
            Object.values(valueGroups).forEach(entries => {
                if (entries.length <= 1) return;
                entries.sort((a, b) => a.mid - b.mid || a.seq - b.seq);
                for (let i = 1; i < entries.length; i++) {
                    dbMap[entries[i].key] = String(++maxId).padStart(3, '0');
                }
            });
        })();

        // --- 1. 建立历史档案（保存用户手动编辑的客人数据，如备注、欠费等）---
        let historicalMap = {}; 
        let cleanIdMap = {}; 

        if (typeof TavernHelper !== 'undefined') {
            const currentVars = TavernHelper.getVariables({ type: 'chat' });
            const savedGuests = currentVars[CONFIG.varGuestKey];
            let listToLoad = [];
            if (Array.isArray(savedGuests)) listToLoad = savedGuests;
            else if (savedGuests && typeof savedGuests === 'object') listToLoad = [savedGuests];

            listToLoad.forEach(g => {
                const rawId = getGuestGroupID(g);
                historicalMap[rawId] = g;
                cleanIdMap[normalize(rawId)] = g;
                if (g._guest_original_id) {
                    historicalMap[g._guest_original_id] = g;
                    cleanIdMap[normalize(g._guest_original_id)] = g;
                }
            });
        }

        // 增量模式：以检查点快照的客人状态为起点，再用最新手动编辑覆盖一遍
        let activeGuestBook = {};
        if (mode === 'incremental' && checkpoint && checkpoint.activeGuestBook) {
            Object.entries(checkpoint.activeGuestBook).forEach(([id, guest]) => {
                // 用最新 historicalMap 中的手动编辑数据覆盖（防止检查点建立后用户又手动改了）
                const savedGuest = historicalMap[id] || cleanIdMap[normalize(id)];
                if (savedGuest) {
                    guest.pending_payment = savedGuest.pending_payment;
                    guest.note = savedGuest.note || "";
                    guest._guest_original_id = savedGuest._guest_original_id || guest._guest_original_id;
                    guest.others = (typeof savedGuest.others !== 'undefined') ? savedGuest.others : guest.others;
                    guest.others_room = savedGuest.others_room || "";
                    guest.custom_date = savedGuest.custom_date;
                    guest.custom_purpose = savedGuest.custom_purpose;
                    if (savedGuest.roles && guest.roles) {
                        const savedRolesMap = {};
                        savedGuest.roles.forEach((r, idx) => {
                            const n = r['姓名'] || r['Name'];
                            if (n) savedRolesMap[normalize(n)] = { role: r, index: idx };
                        });
                        guest.roles.forEach((nr, idx) => {
                            const n = nr['姓名'] || nr['Name'];
                            const matched = (n && savedRolesMap[normalize(n)] && savedRolesMap[normalize(n)].role) || savedGuest.roles[idx];
                            if (!matched) return;
                            ['姓名', 'Name', '性别', 'Gender', '种族', '职业', '外貌特征', 'room'].forEach(key => {
                                if (typeof matched[key] !== 'undefined') nr[key] = matched[key];
                            });
                        });
                    }
                }
                activeGuestBook[id] = guest;
            });
        }

        // --- 2. 扫描循环（增量模式/importBase 均通过 scanFromIndex 控制起点）---
        // 【修复 Bug 1】统一用 scanFromIndex 切片，full 模式下默认 scanFromIndex=0（全量），
        // 有 importBase 时 scanFromIndex 已被设为导入后的第一条新消息，防止重放旧消息。
        const messagesToScan = allMessages.slice(scanFromIndex);
        // 【修复 Bug 2】per-message ADD 序号计数器
        // 使 uniqueKey 只依赖「消息id + 该消息内第几个ADD」，与 usedMapKeys 的预载数量无关，
        // 从而保证 dbMap 查找稳定，消除跳 ID / 重复 ID 问题。
        const msgAddCounters = {};
        for (const msg of messagesToScan) {
            const text = msg.message || msg.mes || "";
            if (!text) continue;

            // 追踪当前世界日期
            if (text.includes('[STATUS]')) {
                const dateMatch = text.match(CONFIG.regexStatusDate);
                if (dateMatch && dateMatch[1]) currentWorldDate = dateMatch[1].trim();
            }

            // 扫描基建修缮记录
            if (text.includes('修缮')) {
                CONFIG.regexRenovation.lastIndex = 0;
                for (const m of text.matchAll(CONFIG.regexRenovation)) {
                    renovationList.push({
                      date: currentWorldDate || "未知日期",
    cost: m[1],
    detail: m[2].replace(/。\s*$/, "").trim()
                    });
                }
            }

            const foundGuests = parseGuestData(text);
foundGuests.forEach(foundGuest => {
    const rawId = getGuestGroupID(foundGuest);
    const cleanId = normalize(rawId);

    let oldData = historicalMap[rawId] || cleanIdMap[cleanId];

    if (oldData) {
        foundGuest.pending_payment = oldData.pending_payment; 
        foundGuest.note = oldData.note || "";
        foundGuest.others_room = oldData.others_room || "";
        foundGuest.custom_date = oldData.custom_date;
        foundGuest.custom_purpose = oldData.custom_purpose;

        const oldRolesMap = {};
        if (oldData.roles && Array.isArray(oldData.roles)) {
            oldData.roles.forEach(r => {
                const rName = r['姓名'] || r['Name'];
                if (rName) oldRolesMap[normalize(rName)] = r;
            });
        }
        if (foundGuest.roles && Array.isArray(foundGuest.roles)) {
            foundGuest.roles.forEach(newRole => {
                const newName = newRole['姓名'] || newRole['Name'];
                const cleanName = normalize(newName);
                if (cleanName && oldRolesMap[cleanName]) {
                    newRole.room = oldRolesMap[cleanName].room || "";
                }
            });
        }
    }
    activeGuestBook[rawId] = foundGuest;
});

            // 删除指令
            if (text.includes('CMD:DEL_GUEST')) {
                CONFIG.regexGuestDel.lastIndex = 0;
                for (const m of text.matchAll(CONFIG.regexGuestDel)) {
                    const targetId = m[1].trim();
                    if (targetId) {
                        if(activeGuestBook[targetId]) delete activeGuestBook[targetId];
                        else {
                            const cleanTarget = normalize(targetId);
                            Object.keys(activeGuestBook).forEach(k => {
                                if(normalize(k) === cleanTarget) delete activeGuestBook[k];
                            });
                        }
                    }
                }
            }
            // 仅把 <Item> 或 <player_silent> 标签内的内容当作物品 CMD 的扫描范围；
            // 这样 AI 思维链里出现裸 "CMD:ADD/MOD/DEL" 文本不会被误判执行。
            let cmdScope = '';
            {
                const wrapRe = /<(Item|player_silent)>([\s\S]*?)<\/\1>/gi;
                let mw;
                while ((mw = wrapRe.exec(text)) !== null) { cmdScope += '\n' + mw[2]; }
            }
            if (cmdScope.includes('CMD:ADD')) {
                CONFIG.regexLineAdd.lastIndex = 0;
                for (const m of cmdScope.matchAll(CONFIG.regexLineAdd)) {
                    let parts = smartParse(m[1]);
                    if (parts.length > 0 && /^\d+$/.test(parts[0])) parts.shift();
                    if (parts.length >= 2) {
                        // 货币不是道具。检查图标/名称位置，兼容缺图标/字段错位/繁体/空格写法。
                        if (shouldSkipInventoryAdd(parts)) continue;
                        const uniqueKey = `${msg.message_id}_add_${msgAddCounters[msg.message_id] !== undefined ? msgAddCounters[msg.message_id] : 0}`;
                        if (msgAddCounters[msg.message_id] === undefined) msgAddCounters[msg.message_id] = 0;
                        msgAddCounters[msg.message_id]++;
                        usedMapKeys.add(uniqueKey);
                        let assignedId = dbMap[uniqueKey] || String(++maxId).padStart(3, '0');
                        dbMap[uniqueKey] = assignedId;
                        currentInventory.push({ id: assignedId, icon: parts[0], name: parts[1], desc: parts.length >= 3 ? parts[2] : "" });
                    }
                }
            }
            if (cmdScope.includes('CMD:MOD')) {
                CONFIG.regexLineMod.lastIndex = 0;
                for (const m of cmdScope.matchAll(CONFIG.regexLineMod)) {
                    const parts = smartParse(m[1]);
                    if (parts.length >= 3) {
                        // 禁止 MOD 把已有道具改成货币，避免 AI 用 MOD 绕过 CMD:ADD 的货币过滤。
                        if (shouldSkipInventoryMod(parts)) continue;
                        const idx = currentInventory.findIndex(x => x.id === parts[0]);
                        if (idx !== -1) {
                            currentInventory[idx].icon = parts[1];
                            currentInventory[idx].name = parts[2];
                            if (parts.length >= 4) currentInventory[idx].desc = parts[3];
                        }
                    }
                }
            }
            if (cmdScope.includes('CMD:DEL')) {
                CONFIG.regexLineDel.lastIndex = 0;
                for (const m of cmdScope.matchAll(CONFIG.regexLineDel)) {
                    const parts = smartParse(m[1]);
                    if (parts.length >= 1) {
                        // 历史脏数据里可能存在重复 ID；每条 DEL 只代表一次用户操作，避免一删删一串。
                        currentInventory = removeFirstInventoryById(currentInventory, parts[0]);
                    }
                }
            }
            if (text.includes('成就')) { CONFIG.regexAchievement.lastIndex = 0; for (const m of text.matchAll(CONFIG.regexAchievement)) { achievementMap.set(m[2].trim(), { icon: m[1].trim(), name: m[2].trim(), condition: m[3].trim(), reward: m[4].trim(), eval: m[5].trim() }); } }
            if (text.includes('CMD:DEL_STAFF')) {
                CONFIG.regexStaffDel.lastIndex = 0;
                for (const m of text.matchAll(CONFIG.regexStaffDel)) {
                    const targetName = m[1].trim();
                    if (targetName) {
                        staffMap.delete(targetName);
                        staffSeen.delete(targetName); // 【v95】显式解雇/编辑覆盖：先解除旧归属，再允许同楼的新员工卡写回
                    }
                }
            }
            if (text.match(/<New_Employee_Profile>/i)) { CONFIG.regexStaffBlock.lastIndex = 0; for (const blockMatch of text.matchAll(CONFIG.regexStaffBlock)) { const innerContent = blockMatch[1]; if (!innerContent) continue; let staffObj = {}; CONFIG.regexStaffKV.lastIndex = 0; for (const kvMatch of innerContent.matchAll(CONFIG.regexStaffKV)) { staffObj[kvMatch[1].trim()] = kvMatch[2].trim(); } let name = staffObj['姓名'] || staffObj['Name'] || staffObj['name']; if (name) { staffMap.set(name, staffObj); /* 【v95】首次出现的楼层即招募楼，记入归属；后续重复出现只更新 data，不改归属 */ if (!staffSeen.has(name)) staffSeen.set(name, msg.message_id); } } }
        }

        // 兜底清理：历史/检查点里若已被错误 MOD 成货币，移出物品栏。
        currentInventory = currentInventory.filter(item => !isCurrencyInventoryItem(item));
        // 【修复 ID 粘连 Bug】扫描结束后的兜底去重：
        // 如果旧检查点 / 旧导入基准中 currentInventory 本身带有重复 ID（且对应的 dbMap
        // 脏数据在上面的 dedupeDbMapValues 环节被修掉了一半，但物品仍沿用旧 ID），
        // 这里再扫一遍，把重复 ID 的物品强制换成新 ID，并把 dbMap 里指向旧 ID 的最新
        // 那条记录同步刷到新 ID，保证下次扫描不会再复现。
        (function dedupeInventoryIds() {
            const seen = new Set();
            for (const item of currentInventory) {
                if (!item || !item.id) continue;
                if (!seen.has(item.id)) { seen.add(item.id); continue; }
                const oldId = item.id;
                const newId = String(++maxId).padStart(3, '0');
                item.id = newId;
                seen.add(newId);
                let candidateKey = null, candidateMid = -1, candidateSeq = -1;
                for (const [k, v] of Object.entries(dbMap)) {
                    if (v !== oldId) continue;
                    const p = String(k).match(/^(\d+)_add_(\d+)$/);
                    const mid = p ? parseInt(p[1], 10) : 0;
                    const seq = p ? parseInt(p[2], 10) : 0;
                    if (mid > candidateMid || (mid === candidateMid && seq > candidateSeq)) {
                        candidateKey = k; candidateMid = mid; candidateSeq = seq;
                    }
                }
                if (candidateKey) dbMap[candidateKey] = newId;
            }
        })();

        // 3. 保存与渲染
        const newDbMap = {}; Object.keys(dbMap).forEach(key => { if (usedMapKeys.has(key)) newDbMap[key] = dbMap[key]; });
        const currentAchievements = Array.from(achievementMap.values());
        const currentStaff = Array.from(staffMap.values());

        // 【v95 员工持久化】构建 staffRecordMap：姓名 -> { firstMsgId, data }。
        // 只保留招募楼仍存在的员工；这份映射是下次扫描的权威来源，确保员工不会"扫不到就丢"。
        const staffRecordMap = {};
        staffMap.forEach((data, name) => {
            let fid = staffSeen.has(name) ? staffSeen.get(name) : null;
            // 没有归属（理论上少见）时，锚定到当前最新楼层，避免被立即判定为"招募楼已删"
            if (fid == null) { const lm = allMessages.length > 0 ? allMessages[allMessages.length - 1].message_id : 0; fid = lm; }
            if (!existingMsgIds.has(fid)) return; // 招募楼已不存在 -> 不持久化（员工消失）
            staffRecordMap[name] = { firstMsgId: fid, data: data };
        });
        const staffSeenObj = {};
        staffSeen.forEach((fid, name) => { if (existingMsgIds.has(fid)) staffSeenObj[name] = fid; });

        let staffItemsMap = getVars()[CONFIG.varStaffItemsKey] || {};
        let isStaffMapDirty = false;
        for (const [staffName, heldIds] of Object.entries(staffItemsMap)) {
            const validIds = heldIds.filter(id => currentInventory.some(item => item.id === id));
            if (validIds.length !== heldIds.length) { staffItemsMap[staffName] = validIds; isStaffMapDirty = true; }
        }
        // 【v95 提速】不再单独写一次，合并进下方主 varsToSave 一次性写回（减少高楼层卡顿）

        let roomItemsMap = getRoomItemsMap();
        let isRoomItemsDirty = false;
        for (const [roomKey, heldIds] of Object.entries(roomItemsMap)) {
            const validIds = (heldIds || []).filter(id => currentInventory.some(item => item.id === id)).slice(0, 4);
            if (validIds.length !== (heldIds || []).length) { roomItemsMap[roomKey] = validIds; isRoomItemsDirty = true; }
        }

        let priceSlotsData = getPriceSlotsData();
        let isSlotsDirty = false;
        // 货架记忆：物品因从库存消失(被 CMD:DEL 卖出)而要清出货架槽前，先记下它原来的槽位与定价。
        // 这样若玩家随后 swipe 撤销了那条卖出正文、物品在库存里复活，下方“退回货架”逻辑能把它放回原槽，而不是掉回背包。
        let shelfMemory = getVars()[CONFIG.varShelfMemoryKey] || {};
        let isShelfMemoryDirty = false;
        priceSlotsData.forEach((slot, idx) => {
            if (slot.id && !currentInventory.some(item => item.id === slot.id)) {
                if (!shelfMemory[slot.id] || shelfMemory[slot.id].done) { shelfMemory[slot.id] = { slotIdx: idx, price: slot.price || "" }; isShelfMemoryDirty = true; }
                slot.id = null; slot.price = ""; isSlotsDirty = true;
            }
        });

        const guestListToSave = Object.values(activeGuestBook);

        // === 退回货架：若被卖出清槽的物品在库存里复活了(玩家 swipe 撤销了卖出正文)，把它放回原货架槽，而不是让它掉回背包 ===
        // 注：记忆条目消费后用 done=true 标记而非删除——本脚本统一用 insertOrAssignVariables(合并语义，删不掉键)，
        // 故以标记跳过代替删除；done 条目极少(仅“卖出又复活过”的物品)且每轮被直接跳过，不影响逻辑。
        {
            const occupiedIds = new Set(priceSlotsData.filter(s => s.id).map(s => s.id));
            Object.values(staffItemsMap).forEach(ids => (ids || []).forEach(id => occupiedIds.add(id)));
            Object.values(roomItemsMap).forEach(ids => (ids || []).forEach(id => occupiedIds.add(id)));
            for (const memId of Object.keys(shelfMemory)) {
                const mem = shelfMemory[memId];
                if (!mem || mem.done) continue;                       // 已消费的记忆，跳过
                if (occupiedIds.has(memId)) { mem.done = true; isShelfMemoryDirty = true; continue; } // 已在某槽(手动放回)→消费
                if (!currentInventory.some(it => it.id === memId)) continue; // 仍是卖出状态→留着等 swipe 复活
                // 物品已在库存复活且不占任何槽 → 放回原槽(原槽空则用原槽，否则任意空槽；货架满则留库存待手动上架)
                let targetIdx = (Number.isInteger(mem.slotIdx) && priceSlotsData[mem.slotIdx] && !priceSlotsData[mem.slotIdx].id) ? mem.slotIdx : -1;
                if (targetIdx === -1) targetIdx = priceSlotsData.findIndex(s => !s.id);
                if (targetIdx !== -1) {
                    priceSlotsData[targetIdx].id = memId;
                    priceSlotsData[targetIdx].price = mem.price || "";
                    occupiedIds.add(memId);
                    isSlotsDirty = true;
                }
                mem.done = true;
                isShelfMemoryDirty = true;
            }
        }

        if (typeof TavernHelper !== 'undefined') {
            let varsToSave = { 
                [CONFIG.varDataKey]: currentInventory, 
                [CONFIG.varMapKey]: newDbMap, 
                [CONFIG.varMaxIdKey]: maxId, 
                [CONFIG.varAchieveKey]: currentAchievements,
                [CONFIG.varGuestKey]: guestListToSave,
                [CONFIG.varRenoKey]: renovationList, // 保存基建记录
                [CONFIG.varStaffKey]: currentStaff,  // 渲染用的员工数组快照
                [CONFIG.varStaffMapKey]: staffRecordMap // 【v95】员工持久化映射（权威来源）
            };
            if (isSlotsDirty) varsToSave[CONFIG.varPriceSlotsKey] = priceSlotsData;
            if (isShelfMemoryDirty) varsToSave[CONFIG.varShelfMemoryKey] = shelfMemory;
            if (isStaffMapDirty) varsToSave[CONFIG.varStaffItemsKey] = staffItemsMap; // 合并：清理失效持有物品
            if (isRoomItemsDirty) varsToSave[CONFIG.varRoomItemsKey] = roomItemsMap; // 合并：清理失效房间放置物

            TavernHelper.insertOrAssignVariables(varsToSave, { type: 'chat' });

            refreshGuestPrompt(guestListToSave);
            checkDeparturePrompt(guestListToSave);
        }

        // === 脏标记：标记所有 Tab 数据已更新，等待按需渲染 ===
        ['inventory', 'staff', 'achievement', 'price', 'infra'].forEach(t => dirtyTabs.add(t));

        if (isPanelOpen) renderActiveTab();
        if (isStorageOpen) renderStorageItems();

        // === 自动检查点：全量扫描完成后，视情况更新检查点 ===
        if (mode === 'full') {
            const latestMsg = allMessages.length > 0 ? allMessages[allMessages.length - 1] : null;
            const latestMsgId = latestMsg ? latestMsg.message_id : 0;
            const existingCp = getCheckpoint();
            const lastCpId = existingCp ? (existingCp.message_id || 0) : 0;
            // 【修复 物品消失 Bug】护栏：手动建立检查点(forceCheckpoint)始终允许；
            // 自动建立时，绝不在"生成中"或"最新楼文本为空"的时刻把它存成检查点——
            // 否则会把一个尚未写入物品指令的空楼快照固化下来，导致后续增量扫丢物品。
            const latestText = latestMsg ? String(latestMsg.message || latestMsg.mes || '').trim() : '';
            const cpSafe = forceCheckpoint || (!isGenerating && latestText !== '');
            if (cpSafe && (forceCheckpoint || (latestMsgId - lastCpId >= CONFIG.checkpointInterval))) {
                saveCheckpoint({
                    message_id: latestMsgId,
                    maxId: maxId,
                    dbMap: newDbMap,
                    inventory: currentInventory,
                    achievements: currentAchievements,
                    staff: currentStaff,
                    staffSeen: staffSeenObj, // 【v95】员工归属楼层快照
                    activeGuestBook: activeGuestBook,
                    renovationList: renovationList,
                    worldDate: currentWorldDate
                });
                // Keep the import base permanently. Checkpoints serve incremental scans only;
                // full scans still need this baseline to preserve data brought from another chat.
            }
        }

        // 注入基建Prompt
        refreshInfraPrompt(renovationList);

        let storageList = getVars()[CONFIG.varStorageKey] || [];
        const _validStorage = storageList.filter(id => currentInventory.some(item => item.id === id));
        if (_validStorage.length !== storageList.length) { storageList = _validStorage; if (typeof TavernHelper !== 'undefined') TavernHelper.insertOrAssignVariables({ [CONFIG.varStorageKey]: storageList }, { type: 'chat' }); }
        let allStaffHeldIds = [];
        Object.values(staffItemsMap).forEach(ids => allStaffHeldIds = allStaffHeldIds.concat(ids));
        let allRoomHeldIds = [];
        Object.values(roomItemsMap).forEach(ids => allRoomHeldIds = allRoomHeldIds.concat(ids || []));
        const priceHeldIds = priceSlotsData.filter(s => s.id).map(s => s.id);
        const aiVisibleInventory = currentInventory.filter(item => !storageList.includes(item.id) && !allStaffHeldIds.includes(item.id) && !allRoomHeldIds.includes(item.id) && !priceHeldIds.includes(item.id));
        refreshSystemPrompt(aiVisibleInventory); 
        refreshStaffPrompt(currentStaff, currentInventory, staffItemsMap);
        refreshPricePrompt(null, isSlotsDirty ? priceSlotsData : null); 
        $('#th-inv-counter').text(`物品:${aiVisibleInventory.length}${(storageList.length + allStaffHeldIds.length + allRoomHeldIds.length + priceHeldIds.length) > 0 ? `(+${storageList.length + allStaffHeldIds.length + allRoomHeldIds.length + priceHeldIds.length})` : ''}`);
        $('#th-ach-counter').text(`成就:${currentAchievements.length}`);
    }


