    function refreshSystemPrompt(inventory) {
        // ---- 信息库：物品清单 → 写入 inventory_ai_view_items 变量 ----
        let itemListContent = '';
        if (inventory && inventory.length > 0) {
            let listStr = '';
            inventory.forEach(item => {
                listStr += `ID: ${item.id} | ${item.icon} | ${item.name} | ${item.desc || '无描述'}\n`;
            });
            itemListContent = `\n${listStr.trim()}\n`;
        }
        if (typeof TavernHelper !== 'undefined') {
            TavernHelper.insertOrAssignVariables({ inventory_ai_view_items: itemListContent }, { type: 'chat' });
        }

        // ---- 指令：CMD 格式说明 → in_chat depth 998 ----
        const formatContent = `<Item_Format>
本轮剧情若有物品获取/变化/消耗，请严格按以下格式记录在正文末尾，并以一组<Item>标签包裹所有增删改：
1.获得重要物品: CMD:ADD | 图标 | 名称 | (选填)描述
2.物品发生重要性质变化: CMD:MOD | ID | 修正图标 | 修正名称 | (选填)修正描述
3.物品用完/丢弃/所有权转移: CMD:DEL | ID
注意:
 - (如有)描述应始终记录物品最本质客观的属性
 - 禁止将货币计入物品，也禁止用 CMD:MOD 将已有物品改为金币/银币/铜币等货币
 - ID仅作为增删改格式使用，禁止出现在剧情中

示例:
  以一罐蒜蓉酱为例，剧情中获得蒜蓉酱时:
 <Item>
 CMD:ADD | 🥫 | 蒜蓉酱 | 一罐未拆封的蒜蓉酱(250g)
 </Item>

 使用蒜蓉酱后(量发生变化，用分数表示):
 <Item>
 CMD:MOD | 001(该道具在数据库中对应ID) | 🥫 | 蒜蓉酱 | 开封蒜蓉酱(175/250g)，还剩下半罐
 </Item>

 蒜蓉酱用完时:
 <Item>
 CMD:DEL | 001
 </Item>
</Item_Format>`;
        if (typeof uninjectPrompts !== 'undefined') uninjectPrompts([CONFIG.promptId]);
        const injection = { id: CONFIG.promptId, position: 'in_chat', depth: 998, role: 'system', content: formatContent, should_scan: true };
        if (typeof injectPrompts !== 'undefined') injectPrompts([injection]);
    }

        function refreshStaffPrompt(staffList, fullInventory, staffItemsMap) {
        let content = '';
        if (staffList && staffList.length > 0) {
            let _staffNotes = {};
            try { if (typeof TavernHelper !== 'undefined') _staffNotes = TavernHelper.getVariables({ type: 'chat' })[CONFIG.varStaffNotesKey] || {}; } catch(e) {}

            const yamlValue = (value, indent = '  ') => {
                const text = String(value == null ? '' : value).trim();
                if (!text) return '';
                if (/\r|\n/.test(text)) {
                    return '|-\n' + text.replace(/\r\n/g, '\n').split('\n').map(line => indent + '  ' + line).join('\n');
                }
                return text;
            };

            const lines = ['<Employee_Profile>', '目前酒馆的员工：', ''];
            staffList.forEach((staff, index) => {
                if (index > 0) lines.push('');

                const cleanStaff = {};
                for (const [k, v] of Object.entries(staff)) {
                    if (v === '' || v == null) continue;
                    if (k === '持有物品' || k === '持有物（<user>给予）') continue;
                    cleanStaff[k] = v;
                }

                const name = cleanStaff['姓名'] || cleanStaff['Name'] || cleanStaff['name'];
                const heldIds = (staffItemsMap && name) ? (staffItemsMap[name] || []) : [];
                const heldItems = [];
                heldIds.forEach(id => {
                    const item = (fullInventory || []).find(i => i.id === id);
                    if (!item) return;
                    const desc = item.desc || item.description || item['描述'] || '';
                    heldItems.push(`${item.icon || ''} ${item.name || '未知物品'}${desc ? ` (${desc})` : ''}`.trim());
                });

                if (name && _staffNotes[name]) cleanStaff['备注'] = _staffNotes[name];

                let firstField = true;
                for (const [k, v] of Object.entries(cleanStaff)) {
                    const prefix = firstField ? '- ' : '  ';
                    lines.push(prefix + `${k}: ${yamlValue(v)}`);
                    firstField = false;
                }

                if (heldItems.length > 0) {
                    if (firstField) {
                        lines.push('- 持有物（<user>给予）:');
                    } else {
                        lines.push('  持有物（<user>给予）:');
                    }
                    heldItems.forEach(itemText => lines.push('    - ' + itemText));
                }
            });
            lines.push('', '</Employee_Profile>');
            content = lines.join('\n');
        }
        if (typeof TavernHelper !== 'undefined') {
            TavernHelper.insertOrAssignVariables({ inventory_ai_view_staff: content }, { type: 'chat' });
        }
        // 注销旧 inject ID（迁移期清理；后续每次调用都执行也是幂等的）
        if (typeof uninjectPrompts !== 'undefined') uninjectPrompts([CONFIG.staffPromptId]);
    }

        function refreshInfraPrompt(renoList) {
        let content = '';
        const rawHiddenSet = getVars()[CONFIG.varRenoHiddenKey];
        // Older broken merges may have stored this list as an object. Read it safely so the
        // inventory can open again, then the next merge writes the normal array form.
        const hiddenSet = new Set(Array.isArray(rawHiddenSet) ? rawHiddenSet : Object.values(rawHiddenSet || {}));
        const visibleEntries = [];
        // 按 entry 级拆解原始 detail，过滤被玩家隐形删除的条目；不限条数（之前是 slice(-10)）
        const re = /(?:\[#(\d{2,3})\]\s*)?([^、,，()（）]+?(?:[（(][^)）]*[)）])?)\s*[（(]花费(\d+)铜币进行([\s\S]*?)[)）](?:[、,，]|$)/g;
        for (const entry of (renoList || [])) {
            if (!entry || !entry.detail) continue;
            re.lastIndex = 0;
            let m;
            while ((m = re.exec(entry.detail)) !== null) {
                let id = m[1] || '';
                let name = (m[2] || '').trim();
                const tail = name.match(/\[#(\d{2,3})\]\s*$/);
                if (!id && tail) { id = tail[1]; name = name.replace(/\s*\[#\d{2,3}\]\s*$/, '').trim(); }
                const cost = parseInt(m[3], 10) || 0;
                const action = (m[4] || '').trim();
                const date = entry.date || '未知日期';
                const sig = encodeURIComponent(id + '|' + cost + '|' + action + '|' + date);
                if (hiddenSet.has(sig)) continue;
                visibleEntries.push({ id, name, cost, action, date });
            }
        }

        const sections = [];
        if (visibleEntries.length > 0) {
            const lines = visibleEntries.map(e => {
                const idStr = e.id ? '[#' + e.id + ']' : '';
                return e.date + ': ' + idStr + e.name + '(花费' + e.cost + '铜币进行' + e.action + ')';
            });
            sections.push(`[基建修缮记录]\n${lines.join('\n')}`);
        }

        const structure = getInfraStructure();
        const roomItemsMap = getRoomItemsMap();
        const fullInventory = getVars()[CONFIG.varDataKey] || [];
        const roomLines = [];
        for (const floorKey of INFRA_FLOOR_ORDER) {
            const floor = structure[floorKey];
            if (!floor || typeof floor !== 'object') continue;
            for (const [roomId, room] of Object.entries(floor)) {
                const roomKey = getInfraRoomStableKey(floorKey, roomId, room);
                const heldIds = (roomItemsMap[roomKey] || []).slice(0, 4);
                const heldItems = heldIds.map(id => fullInventory.find(item => item.id === id)).filter(Boolean);
                if (heldItems.length === 0) continue;
                const placedText = heldItems.map(item => {
                    const desc = item.desc || item.description || item['描述'] || '';
                    return `${item.name || '未知物品'}${desc ? `（${desc}）` : ''}`;
                }).join('、');
                const baseDesc = String(room.desc || '').trim();
                const descText = (baseDesc ? baseDesc + (/[。！？!?]$/.test(baseDesc) ? '' : '。') : '') + '还放着' + placedText + '。';
                roomLines.push(`- ${room.name || roomId}（${room.purpose || '暂无'}）\n  位置：${room.location || '未知'}\n  描述：${descText}`);
            }
        }
        if (roomLines.length > 0) sections.push(`[房间放置物]\n${roomLines.join('\n')}`);
        if (sections.length > 0) content = `<Tavern_Infrastructure>\n${sections.join('\n')}\n</Tavern_Infrastructure>`;
        if (typeof TavernHelper !== 'undefined') {
            TavernHelper.insertOrAssignVariables({ inventory_ai_view_infra: content }, { type: 'chat' });
        }
        if (typeof uninjectPrompts !== 'undefined') uninjectPrompts([CONFIG.infraPromptId]);
    }

