    function _refreshUIAfterImport() {
        const vars = getVars();
        const inv = vars[CONFIG.varDataKey] || [];
        const achievements = vars[CONFIG.varAchieveKey] || [];
        const staff = vars[CONFIG.varStaffKey] || [];
        const guests = vars[CONFIG.varGuestKey] || [];
        const renoList = vars[CONFIG.varRenoKey] || [];
        const storageList = vars[CONFIG.varStorageKey] || [];
        const staffItemsMap = vars[CONFIG.varStaffItemsKey] || {};
        const roomItemsMap = vars[CONFIG.varRoomItemsKey] || {};
        const slotsData = getPriceSlotsData();
        let allStaffHeldIds = [];
        Object.values(staffItemsMap).forEach(ids => allStaffHeldIds = allStaffHeldIds.concat(ids));
        let allRoomHeldIds = [];
        Object.values(roomItemsMap).forEach(ids => allRoomHeldIds = allRoomHeldIds.concat(ids || []));
        const priceHeldIds = slotsData.filter(s => s.id).map(s => s.id);
        const aiVisibleInventory = inv.filter(item => !storageList.includes(item.id) && !allStaffHeldIds.includes(item.id) && !allRoomHeldIds.includes(item.id) && !priceHeldIds.includes(item.id));
        // 更新计数器
        const hidden = storageList.filter(id => inv.some(i => i.id === id)).length + allStaffHeldIds.length + allRoomHeldIds.length + priceHeldIds.length;
        $('#th-inv-counter').text(`物品:${aiVisibleInventory.length}${hidden > 0 ? `(+${hidden})` : ''}`);
        $('#th-ach-counter').text(`成就:${achievements.length}`);
        // 刷新所有 Prompt
        refreshSystemPrompt(aiVisibleInventory);
        refreshStaffPrompt(staff, inv, staffItemsMap);
        refreshPricePrompt();
        refreshGuestPrompt(guests);
        refreshInfraPrompt(renoList);
        // 保存导入基准检查点，防止后续 performScan 用空聊天记录覆盖数据
        try {
            let _lastMsgId = 0;
            if (typeof getChatMessages !== 'undefined') {
                const _msgs = getChatMessages('0-{{lastMessageId}}');
                if (_msgs && _msgs.length > 0) _lastMsgId = _msgs[_msgs.length - 1].message_id;
            }
            const _dbMap = vars[CONFIG.varMapKey] || {};
            Object.keys(_dbMap).forEach(k => {});  // ensure object
            // 重建 activeGuestBook
            const _guestBook = {};
            (guests || []).forEach(g => { const gid = getGuestGroupID(g); if (gid) _guestBook[gid] = g; });
            // 【v95】导入员工重锚定：来源聊天的 firstMsgId 在新聊天里通常不存在，
            // 若不处理，预载时会被判定"招募楼已删"而丢人。统一锚定到当前最新楼层。
            const _staffSeen = {};
            const _rebasedStaffMap = {};
            (staff || []).forEach(s => {
                const n = s['姓名'] || s['Name'] || s['name'];
                if (!n) return;
                _staffSeen[n] = _lastMsgId;
                _rebasedStaffMap[n] = { firstMsgId: _lastMsgId, data: s };
            });
            // 用重锚定后的映射覆盖导入进来的（旧 msgId）映射，保证员工不丢
            TavernHelper.insertOrAssignVariables({ [CONFIG.varStaffMapKey]: _rebasedStaffMap }, { type: 'chat' });
            // 独立存储导入基准，clearCheckpoint() 不会影响这个变量
            const _importBase = {
                importedAtMsgId: _lastMsgId,  // 【修复】记录导入时刻的消息位置，全量扫描据此跳过旧消息
                maxId: vars[CONFIG.varMaxIdKey] || 0,
                dbMap: _dbMap,
                inventory: inv,
                achievements: achievements,
                staff: staff,
                activeGuestBook: _guestBook,
                renovationList: renoList
            };
            TavernHelper.insertOrAssignVariables({ [CONFIG.varImportBaseKey]: _importBase }, { type: 'chat' });
            // 同时把检查点指向当前楼层，让 generation_started 走增量扫描
            saveCheckpoint({ message_id: _lastMsgId, maxId: _importBase.maxId, dbMap: _dbMap, inventory: inv, achievements: achievements, staff: staff, staffSeen: _staffSeen, activeGuestBook: _guestBook, renovationList: renoList, worldDate: '' });
        } catch(e) { console.error('import checkpoint save failed', e); }
        // 标脏所有 Tab，切换时重新渲染
        ['inventory', 'staff', 'achievement', 'price', 'infra'].forEach(t => dirtyTabs.add(t));
        if (isPanelOpen) renderActiveTab();
        if (isStorageOpen) renderStorageItems();
    }

    function cloneImportValue(value) {
        try { return JSON.parse(JSON.stringify(value)); } catch (e) { return value; }
    }

    function getImportItemIdMax(items, declaredMax) {
        let max = Number(declaredMax) || 0;
        (Array.isArray(items) ? items : []).forEach(item => {
            const n = Number(item && item.id);
            if (Number.isFinite(n)) max = Math.max(max, n);
        });
        return max;
    }

    function remapImportedIdList(ids, idMap) {
        return (Array.isArray(ids) ? ids : []).map(id => idMap[String(id)] || id);
    }

    function mergeImportedIdLists(sourceIds, currentIds, idMap, limit) {
        const merged = [];
        remapImportedIdList(sourceIds, idMap).concat(Array.isArray(currentIds) ? currentIds : []).forEach(id => {
            if (id == null || merged.includes(id)) return;
            merged.push(id);
        });
        return typeof limit === 'number' ? merged.slice(0, limit) : merged;
    }

    function mergeNamedImportRecords(sourceList, currentList, getKey) {
        const records = new Map();
        (Array.isArray(sourceList) ? sourceList : []).forEach(item => {
            const key = getKey(item);
            if (key) records.set(String(key), cloneImportValue(item));
        });
        (Array.isArray(currentList) ? currentList : []).forEach(item => {
            const key = getKey(item);
            if (key) records.set(String(key), cloneImportValue(item));
        });
        return Array.from(records.values());
    }

    function mergeImportObjects(source, current) {
        const sourceObj = source && typeof source === 'object' && !Array.isArray(source) ? source : {};
        const currentObj = current && typeof current === 'object' && !Array.isArray(current) ? current : {};
        const result = cloneImportValue(sourceObj);
        Object.entries(currentObj).forEach(([key, value]) => {
            if (value && typeof value === 'object' && !Array.isArray(value) && result[key] && typeof result[key] === 'object' && !Array.isArray(result[key])) {
                result[key] = mergeImportObjects(result[key], value);
            } else if (value !== undefined) {
                result[key] = cloneImportValue(value);
            }
        });
        return result;
    }

    function mergeUniqueImportEntries(sourceList, currentList) {
        const seen = new Set();
        const result = [];
        (Array.isArray(sourceList) ? sourceList : []).concat(Array.isArray(currentList) ? currentList : []).forEach(entry => {
            const copy = cloneImportValue(entry);
            let key = '';
            try { key = JSON.stringify(copy); } catch (e) { key = String(copy); }
            if (seen.has(key)) return;
            seen.add(key);
            result.push(copy);
        });
        return result;
    }

    // Message IDs only have meaning inside their own chat. Preserve the current chat map,
    // while imported inventory becomes part of the durable import baseline.
    function mergeImportedData(source, current) {
        const merged = {};
        const sourceInventory = Array.isArray(source[CONFIG.varDataKey]) ? source[CONFIG.varDataKey] : [];
        const currentInventory = Array.isArray(current[CONFIG.varDataKey]) ? current[CONFIG.varDataKey] : [];
        let nextId = Math.max(
            getImportItemIdMax(sourceInventory, source[CONFIG.varMaxIdKey]),
            getImportItemIdMax(currentInventory, current[CONFIG.varMaxIdKey])
        );
        const occupiedIds = new Set(currentInventory.map(item => String(item && item.id || '')).filter(Boolean));
        const sourceSeenIds = new Set();
        const idMap = {};
        const remappedSourceInventory = sourceInventory.map(rawItem => {
            const item = cloneImportValue(rawItem) || {};
            const oldId = String(item.id == null ? '' : item.id);
            let newId = oldId;
            if (!newId || occupiedIds.has(newId) || sourceSeenIds.has(newId)) newId = String(++nextId).padStart(3, '0');
            item.id = newId;
            if (oldId && !idMap[oldId]) idMap[oldId] = newId;
            occupiedIds.add(newId);
            sourceSeenIds.add(newId);
            return item;
        });

        merged[CONFIG.varDataKey] = remappedSourceInventory.concat(cloneImportValue(currentInventory));
        merged[CONFIG.varMapKey] = cloneImportValue(current[CONFIG.varMapKey] || {});
        merged[CONFIG.varMaxIdKey] = nextId;
        merged[CONFIG.varAchieveKey] = mergeNamedImportRecords(source[CONFIG.varAchieveKey], current[CONFIG.varAchieveKey], item => item && item.name);
        merged[CONFIG.varGuestKey] = mergeNamedImportRecords(source[CONFIG.varGuestKey], current[CONFIG.varGuestKey], item => getGuestGroupID(item));
        merged[CONFIG.varRenoKey] = mergeUniqueImportEntries(source[CONFIG.varRenoKey], current[CONFIG.varRenoKey]);
        merged[CONFIG.varRenoHiddenKey] = mergeUniqueImportEntries(source[CONFIG.varRenoHiddenKey], current[CONFIG.varRenoHiddenKey]);
        merged[CONFIG.varStaffKey] = mergeNamedImportRecords(source[CONFIG.varStaffKey], current[CONFIG.varStaffKey], item => item && (item['\u59d3\u540d'] || item.Name || item.name));
        merged[CONFIG.varStaffNotesKey] = mergeImportObjects(source[CONFIG.varStaffNotesKey], current[CONFIG.varStaffNotesKey]);
        merged[CONFIG.varTavernStructureKey] = mergeImportObjects(source[CONFIG.varTavernStructureKey], current[CONFIG.varTavernStructureKey]);
        merged.inventory_evolution_list = mergeUniqueImportEntries(source.inventory_evolution_list, current.inventory_evolution_list);

        merged[CONFIG.varStorageKey] = mergeImportedIdLists(source[CONFIG.varStorageKey], current[CONFIG.varStorageKey], idMap, null);

        const sourceStaffItems = source[CONFIG.varStaffItemsKey] || {};
        const currentStaffItems = current[CONFIG.varStaffItemsKey] || {};
        const mergedStaffItems = {};
        Object.keys(sourceStaffItems).forEach(name => { mergedStaffItems[name] = remapImportedIdList(sourceStaffItems[name], idMap); });
        Object.keys(currentStaffItems).forEach(name => { mergedStaffItems[name] = mergeImportedIdLists(mergedStaffItems[name], currentStaffItems[name], {}, 2); });
        merged[CONFIG.varStaffItemsKey] = mergedStaffItems;

        const sourceRoomItems = source[CONFIG.varRoomItemsKey] || {};
        const currentRoomItems = current[CONFIG.varRoomItemsKey] || {};
        const mergedRoomItems = {};
        Object.keys(sourceRoomItems).forEach(key => { mergedRoomItems[key] = remapImportedIdList(sourceRoomItems[key], idMap).slice(0, 4); });
        Object.keys(currentRoomItems).forEach(key => { mergedRoomItems[key] = mergeImportedIdLists(mergedRoomItems[key], currentRoomItems[key], {}, 4); });
        merged[CONFIG.varRoomItemsKey] = mergedRoomItems;

        const sourceSlots = Array.isArray(source[CONFIG.varPriceSlotsKey]) ? source[CONFIG.varPriceSlotsKey] : [];
        const currentSlots = Array.isArray(current[CONFIG.varPriceSlotsKey]) ? current[CONFIG.varPriceSlotsKey] : [];
        merged[CONFIG.varPriceSlotsKey] = Array.from({ length: Math.max(sourceSlots.length, currentSlots.length) }, (_, index) => {
            const oldSlot = cloneImportValue(sourceSlots[index] || {});
            if (oldSlot.id != null) oldSlot.id = idMap[String(oldSlot.id)] || oldSlot.id;
            const liveSlot = cloneImportValue(currentSlots[index] || {});
            return liveSlot.id ? liveSlot : (oldSlot.id ? oldSlot : (Object.keys(liveSlot).length ? liveSlot : oldSlot));
        });

        const sourcePrice = Array.isArray(source[CONFIG.varPriceKey]) ? source[CONFIG.varPriceKey] : [];
        const currentPrice = Array.isArray(current[CONFIG.varPriceKey]) ? current[CONFIG.varPriceKey] : [];
        merged[CONFIG.varPriceKey] = mergeNamedImportRecords(sourcePrice, currentPrice, row => row && (row.name ? `name:${row.name}` : 'note'));
        const sourceShelfMemory = cloneImportValue(source[CONFIG.varShelfMemoryKey] || {});
        const remappedShelfMemory = {};
        Object.entries(sourceShelfMemory).forEach(([id, value]) => { remappedShelfMemory[idMap[String(id)] || id] = value; });
        merged[CONFIG.varShelfMemoryKey] = mergeImportObjects(remappedShelfMemory, current[CONFIG.varShelfMemoryKey]);
        merged[CONFIG.varNoticeKey] = current[CONFIG.varNoticeKey] || source[CONFIG.varNoticeKey] || '';
        return merged;
    }

    function importAllData(importMode) {
        const isMerge = importMode === 'merge';
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = '.json,application/json';
        input.onchange = function(e) {
            const file = e.target.files[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = function(evt) {
                try {
                    const obj = JSON.parse(evt.target.result);
                    if (!obj.version) { alert('\u6587\u4ef6\u683c\u5f0f\u4e0d\u6b63\u786e\uff0c\u65e0\u6cd5\u5bfc\u5165\u3002'); return; }
                    const confirmText = isMerge
                        ? '\u5408\u5e76\u4f1a\u4fdd\u7559\u5f53\u524d\u804a\u5929\u5df2\u6709\u7684\u6570\u636e\uff0c\u5e76\u52a0\u5165\u65e7\u5907\u4efd\u4e2d\u7684\u7269\u54c1\u3001\u5458\u5de5\u3001\u6210\u5c31\u7b49\u5185\u5bb9\u3002\u82e5\u540c\u4e00\u8bb0\u5f55\u5728\u4e24\u8fb9\u90fd\u5b58\u5728\uff0c\u5c06\u4f18\u5148\u4fdd\u7559\u5f53\u524d\u804a\u5929\u7248\u672c\u3002\u786e\u5b9a\u5417\uff1f'
                        : '\u5bfc\u5165\u540e\u5f53\u524d\u5b58\u6863\u7684\u6240\u6709\u7269\u54c1/\u6210\u5c31/\u5458\u5de5\u6570\u636e\u5c06\u88ab\u8986\u76d6\uff0c\u786e\u5b9a\u5417\uff1f';
                    if (!confirm(confirmText)) return;
                    flushPriceSave();
                    let toImport = isMerge ? mergeImportedData(obj, getVars()) : cloneImportValue(obj);
                    delete toImport.version;
                    delete toImport.timestamp;
                    delete toImport[CONFIG.varCheckpointKey];
                    delete toImport[CONFIG.varImportBaseKey];
                    if (typeof TavernHelper !== 'undefined') TavernHelper.insertOrAssignVariables(toImport, { type: 'chat' });
                    if (window.toastr) toastr.success(isMerge ? '\u65e7\u5907\u4efd\u5df2\u5408\u5e76\uff0c\u6b63\u5728\u5237\u65b0\u2026' : '\u6570\u636e\u5df2\u5bfc\u5165\uff0c\u6b63\u5728\u5237\u65b0\u2026', '\u7cfb\u7edf');
                    _refreshUIAfterImport();
                } catch(err) { alert('\u8bfb\u53d6\u6587\u4ef6\u5931\u8d25\uff1a' + err.message); }
            };
            reader.readAsText(file, 'utf-8');
        };
        document.body.appendChild(input);
        input.click();
        document.body.removeChild(input);
    }
    function scheduleScan(mode) { 
        if (debounceTimer) clearTimeout(debounceTimer); 
        debounceTimer = setTimeout(() => performScan(mode || 'full'), CONFIG.debounceDelay); 
    }

