                closeDetailPopup();
            });
            $btnArea.append($returnBtn);
        } else if (sourceType === 'from_room') {
            // 从房间槽查看：添加"收回杂物间"按钮
            const $returnBtn = $(`<div style="cursor: pointer; font-size: 16px; opacity: 0.6;" title="收回杂物间">🏚️</div>`);
            $returnBtn.on('click', (e) => {
                e.stopPropagation();
                moveRoomItemToStorage(item.id, staffName);
                closeDetailPopup();
            });
            $btnArea.append($returnBtn);
        }

        $popup.find('.close-btn').off('click').on('click', (e) => { e.stopPropagation(); closeDetailPopup(); });
        parseEmoji($popup[0]);

        // 位置：若用户本次拖拽过窗口，沿用记忆的绝对位置；否则智能计算，避免遮挡操作区域
        if (detailPopupCustomPos) {
            $popup.css({ left: detailPopupCustomPos.left + 'px', top: detailPopupCustomPos.top + 'px', transform: 'none' });
        } else if (sourceType === 'from_price') {
            // 货架物品：详情页始终放在上方（因为点击后杂物间会随之弹出在下方）
            $popup.css('top', '20%');
        } else if ($panel.length && $panel.is(':visible')) {
            if (isStorageOpen) {
