                            metaLine = `<div class="th-infra-evo-meta th-infra-evo-ready">有新事件待触发</div>`;
                            badge = `<span class="th-infra-evo-action trigger" title="点击触发新剧情">❗</span>`;
                        } else {
                            metaLine = `<div class="th-infra-evo-meta">距下次事件还需 ${e.floorsToAction} 楼</div>`;
                        }
                    } else {
                        // vanish 类型到最后阶段：很快就消失
                        metaLine = `<div class="th-infra-evo-meta th-infra-evo-final">即将消散</div>`;
                    }
                    return `<div class="th-infra-evo-item" data-evo-id="${e.id}" data-evo-name="${safeName}"><div class="th-infra-evo-box"><span class="th-infra-evo-emoji">${cur.emoji || '📦'}</span></div><div class="th-infra-evo-text"><div class="th-infra-evo-state">${cur.state || ''}</div>${metaLine}</div>${badge}<span class="th-infra-evo-del" title="移除此演化物品">✕</span></div>`;
                }).join('') + `</div>`
