                    <span class="th-infra-room-namelabel">${nameText}</span>
                    <span class="th-infra-room-edit-btn" title="编辑房间名和用途">✏️</span>
                </div>
                <div class="th-infra-room-meta">用途：<span class="th-infra-room-purpose">${purposeText}</span></div>
                ${roomSlotsAreaHtml}
                ${buffsHtml}
                <div class="th-infra-room-desc">${room.desc || ''}</div>
                ${evosHtml}
            `;
        }

        $list.html(`
            <div class="th-infra-layout">
                <div class="th-infra-sidebar">${sidebarHtml}</div>
                <div class="th-infra-main">
                    <div class="th-infra-roomtabs">${tabsHtml}</div>
                    <div class="th-infra-detail">${detailHtml}</div>
                </div>
            </div>
        `);

        $list.find('.th-infra-floor-btn').on('click', function () {
