            infraState.floor = $(this).data('floor');
            infraState.roomId = null;
            infraState.roomTabScroll = 0; // 切换楼层：房间 tab 栏回到开头
            renderInfraBoard();
        });
        $list.find('.th-infra-room-tab').on('click', function () {
            infraState.roomId = $(this).data('room');
            renderInfraBoard();
        });

        // 桌面端：在房间 tab 行滚动鼠标滚轮 → 横向滚动
        $list.find('.th-infra-roomtabs').each(function () {
            this.addEventListener('wheel', function (e) {
                if (e.deltaY === 0) return;
                e.preventDefault();
                this.scrollLeft += e.deltaY;
            }, { passive: false });
            // 恢复上次的横向滚动位置，避免点击 tab 重渲染后滚回开头
            this.scrollLeft = infraState.roomTabScroll || 0;
            // 持续记录滚动位置，供下次重渲染后恢复
            this.addEventListener('scroll', function () { infraState.roomTabScroll = this.scrollLeft; }, { passive: true });
        });

        $list.find('.th-infra-room-edit-btn').on('click', function (e) {
            e.stopPropagation();
            openInfraRoomEditPopup();
        });

        $list.find('.th-infra-room-slot.filled').on('click', function () {
            const itemId = $(this).data('item-id');
            const roomKey = $(this).data('room-key');
            const item = (getVars()[CONFIG.varDataKey] || []).find(it => it.id === String(itemId));
            if (item) showItemDetail(item, false, 'from_room', roomKey);
            toggleStoragePopup();
        });

        $list.find('.th-infra-room-slot:not(.filled)').on('click', function () {
            const $popup = $('#th-detail-popup-ui');
            const pendingItemId = $popup.data('pending-room-item');
            if (pendingItemId) {
                const roomKey = $(this).data('room-key');
                moveStorageToRoom(pendingItemId, roomKey);
                $popup.removeData('pending-room-item');
                $('.th-infra-room-slot').removeClass('th-assign-hint');
                $('.th-infra-room-slots').removeClass('assigning');
                closeDetailPopup();
            } else {
                toggleStoragePopup();
            }
        });

        $list.find('.th-infra-room-slot.filled').each(function () {
            const itemId = $(this).data('item-id');
            const roomKey = $(this).data('room-key');
            const item = (getVars()[CONFIG.varDataKey] || []).find(it => it.id === String(itemId));
            if (item) bindDragEvents($(this), item, 'from_room', roomKey);
        });

        // 演化条目删除：✕ → 确认 → removeEvolution
        $list.find('.th-infra-evo-del').on('click', function (e) {
            e.stopPropagation();
            const $item = $(this).closest('.th-infra-evo-item');
            const evoId = $item.attr('data-evo-id');
            const evoName = $item.attr('data-evo-name') || '该演化物品';
            if (!evoId) return;
            if (!confirm(`确认移除「${evoName}」？\n（演化进度无法恢复）`)) return;
            try {
                const fn = window.parent && window.parent.removeEvolution;
                if (typeof fn === 'function') {
                    fn(evoId);
                    renderInfraBoard();
                } else { alert('未检测到 removeEvolution 接口，请确认「酒馆结构」副脚本已加载'); }
            } catch (err) { console.error('[infra] removeEvolution failed', err); alert('移除失败：' + (err && err.message ? err.message : err)); }
        });

        // 演化 ! 周期收取（periodic）：点击 → 确认 → collectPeriodicEvolution + 隐式 CMD:ADD
        $list.find('.th-infra-evo-action.periodic').on('click', async function (e) {
            e.stopPropagation();
            const $item = $(this).closest('.th-infra-evo-item');
            const evoId = $item.attr('data-evo-id');
            const evoName = $item.attr('data-evo-name') || '演化物品';
            if (!evoId) return;
            if (!confirm(`从「${evoName}」收取一次产物？`)) return;
            let item = null;
            try {
                const fn = window.parent && window.parent.collectPeriodicEvolution;
                if (typeof fn === 'function') item = fn(evoId);
            } catch (err) { console.error('[infra] collect failed', err); }
            if (!item) { alert('未能收取（也许还没准备好）'); return; }
            const safe = v => String(v || '').replace(/\|/g, '／');
            const cmd = `<Item>\nCMD:ADD | ${safe(item.icon)} | ${safe(item.name)}${item.desc ? ' | ' + safe(item.desc) : ''}\n</Item>`;
            try { await appendUpdateToChat(cmd, `收获 ${item.name}`); } catch (err) { console.error('[infra] CMD:ADD failed', err); alert('写入失败：' + err.message); }
            renderInfraBoard();
        });

        // 演化 ! 事件触发（trigger）：点击 → 确认 → markTriggerFired（消耗 badge）
        // → 把事件作为一条 depth0 的一次性 system 注入排队，等下一次正常生成时自然融入当前正文。
        // 【改造】不再新建楼层、不再自行调用 generate：
        //   旧做法先消耗事件再 generate，若 generate 返回空/非字符串则不建楼却仍报成功，
        //   造成"提示成功、实际没触发、事件被白白消耗"。现在改为"排队注入 + 无痕融入"。
        $list.find('.th-infra-evo-action.trigger').on('click', function (e) {
            e.stopPropagation();
            const $btn = $(this);
            const $item = $btn.closest('.th-infra-evo-item');
            const evoId = $item.attr('data-evo-id');
            const evoName = $item.attr('data-evo-name') || '演化物品';
            if (!evoId) return;
            if (!confirm(`触发「${evoName}」的新事件？\n下一次 AI 生成时，会把这段剧情自然融入正文（不新建楼层）。`)) return;
            let payload = null;
            try {
                const fn = window.parent && window.parent.markTriggerFired;
                if (typeof fn === 'function') payload = fn(evoId);
            } catch (err) { console.error('[infra] markTriggerFired failed', err); }
            if (!payload || !payload.keyword) { alert('未能触发（也许还没准备好）'); return; }
            try {
                const injectContent = `（请将这个剧情自然地融入当前正文：${payload.keyword}）`;
                // 先撤旧的（若上一条还没被消费，保证只保留最新一条），再注入新的
                if (typeof uninjectPrompts !== 'undefined') uninjectPrompts([CONFIG.evoTriggerPromptId]);
                if (typeof injectPrompts !== 'undefined') {
                    injectPrompts([{ id: CONFIG.evoTriggerPromptId, position: 'in_chat', depth: 0, role: 'system', content: injectContent, should_scan: false }]);
                    pendingEvoTriggerInject = true; // 交给 generation_started 在下一次生成开始时撤销（只生效一次）
                    if (window.toastr) toastr.success('事件已排队，下次生成时融入正文');
                } else {
                    // 极少数环境没有 injectPrompts：明确告知未生效，避免虚假成功提示
                    alert('当前环境不支持注入，事件未能排队');
                }
            } catch (err) {
                console.error('[infra] evo trigger inject failed', err);
                alert('排队失败：' + (err && err.message ? err.message : err));
            } finally {
                renderInfraBoard();
            }
        });

        parseEmoji($list[0]);
    }

