    function closeImportHelpHint() {
        if (importHelpDismissTimer) {
            clearTimeout(importHelpDismissTimer);
            importHelpDismissTimer = null;
        }
        $('#th-import-help-tooltip').remove();
        $(document).off('.thImportHelpOutside');
    }

    function showImportHelpHint(text, point, owner) {
        closeImportHelpHint();
        if (!text) return;
        const x = Number.isFinite(point && point.x) ? point.x : window.innerWidth / 2;
        const y = Number.isFinite(point && point.y) ? point.y : window.innerHeight / 2;
        const $tooltip = $('<div id="th-import-help-tooltip" role="tooltip"></div>').text(text).appendTo('body');
        $tooltip.data('th-owner', owner || null);
        if (isNightMode) $tooltip.addClass('th-night-hint');
        const tipWidth = $tooltip.outerWidth();
        const tipHeight = $tooltip.outerHeight();
        const left = Math.max(12, Math.min(window.innerWidth - tipWidth - 12, x + 12));
        const top = y + tipHeight + 12 <= window.innerHeight ? y + 12 : Math.max(12, y - tipHeight - 12);
        $tooltip.css({ left: `${left}px`, top: `${top}px` });
        requestAnimationFrame(() => $tooltip.addClass('visible'));
        // Touch browsers do not always deliver a useful outside pointer event inside the panel iframe.
        // The timeout guarantees this small hint cannot remain on screen indefinitely.
        importHelpDismissTimer = setTimeout(closeImportHelpHint, 4800);
        setTimeout(() => {
            $(document).off('.thImportHelpOutside').on('pointerdown.thImportHelpOutside touchstart.thImportHelpOutside click.thImportHelpOutside', event => {
                if (!$(event.target).closest('.th-import-help, #th-import-help-tooltip').length) closeImportHelpHint();
            });
        }, 0);
    }

    function bindImportHelpHints() {
        $('.th-import-help').off('.thImportHelp').on('click.thImportHelp', function(event) {
            event.preventDefault();
            event.stopPropagation();
            const $tooltip = $('#th-import-help-tooltip');
            if ($tooltip.length && $tooltip.data('th-owner') === this) {
                closeImportHelpHint();
                return;
            }
            const original = event.originalEvent || event;
            const touch = (original.changedTouches && original.changedTouches[0]) || (original.touches && original.touches[0]);
            const point = touch ? { x: touch.clientX, y: touch.clientY } : { x: event.clientX, y: event.clientY };
            showImportHelpHint($(this).attr('data-th-hint') || '', point, this);
        }).on('keydown.thImportHelp', function(event) {
            if (event.key !== 'Enter' && event.key !== ' ') return;
            event.preventDefault();
            const $tooltip = $('#th-import-help-tooltip');
            if ($tooltip.length && $tooltip.data('th-owner') === this) { closeImportHelpHint(); return; }
            const rect = this.getBoundingClientRect();
            showImportHelpHint($(this).attr('data-th-hint') || '', { x: rect.left + rect.width / 2, y: rect.bottom }, this);
        });
    }
