    function bindDetailPopupDrag() {
        const $popup = $('#th-detail-popup-ui');
        const $handle = $popup; // 整个弹窗都是拖拽热区（操作按钮区除外）
        const handleEl = $popup[0];
        if (!handleEl) return;

        // 拖拽热区判定：除"编辑/删除/关闭/上架"等操作按钮外，弹窗任意位置均可拖动。
        // 这样大大扩展了可拖拽范围，同时不影响那些按钮的点击。
        function isDraggableTarget(target) {
            return $(target).closest('.btn-area, .close-btn').length === 0;
        }

        function snapToReal() {
            const r = handleEl.getBoundingClientRect();
            $popup.css({ left: r.left + 'px', top: r.top + 'px', transform: 'none' });
            return { left: r.left, top: r.top };
        }

        // 拖拽结束后记录位置，使点击其它物品时窗口停留在这里（详见 detailPopupCustomPos）
        function rememberPos() {
            const r = handleEl.getBoundingClientRect();
            detailPopupCustomPos = { left: r.left, top: r.top };
        }

        // ── 触控拖拽 ──
        let touchDragging = false;
        let startX, startY, initL = undefined, initT;

        $handle.on('touchstart', e => {
            const t = e.touches[0];
            if (!isDraggableTarget(e.target)) return;
            touchDragging = false;
            startX = t.clientX; startY = t.clientY;
            const pos = snapToReal();
            initL = pos.left; initT = pos.top;
        });
        $handle.on('touchmove', e => {
            // startX/startY 只在 touchstart 命中拖拽热区时才被赋值，否则 initL 为 undefined，不会移动
            if (initL === undefined) return;
            const t = e.touches[0];
            const moveX = t.clientX - startX, moveY = t.clientY - startY;
            if (Math.abs(moveX) > 5 || Math.abs(moveY) > 5) {
                touchDragging = true;
                $popup.css({ left: initL + moveX + 'px', top: initT + moveY + 'px' });
            }
            if (touchDragging) e.preventDefault();
        });
        $handle.on('touchend touchcancel', () => {
            if (touchDragging) rememberPos();
            touchDragging = false; initL = undefined;
        });

        // ── 鼠标拖拽 ──
        let mouseDragging = false, isMouseDown = false;

        handleEl.addEventListener('pointerdown', e => {
            if (e.pointerType !== 'mouse' || e.button !== 0) return;
            if (!isDraggableTarget(e.target)) return;
            isMouseDown = true;
            mouseDragging = false;
            startX = e.clientX; startY = e.clientY;
            const pos = snapToReal();
            initL = pos.left; initT = pos.top;
            try { handleEl.setPointerCapture(e.pointerId); } catch(err) {}
            e.preventDefault();
        });
        handleEl.addEventListener('pointermove', e => {
            if (e.pointerType !== 'mouse' || !isMouseDown) return;
            const moveX = e.clientX - startX, moveY = e.clientY - startY;
            if (!mouseDragging && (Math.abs(moveX) > 5 || Math.abs(moveY) > 5)) {
                mouseDragging = true;
                handleEl.style.cursor = 'grabbing';
            }
            if (mouseDragging) {
                $popup.css({ left: initL + moveX + 'px', top: initT + moveY + 'px' });
            }
        });
        handleEl.addEventListener('pointerup', e => {
            if (e.pointerType !== 'mouse') return;
            if (mouseDragging) rememberPos();
            isMouseDown = false;
            mouseDragging = false;
            handleEl.style.cursor = '';
        });
        handleEl.addEventListener('pointercancel', e => {
            if (e.pointerType !== 'mouse') return;
            isMouseDown = false;
            mouseDragging = false;
        });
    }

    function bindEvents() {
        if (typeof tavern_events === 'undefined') return;
        // 新消息到来：使用增量扫描（只扫新楼层，速度快）
        eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, () => scheduleScan('incremental'));
        // 删楼、回滚、修改楼层：先作废检查点，再全量重扫（防止旧快照污染增量结果）
        [tavern_events.MESSAGE_DELETED, tavern_events.MESSAGE_SWIPED, tavern_events.MESSAGE_UPDATED]
            .forEach(e => eventOn(e, () => { clearCheckpoint(); scheduleScan('full'); }));
        // 生成开始：只标记"生成中"。
        // 【修复 物品消失 Bug】此前这里会 clearTimeout 抢占掉 swipe/重roll 刚排好的全量扫，
        // 并在没有检查点时立刻同步 performScan('full')——但此刻最新楼还在生成、文本为空，
        // 全量扫会据此存下一个"缺物品"的检查点（恰好落在 25 的倍数楼层附近），
        // 之后增量扫都基于这个坏检查点，物品就此消失，直到删楼强制全量重扫才回来。
        // 现在生成期间不动检查点：基线建立交给 generation_ended / 删改楼 / 增量流自然完成。
        eventOn('generation_started', () => {
            isGenerating = true;
            // 演化「手动触发事件」一次性注入：本次生成已把它带进上下文，生成一开始即视为消费，撤销之，保证只生效一次。
            if (pendingEvoTriggerInject) {
                pendingEvoTriggerInject = false;
                try { if (typeof uninjectPrompts !== 'undefined') uninjectPrompts([CONFIG.evoTriggerPromptId]); } catch (err) { console.error('[infra] uninject evo trigger failed', err); }
            }
        });
        // 生成结束：解除标记，并按需建立基线（此时最新楼文本已完整）。
        eventOn('generation_ended', () => { isGenerating = false; const _cp = getCheckpoint(); if (_cp) { scheduleScan('incremental'); } else { scheduleScan('full'); } });
        // 生成被中断：仅解除标记，避免 isGenerating 卡在 true 而长期抑制检查点。
        if (typeof tavern_events !== 'undefined' && tavern_events.GENERATION_STOPPED) {
            eventOn(tavern_events.GENERATION_STOPPED, () => { isGenerating = false; });
        }
        eventOn(tavern_events.CHAT_CHANGED, () => {
    isGenerating = false; // 切换聊天：复位生成标记，防止残留状态抑制新聊天的检查点
    // 切换聊天：撤销未消费的演化触发注入，避免它泄漏到别的聊天里
    if (pendingEvoTriggerInject) { pendingEvoTriggerInject = false; try { if (typeof uninjectPrompts !== 'undefined') uninjectPrompts([CONFIG.evoTriggerPromptId]); } catch (e) {} }
    $('[id^="th-fixed"]').remove();
    $('#' + CONFIG.domBallId).remove();
    $('#th-detail-popup-ui').remove();
    removeInfraRoomEditPopup();
    $('.th-drag-helper').remove();
    isPanelOpen = false;
    isStorageOpen = false;
    isBallVisible = true;   // 重置状态
    detailPopupCustomPos = null; // 切换聊天，遗忘记忆的拖拽位置
    setTimeout(createUI, 100); // 稍作延迟，等新角色卡加载完再重建悬浮球
        });
        if (typeof getButtonEvent !== 'undefined') { 
            const btnEvent = getButtonEvent(CONFIG.toggleButtonName); 
            eventOn(btnEvent, () => { toggleBallVisibility(); }); 
        }
    }

    function bindStorageDragEvents() {
        const $storage = $('#' + CONFIG.domStorageId);
        const $handle  = $('#th-storage-header');
        const handleEl = $handle[0];
        if (!handleEl) return;

        let touchDragging = false;
        let mouseDragging = false, isMouseDown = false;
        let startX, startY, initL, initT;

        function snapToReal() {
            const r = $storage[0].getBoundingClientRect();
            $storage.css({ left: r.left + 'px', top: r.top + 'px', transform: 'none' });
            return { left: r.left, top: r.top };
        }

        $handle.on('touchstart', e => {
            touchDragging = false;
            const t = e.touches[0];
            startX = t.clientX; startY = t.clientY;
            const pos = snapToReal();
            initL = pos.left; initT = pos.top;
        });
        $handle.on('touchmove', e => {
            const t = e.touches[0];
            const moveX = t.clientX - startX, moveY = t.clientY - startY;
            if (Math.abs(moveX) > 5 || Math.abs(moveY) > 5) {
                touchDragging = true;
                $storage.css({ left: initL + moveX + 'px', top: initT + moveY + 'px' });
            }
            e.preventDefault();
        });
        $handle.on('touchend touchcancel', () => { touchDragging = false; initL = undefined; });

        handleEl.addEventListener('pointerdown', e => {
            if (e.pointerType !== 'mouse' || e.button !== 0) return;
            isMouseDown = true;
            mouseDragging = false;
            startX = e.clientX; startY = e.clientY;
            const pos = snapToReal();
            initL = pos.left; initT = pos.top;
            try { handleEl.setPointerCapture(e.pointerId); } catch(err) {}
            e.preventDefault();
        });
        handleEl.addEventListener('pointermove', e => {
            if (e.pointerType !== 'mouse' || !isMouseDown) return;
            const moveX = e.clientX - startX, moveY = e.clientY - startY;
            if (!mouseDragging && (Math.abs(moveX) > 5 || Math.abs(moveY) > 5)) {
                mouseDragging = true;
                handleEl.style.cursor = 'grabbing';
            }
            if (mouseDragging) {
                $storage.css({ left: initL + moveX + 'px', top: initT + moveY + 'px' });
            }
        });
        handleEl.addEventListener('pointerup', e => {
            if (e.pointerType !== 'mouse') return;
            isMouseDown = false;
            mouseDragging = false;
            handleEl.style.cursor = 'grab';
        });
        handleEl.addEventListener('pointercancel', e => {
            if (e.pointerType !== 'mouse') return;
            isMouseDown = false;
            mouseDragging = false;
        });
    }

    function bindBallEvents() {
        const $ball = $('#' + CONFIG.domBallId);
        const ballEl = $ball[0];
        let touchDragging = false;
        let mouseDragging = false, isMouseDown = false;
        let startX, startY, initL, initT;

        // ===== 触控拖动（手机端，原有逻辑不变）=====
        $ball.on('touchstart', e => {
            touchDragging = false;
            const t = e.touches[0];
            startX = t.clientX; startY = t.clientY;
            const r = ballEl.getBoundingClientRect();
            initL = r.left; initT = r.top;
        });
        $ball.on('touchmove', e => {
            const t = e.touches[0];
            const moveX = t.clientX - startX, moveY = t.clientY - startY;
            if (Math.abs(moveX) > 10 || Math.abs(moveY) > 10) {
                touchDragging = true;
                $ball.css({ left: initL + moveX + 'px', top: initT + moveY + 'px', transform: 'none' });
            }
            e.preventDefault();
        });
        $ball.on('touchend', () => {
            if (!touchDragging) togglePanel();
            touchDragging = false;
        });

        // ===== 鼠标拖动（电脑端）=====
        ballEl.addEventListener('pointerdown', e => {
            if (e.pointerType !== 'mouse' || e.button !== 0) return;
            isMouseDown = true;
            mouseDragging = false;
            startX = e.clientX; startY = e.clientY;
            const r = ballEl.getBoundingClientRect();
            initL = r.left; initT = r.top;
            try { ballEl.setPointerCapture(e.pointerId); } catch(err) {}
            e.preventDefault();
        });
        ballEl.addEventListener('pointermove', e => {
            if (e.pointerType !== 'mouse' || !isMouseDown) return;
            const moveX = e.clientX - startX, moveY = e.clientY - startY;
            if (!mouseDragging && (Math.abs(moveX) > 5 || Math.abs(moveY) > 5)) {
                mouseDragging = true;
                ballEl.style.cursor = 'grabbing';
            }
            if (mouseDragging) {
                ballEl.style.left = (initL + moveX) + 'px';
                ballEl.style.top  = (initT + moveY) + 'px';
                ballEl.style.transform = 'none';
            }
        });
        ballEl.addEventListener('pointerup', e => {
            if (e.pointerType !== 'mouse') return;
            if (!mouseDragging) togglePanel();
            isMouseDown = false;
            mouseDragging = false;
            ballEl.style.cursor = 'pointer';
        });
        ballEl.addEventListener('pointercancel', e => {
            if (e.pointerType !== 'mouse') return;
            isMouseDown = false;
            mouseDragging = false;
        });
    }

    // 【修改】拖拽逻辑增加对价目槽的支持
    function bindDragEvents($el, item, sourceType, staffName = null) {
        let isDragging = false;
        let dragTimer = null;
        let startX, startY;
        let $helper = null;

        // ── 共用：根据当前坐标更新高亮 ──
        function updateHighlight(cx, cy) {
            const $storagePopup = $('#' + CONFIG.domStorageId);
            const $mainPanel = $('#' + CONFIG.domPanelId);
            const $binIcon = $('#th-storage-bin');
            const pos = { clientX: cx, clientY: cy };

            $('.th-staff-slot').removeClass('th-drop-target-active');
            $('.th-price-slot').removeClass('th-drop-target-active');
            $('.th-infra-room-slot').removeClass('th-drop-target-active');
            $storagePopup.removeClass('th-drop-target-active');
            $binIcon.removeClass('th-inv-storage-bin-active');

            if (sourceType === 'from_main' || sourceType === 'from_staff' || sourceType === 'from_room' || sourceType === 'from_price') {
                if ($binIcon.length && $binIcon.is(':visible') && isIntersecting(pos, $binIcon[0])) {
                    $binIcon.addClass('th-inv-storage-bin-active');
                }
            }
            if ($mainPanel.is(':visible')) {
                if ($('#th-list-staff').is(':visible')) {
                    $('.th-staff-slot:not(.filled)').each(function() {
                        if (isIntersecting(pos, this)) $(this).addClass('th-drop-target-active');
                    });
                }
                if ($('#th-list-infra').is(':visible') && sourceType === 'from_storage') {
                    $('.th-infra-room-slots').addClass('assigning');
                    $('.th-infra-room-slot:not(.filled)').each(function() {
                        if (isIntersecting(pos, this)) $(this).addClass('th-drop-target-active');
                    });
                }

                if ($('#th-list-price').is(':visible')) {
                    $('#th-shelf-slots-inner').find('.th-shelf-box').each(function() {
                        if (isIntersecting(pos, this)) {
                            const rect = this.getBoundingClientRect();
                            const isRight = (pos.clientX - rect.left) > rect.width / 2;
                            const boxes = $('#th-shelf-slots-inner').find('.th-shelf-box');
                            const boxIdx = boxes.index(this);
                            const slotIdx = boxIdx * 2 + (isRight ? 1 : 0);
                            $(`.th-price-slot[data-slot-index="${slotIdx}"]`).not('.filled').addClass('th-drop-target-active');
                        }
                    });
                }
            }
        }

        // ── 共用：松手时判断落点并执行操作 ──
        function handleDrop(cx, cy) {
            const pos = { clientX: cx, clientY: cy };
            let handled = false;

            if (sourceType === 'from_main') {
                const $popup = $('#' + CONFIG.domStorageId);
                const $bin = $('#th-storage-bin');
                if (($popup.is(':visible') && isIntersecting(pos, $popup[0])) ||
                    ($bin.is(':visible') && isIntersecting(pos, $bin[0]))) {
                    moveToStorage(item.id); handled = true;
                }
            } else if (sourceType === 'from_staff') {
                const $popup = $('#' + CONFIG.domStorageId);
                if ($popup.is(':visible') && isIntersecting(pos, $popup[0])) {
                    moveStaffToStorage(item.id, staffName); handled = true;
                }
            } else if (sourceType === 'from_room') {
                const $popup = $('#' + CONFIG.domStorageId);
                if ($popup.is(':visible') && isIntersecting(pos, $popup[0])) {
                    moveRoomItemToStorage(item.id, staffName); handled = true;
                }
            }

            if (!handled) {
                if ($('#th-list-staff').is(':visible')) {
                    $('.th-staff-slot:not(.filled)').each(function() {
                        if (isIntersecting(pos, this)) {
                            const sName = $(this).data('staff');
                            if (sourceType === 'from_storage') moveStorageToStaff(item.id, sName);
                            return false;
                        }
                    });
                }
                if ($('#th-list-infra').is(':visible')) {
                    $('.th-infra-room-slot:not(.filled)').each(function() {
                        if (!handled && isIntersecting(pos, this)) {
                            const roomKey = $(this).data('room-key');
                            if (sourceType === 'from_storage') { moveStorageToRoom(item.id, roomKey); handled = true; }
                            return false;
                        }
                    });
                }
                if ($('#th-list-price').is(':visible')) {
                    $('#th-shelf-slots-inner').find('.th-shelf-box').each(function() {
                        if (!handled && isIntersecting(pos, this)) {
                            const rect = this.getBoundingClientRect();
                            const isRight = (pos.clientX - rect.left) > rect.width / 2;
                            const boxes = $('#th-shelf-slots-inner').find('.th-shelf-box');
                            const boxIdx = boxes.index(this);
                            const slotIdx = boxIdx * 2 + (isRight ? 1 : 0);
                            const $slot = $(`.th-price-slot[data-slot-index="${slotIdx}"]`).not('.filled');
                            if ($slot.length) {
                                // from_price 时 staffName 存的是来源槽索引，透传以便清除旧槽
                                const srcSlot = (sourceType === 'from_price') ? staffName : null;
                                moveItemToPriceSlot(item.id, slotIdx, srcSlot);
                                handled = true;
                            }
                        }
                    });
                }
            }
            if (!handled && sourceType === 'from_price') {
                const $storageEl = $('#' + CONFIG.domStorageId);
                if ($storageEl.is(':visible') && isIntersecting(pos, $storageEl[0])) {
                    removeItemFromPriceSlot(staffName); handled = true;
                }
            }
            if (!handled && sourceType === 'from_storage') {
                const $panel = $('#' + CONFIG.domPanelId);
                if ($panel.is(':visible') && isIntersecting(pos, $panel[0])) {
                    retrieveFromStorage(item.id);
                }
            }
        }

        // ── 共用：拖拽结束清理 ──
        function endDrag() {
            $el.css('opacity', '1');
            if ($helper) { $helper.remove(); $helper = null; }
            $('#' + CONFIG.domStorageId).removeClass('th-drop-target-active');
            $('#th-storage-bin').removeClass('th-inv-storage-bin-active');
            $('.th-staff-slot').removeClass('th-drop-target-active');
            $('.th-price-slot').removeClass('th-drop-target-active');
            $('.th-infra-room-slot').removeClass('th-drop-target-active');
            $('.th-infra-room-slots').removeClass('assigning');
            isDragging = false;
        }

        // ── 触控拖拽（手机端，长按200ms触发）──
        $el.on('touchstart', (e) => {
            if(e.touches.length > 1) return;
            $('.th-drag-helper').remove();
            const t = e.touches[0];
            startX = t.clientX; startY = t.clientY;
            dragTimer = setTimeout(() => {
                isDragging = true;
                $helper = $el.clone().addClass('th-drag-helper').appendTo('body');
                $helper.css({ left: startX - 25, top: startY - 25 });
                $el.css('opacity', '0.4');
                if (sourceType === 'from_main' && !isStorageOpen) toggleStoragePopup();
                if (sourceType === 'from_staff' && !isStorageOpen) toggleStoragePopup();
                if (sourceType === 'from_room' && !isStorageOpen) toggleStoragePopup();
                if (sourceType === 'from_storage' && $('#th-list-infra').is(':visible')) $('.th-infra-room-slots').addClass('assigning');
                if (sourceType === 'from_price' && !isStorageOpen) toggleStoragePopup();
            }, 200);
        });

        $el.on('touchmove', (e) => {
            if (!isDragging) { if (dragTimer) { clearTimeout(dragTimer); dragTimer = null; } return; }
            e.preventDefault();
            const t = e.touches[0];
            $helper.css({ left: t.clientX - 25, top: t.clientY - 25 });
            updateHighlight(t.clientX, t.clientY);
        });

        $el.on('touchend touchcancel', (e) => {
            if (dragTimer) clearTimeout(dragTimer);
            if (isDragging) {
                if (e.type === 'touchend') {
                    const t = e.changedTouches[0];
                    handleDrop(t.clientX, t.clientY);
                }
                endDrag();
            }
        });

        // ── 鼠标拖拽（电脑端，直接按住拖动）──
        const el = $el[0];
        let isMouseDown = false, mouseDragging = false;

        el.addEventListener('pointerdown', (e) => {
            if (e.pointerType !== 'mouse' || e.button !== 0) return;
            isMouseDown = true; mouseDragging = false;
            startX = e.clientX; startY = e.clientY;
            try { el.setPointerCapture(e.pointerId); } catch(err) {}
            e.preventDefault();
        });

        el.addEventListener('pointermove', (e) => {
            if (e.pointerType !== 'mouse' || !isMouseDown) return;
            const moveX = e.clientX - startX, moveY = e.clientY - startY;
            if (!mouseDragging && (Math.abs(moveX) > 5 || Math.abs(moveY) > 5)) {
                mouseDragging = true;
                isDragging = true;
                $('.th-drag-helper').remove();
                $helper = $el.clone().addClass('th-drag-helper').appendTo('body');
                $helper.css({ left: e.clientX - 25, top: e.clientY - 25 });
                $el.css('opacity', '0.4');
                if (sourceType === 'from_main' && !isStorageOpen) toggleStoragePopup();
                if (sourceType === 'from_staff' && !isStorageOpen) toggleStoragePopup();
                if (sourceType === 'from_room' && !isStorageOpen) toggleStoragePopup();
                if (sourceType === 'from_storage' && $('#th-list-infra').is(':visible')) $('.th-infra-room-slots').addClass('assigning');
                if (sourceType === 'from_price' && !isStorageOpen) toggleStoragePopup();
            }
            if (mouseDragging) {
                $helper.css({ left: e.clientX - 25, top: e.clientY - 25 });
                updateHighlight(e.clientX, e.clientY);
            }
        });

        el.addEventListener('pointerup', (e) => {
            if (e.pointerType !== 'mouse') return;
            if (mouseDragging) {
                handleDrop(e.clientX, e.clientY);
                endDrag();
            }
            isMouseDown = false; mouseDragging = false;
        });

        el.addEventListener('pointercancel', (e) => {
            if (e.pointerType !== 'mouse') return;
            if (mouseDragging) endDrag();
            isMouseDown = false; mouseDragging = false;
        });
    }

    function isIntersecting(touch, element) {
        const r = element.getBoundingClientRect();
        return touch.clientX >= r.left && touch.clientX <= r.right && 
               touch.clientY >= r.top && touch.clientY <= r.bottom;
    }

    // --- 初始化入口 ---
    function init() {
        if (initRetryCount > 20) {
            if(window.toastr) toastr.warning("脚本依赖项加载超时，部分功能可能不可用");
            return;
        }

        const hasJQuery = !!window.$;
        const hasMsgGetter = (typeof getChatMessages !== 'undefined') || (typeof TavernHelper !== 'undefined');
        // 【修复 切卡悬浮球不消失】也必须等 tavern_events 就绪再 init：
        // 否则 bindEvents() 开头的 `if (typeof tavern_events === 'undefined') return` 会静默早退，
        // CHAT_CHANGED 根本没绑上，切换角色卡时旧悬浮球就永远不会被移除。
        // （eventOn/tavern_events 尚未就绪时先重试等待，就绪后一次性绑好，运行期零开销。）
        const hasEvents = (typeof tavern_events !== 'undefined') && (typeof eventOn !== 'undefined');

        if (!hasJQuery || !hasMsgGetter || !hasEvents) {
            initRetryCount++;
            setTimeout(init, 250);
            return;
        }

        try {
            $('[id^="th-inventory"]').remove(); 
            $('[id^="th-fixed"]').remove(); 
            $('#th-detail-popup-ui').remove(); 
            $('.th-drag-helper').remove();

            loadTwemoji();
            loadGoogleFonts();

            if (typeof appendInexistentScriptButtons !== 'undefined') {
                appendInexistentScriptButtons([
                    { name: CONFIG.toggleButtonName, visible: true }
                ]);
            }

            createUI();

            // 监听 iframe 卸载事件，切换角色卡时自动清除残留的 DOM 元素
            window.addEventListener('unload', function() {
                $('[id^="th-fixed"]').remove();
                $('#' + CONFIG.domBallId).remove();
                $('#th-detail-popup-ui').remove();
                removeInfraRoomEditPopup();
                $('.th-drag-helper').remove();
            });

            // 酒馆结构变化（升级/装修）时刷新 infra 面板
            try {
                const onStructChange = () => {
                    if ($('#th-list-infra').is(':visible')) renderInfraBoard();
                    else dirtyTabs.add('infra');
                };
                window.parent.addEventListener('tavern-structure-changed', onStructChange);
                window.parent.addEventListener('tavern-expanded', onStructChange);
                window.parent.addEventListener('tavern-evolution-changed', onStructChange);
            } catch (e) { /* parent 不可访问时忽略 */ }

            bindEvents(); 
            performScan();
            refreshPricePrompt();
            updateUIScale();
            applyNightMode();

            //if(window.toastr) toastr.success('物品栏就绪', '系统');

        } catch (e) {
            alert("脚本错误:\n" + e.message);
            console.error(e);
        }
    }

    $(document).ready(init);
